-- Ten years of The World's 50 Best Bars: every bar on the list (1-100) from
-- 2016 to 2025, plus the 2026 51-100 list, with their places, the special
-- awards, and their signature drinks.
--
-- 1. Closed bars. Many listed bars have shut (Dandelyan, 28 HongKong
--    Street, Operation Dagger and others), but their places and drinks are
--    still worth crediting. profiles.is_closed (with closed_year when known)
--    marks them: they keep their page, awards and drinks, and drop out of
--    near-me, Top bars and the city list.
--
-- 2. 230 more bars as public, unclaimed venue profiles (37 of them
--    closed), same rules as the earlier seeds: a bar already here (same name
--    within 150 m, or the handle taken) is left alone, and each bar claims
--    its profile the usual way. Open bars' points were checked against
--    OpenStreetMap on 29-30 Sep 2026; a closed bar keeps its last address.
--
-- 3. Their places on the list for every year, and the bar awards announced
--    with it (Best New Opening, Legend of the List, Best Bar in <region> and
--    so on), for the new bars and the ones already here: 1181 rows.
--    Titles drop the sponsor ('Nikka Highest Climber Award' is 'Highest
--    Climber'), and the titles the earlier seeds wrote are renamed to match.
--    Awards to a person (Industry Icon, Bartenders' Bartender) come with the
--    people, not here.
--
-- 4. 439 more people as public, unclaimed person profiles: the owners,
--    founders, bar directors and head bartenders the bars or the drinks
--    press name, with 524 positions at these bars (current or former),
--    same rules as the 50 Best people seed (20260929700000): professional
--    details only, in our words, no photos, and people already here get the
--    new positions on their existing profile. Industry Icon and Bartenders'
--    Bartender go on the person.
--
-- 5. 577 signature drinks, shared and credited to the bar they come from,
--    exactly like the city seed: our descriptions, no specs, and a link to
--    the classic they're a version of. Where a source names who made one,
--    it's credited to them too, at 'suggested' until they claim it.

-- --- Closed bars ---

ALTER TABLE "public"."profiles"
    ADD COLUMN "is_closed" boolean DEFAULT false NOT NULL,
    ADD COLUMN "closed_year" smallint CHECK ("closed_year" BETWEEN 1800 AND 2100),
    ADD CONSTRAINT "profiles_closed_is_a_bar" CHECK (NOT "is_closed" OR "kind" = 'bar'),
    ADD CONSTRAINT "profiles_closed_year_when_closed" CHECK ("closed_year" IS NULL OR "is_closed");

-- Signed-out visitors read profiles column by column (20260927000000).
GRANT SELECT ("is_closed", "closed_year") ON "public"."profiles" TO "anon";

-- Near-me and Top bars read bars through here; closed bars stay out.
CREATE OR REPLACE FUNCTION "private"."bars_in_area"(
    "p_latitude" double precision,
    "p_longitude" double precision,
    "p_radius_km" double precision,
    "p_country_code" "text",
    "p_city" "text"
) RETURNS TABLE("id" "uuid", "distance_km" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
    v_radius double precision := least(greatest(coalesce(p_radius_km, 10), 0.1), 200);
    v_dlat double precision;
    v_dlng double precision;
BEGIN
    IF (p_latitude IS NULL) <> (p_longitude IS NULL) THEN
        RAISE EXCEPTION 'A point needs both a latitude and a longitude.' USING ERRCODE = '22023';
    END IF;

    IF p_latitude IS NULL THEN
        RETURN QUERY
        SELECT p.id, NULL::double precision
        FROM public.profiles p
        WHERE p.kind = 'bar' AND p.is_public AND NOT p.is_closed
          AND (p_country_code IS NULL OR p.country_code = upper(p_country_code))
          AND (p_city IS NULL OR lower(p.city) = lower(p_city));
        RETURN;
    END IF;

    IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN
        RAISE EXCEPTION 'That point is off the map.' USING ERRCODE = '22023';
    END IF;

    -- The box around the circle; wider in longitude away from the equator.
    v_dlat := v_radius / 111.045;
    v_dlng := v_radius / (111.045 * greatest(cos(radians(p_latitude)), 0.01));

    RETURN QUERY
    SELECT b.id, b.d
    FROM (
        SELECT p.id, private.distance_km(p_latitude, p_longitude, p.latitude, p.longitude) AS d
        FROM public.profiles p
        WHERE p.kind = 'bar' AND p.is_public AND NOT p.is_closed AND p.latitude IS NOT NULL
          AND p.latitude BETWEEN p_latitude - v_dlat AND p_latitude + v_dlat
          AND (
              v_dlng >= 180
              OR p.longitude BETWEEN p_longitude - v_dlng AND p_longitude + v_dlng
              -- Across the antimeridian.
              OR p.longitude >= p_longitude - v_dlng + 360
              OR p.longitude <= p_longitude + v_dlng - 360
          )
    ) b
    WHERE b.d <= v_radius;
END;
$$;

-- --- The bars ---

INSERT INTO "public"."profiles" ("kind", "handle", "display_name", "bio", "website", "is_public", "locality", "address_line",
                                 "postcode", "city", "region", "country_code", "latitude", "longitude", "is_closed", "closed_year")
SELECT 'bar', v.handle, v.name, v.bio, v.website::text, true, v.locality::text, v.address_line::text,
       v.postcode::text, v.city, v.region::text, v.country_code, v.latitude, v.longitude, v.is_closed, v.closed_year::smallint
FROM (VALUES
    ('frontbackaccra', 'Front/Back', 'Private members'' club and cocktail bar inside The Container art gallery in Osu, Accra, run by co-founders Kojo Aidoo and David Nyamekye. Drinks use Ghanaian and wider African ingredients such as palm wine, prekese and lemongrass, across a restaurant, a library room and a terrace with DJs and live music.', 'https://www.frontbackaccra.com/', 'Osu', 'The Container, First Osu Lane', NULL, 'Accra', NULL, 'GH', 5.56407, -0.17632, false, NULL),
    ('laborrachagh', 'La Borracha', 'Mexican-inspired tequila bar and cantina on Dade Street in Accra, opened in June 2021 and owned by Danny Punjabi. It is known for a long margarita list, a back bar heavy on tequila with a few mezcals, tacos and tortas, and weekly game nights and weekend DJ sets.', 'https://www.laborrachaghana.com/', 'Labone', '11 Dade Street', NULL, 'Accra', NULL, 'GH', 5.575, -0.17272, false, NULL),
    ('flyingdutchmencocktails', 'Flying Dutchmen Cocktails', 'Neo-classic cocktail bar on Singel in Amsterdam''s old centre, opened in 2018 by Tess Posthumus and Timo Janse in a 1662 national monument. It teaches the classics before the riffs, keeps a back bar of 800-plus spirits and serves until 4 am. It is now fully female-owned by Posthumus, Rosa Moolenaar and Alina Lucia.', 'https://www.flyingdutchmencocktails.shop/', 'Centrum', 'Singel 460', '1017 AW', 'Amsterdam', NULL, 'NL', 52.36753, 4.88886, false, NULL),
    ('tales.and.spirits', 'Tales & Spirits', 'Compact, multi-storey cocktail bar and restaurant in a narrow alley off the Singel in central Amsterdam, opened in 2012. Known for storytelling drinks with playful themes and names, antique glassware and a spirits boutique next door, it has been one of the city''s most-awarded cocktail bars.', NULL, 'Centrum', 'Lijnbaanssteeg 5-7', '1012 TE', 'Amsterdam', NULL, 'NL', 52.3761, 4.89179, true, 2026),
    ('barronegroathens', 'Barro Negro', 'Athens'' first tequila and mezcal bar, opened in 2019 by George Kavaklis and Stelios Papadopoulos in the Psyri district. Mexico-inspired drinks built on agave spirits, plus Academia de Barro Negro, an education programme that includes trips to Mexico. It bills itself as the world''s first Paloma Embassy.', 'https://www.barronegroathens.com/', 'Psyri', 'Ioannou Paparrigopoulou 15', '105 61', 'Athens', NULL, 'GR', 37.97848, 23.73075, false, NULL),
    ('naked.athens', 'Naked Athens', 'Minimalist cocktail bar on Agias Irinis Square in Monastiraki, Athens, founded by Thanos Krimpouras and Christina Foka. Sparse stone-and-plain design, clarified and see-through cocktails and a sustainability focus, with a nearby experimental hub for research, workshops and events.', 'https://nakedbarathens.com/', 'Monastiraki', 'Plateia Agias Irinis 2', '105 60', 'Athens', NULL, 'GR', 37.97718, 23.72805, false, NULL),
    ('the_clumsies', 'The Clumsies', 'Multi-room all-day bar in a neoclassical townhouse near Agioi Theodoroi Square in central Athens, opened in 2014 by World Class Greece winners Vasilis Kyritsis and Nikos Bakoulis with three business partners. It runs from daytime coffee to late cocktails and has a private back room for tailored drinks.', 'https://www.theclumsies.gr/', 'Agioi Theodoroi', 'Praxitelous 30', NULL, 'Athens', NULL, 'GR', 37.97897, 23.72983, false, NULL),
    ('americanbargleneagles', 'The American Bar at Gleneagles', 'Hotel cocktail bar at Gleneagles in Perthshire, Scotland, styled as a tribute to the 1920s, the decade the hotel was built. Head bartender Emilio Giovanazzi and his team write themed menus, most recently The Rose Compendium, which pairs drinks around ingredients from the rose family. Open Wednesday to Sunday evenings.', 'https://gleneagles.com/eat-drink/the-american-bar/', 'Gleneagles', 'Gleneagles Hotel', 'PH3 1NF', 'Auchterarder', NULL, 'GB', 56.28341, -3.7524, false, NULL),
    ('drywavecocktailstudio', 'Dry Wave Cocktail Studio', 'Cocktail bar on the second floor of the Sodality community space in Thonglor, opened in January 2024 by bartender Supawit ''Palm'' Muttarattana and Niwarin ''Ae'' Phlainoi. The menu is built on ''super classics'', drinks that fuse two classic cocktails into one. It won the Campari One To Watch Award in 2024 and entered Asia''s 50 Best Bars at No. 5 in 2025.', 'https://www.instagram.com/drywavecocktailstudio/', 'Thonglor', '2nd Floor, Sodality, 263 Thong Lo Soi 13', '10110', 'Bangkok', NULL, 'TH', 13.73371, 100.58067, false, NULL),
    ('god_bkk', 'G.O.D', 'Cocktail bar off Soi Nana in Bangkok''s Chinatown, opened in April 2024 by Niks Anuman-Rajadhon and partners inside two fused shophouses. The name stands for Genius On Drugs. Each drink comes with a small paired bite, the menu has oyster and uni chapters, and a pianist plays at weekends. Part of the group behind Teens of Thailand and Asia Today.', 'https://www.instagram.com/god_bkk/', 'Pom Prap Sattru Phai', '25, 27 Soi Rammaitree', '10100', 'Bangkok', NULL, 'TH', 13.7398, 100.51437, false, NULL),
    ('mahaniyom.cocktailbar', 'Mahaniyom Cocktail Bar', 'Cocktail bar above the 100 Mahaseth restaurant in Bang Rak, opened in March 2022 by bartenders Ronnaporn ''Neung'' Kanivichaporn and Chennarong ''Jan'' Bhumichitr. Its Resourceful Cocktail concept builds each drink around one ingredient and uses every part of it, in a colourful room lit by a neon two-headed tiger.', 'https://www.instagram.com/mahaniyom.cocktailbar/', 'Si Phraya', '2nd Floor, 104 Maha Set Rd', '10500', 'Bangkok', NULL, 'TH', 13.72897, 100.51832, false, NULL),
    ('opm.bkk', 'Opium Bar', 'Speakeasy-style cocktail bar on the top floors of the Potong building in Bangkok''s Chinatown, conceived by restaurateur Arnon ''KK'' Hoontrakul around the idea of ''liquid surreality''. Matteo Cadeddu leads the bar, which serves nearly 50 cocktails and mocktails and four house-made gins. Food comes from the Potong kitchen downstairs.', 'https://opiumbarbangkok.com', 'Yaowarat', '422 Vanich 1 Rd', '10100', 'Bangkok', NULL, 'TH', 13.73921, 100.50848, false, NULL),
    ('rabbitholebkk', 'Rabbit Hole', 'Three-storey Thonglor cocktail bar behind an unmarked wooden door, opened in 2016 with veteran bartenders Suwincha Singsuwan and Naphat Natchachon behind the bar. Known for spirit-forward drinks and a series of themed menus, it became a fixture of Asia''s 50 Best Bars and marked its tenth year in 2026. Noppasate Hirunwathit is head bartender.', 'https://rabbitholebkk.com/', 'Thonglor', '125 Sukhumvit 55 (Thonglor)', '10110', 'Bangkok', NULL, 'TH', 13.7299, 100.58112, false, NULL),
    ('bamboobar.bkk', 'The Bamboo Bar', 'Hotel jazz bar inside the Mandarin Oriental, Bangkok, which dates its official start to 1953 as the city''s first dedicated jazz venue. It moved to its present River Wing room in 1972 and was renovated in 2014-15. Live music plays most nights, and the list pairs the classic Thaijito with newer drinks built on Thai produce.', 'https://www.mandarinoriental.com/en/bangkok/chao-phraya-river/dine/the-bamboo-bar', 'Bang Rak', 'Mandarin Oriental, 48 Oriental Avenue', '10500', 'Bangkok', NULL, 'TH', 13.72392, 100.51415, false, NULL),
    ('tropiccitybkk', 'Tropic City', 'Tropical cocktail bar on Charoen Krung Soi 28 in Bangkok, opened late 2017 by Swedish bartenders Sebastian De la Cruz and Philip Stefanescu. Known for rum-led tiki drinks and music, it helped turn Charoen Krung into a nightlife district. It closed in April 2026 after about eight and a half years, ending with a three-day farewell party.', 'https://www.tropiccitybkk.com/', 'Charoen Krung', '672/65 Charoen Krung Soi 28', '10500', 'Bangkok', NULL, 'TH', 13.73076, 100.51538, true, 2026),
    ('vesperbkk', 'Vesper', 'Cocktail bar on Convent Road in Bangkok''s Silom district, opened in 2014 by Choti and Debby Leenutaphong of Foodie Collection as a restaurant and bar. It dropped the kitchen focus in 2017 to concentrate on drinks, and British bartender Tom Hearn now leads the bar. Vesper was named Legend of the List at Asia''s 50 Best Bars in 2025.', 'https://www.vesperbar.co', 'Silom', '10/15 Convent Road', '10500', 'Bangkok', NULL, 'TH', 13.72704, 100.53344, false, NULL),
    ('boadascocktails', 'Boadas Cocktails', 'Barcelona''s oldest cocktail bar, opened in 1933 just off the Ramblas by bartender Miguel Boadas, who had worked at Havana''s Floridita. Simone Caporale and Marc Alvarez of Sips took it over in late 2022 and restored it, keeping the Art Deco room and the founder''s classic recipes, including the Daiquiri.', 'https://www.boadascocktails.com', 'El Raval', 'Carrer dels Tallers, 1', '08001', 'Barcelona', NULL, 'ES', 41.38466, 2.17027, false, NULL),
    ('dr.stravinsky_bcn', 'Dr. Stravinsky', 'Apothecary-style cocktail bar in Barcelona''s Born district, opened in 2017 by Lito Baldovinos and Enric Rebordosa of Grup Confiteria, with bar manager Antonio Naranjo writing the first menu. Known for its house distillates, ferments and infusions made on site from medicinal plants, and for an unbranded, lab-like back bar.', 'https://drstravinsky.cat', 'El Born', 'Carrer dels Mirallers, 5', '08003', 'Barcelona', NULL, 'ES', 41.38418, 2.18067, false, NULL),
    ('drymartinibarcelona', 'Dry Martini', 'Eixample cocktail bar opened in 1978 as a tribute to the drink that names it, and run since 1996 by Javier de las Muelas. Known for leather, wood and brass, white-jacketed service and a ritual around the Dry Martini, it has a hidden speakeasy restaurant and a counter tallying the martinis it has served.', 'https://www.drymartinibarcelona.com', 'Eixample', 'Carrer d''Aribau, 162-166', '08036', 'Barcelona', NULL, 'ES', 41.39274, 2.154, false, NULL),
    ('foco.bcn', 'FOCO', 'Neighbourhood cocktail bar in Barcelona''s Gràcia, run by English bartenders Tom Godfrey and Theo Quinn, who previously worked at Paradiso and Two Schmucks. The concept borrows from foreign correspondents'' clubs, with guests swapping stories over a menu of rotating house cocktails, classics and bottled drinks.', 'https://www.focobcn.com', 'Gràcia', 'Carrer de l''Encarnació, 52', '08024', 'Barcelona', NULL, 'ES', 41.40656, 2.16042, false, NULL),
    ('solange.barcelona', 'Solange Cocktails & Luxury Spirits', 'Eixample cocktail lounge on Carrer d''Aribau, run by the Pernia family in a jewel-box style room. Its cocktail menu is themed on James Bond films, with drinks named after characters from each one, alongside a long list of rare spirits and a separate whisky menu. Prices sit at the upper end of the city.', 'https://www.solangecocktail.com', 'Eixample', 'Carrer d''Aribau, 143', '08036', 'Barcelona', NULL, 'ES', 41.39224, 2.154, false, NULL),
    ('two.schmucks', 'Two Schmucks', 'Self-styled five star dive bar in Barcelona''s Raval, with graffiti walls and recycled furniture. Co-founder and creative director Moe Aljaff and his team took it to No. 7 in the world in 2022. Aljaff and most of the bar team left that October after a dispute among the owners, so the bar today is a different team from the one that earned the ranking.', NULL, 'El Raval', 'Carrer de Joaquin Costa, 52', '08001', 'Barcelona', NULL, 'ES', 41.38312, 2.16527, false, NULL),
    ('central.station', 'Central Station', 'Boutique cocktail bar on Armenia Street in Beirut''s Mar Mikhael, styled after a railway station in rustic reds and browns with plenty of greenery. It runs an in-house lab for distillates, infusions, fat and milk washes, and pairs its cocktails with an international menu. It has been a regular on the World''s 50 Best Bars list.', 'https://centralstation.bar', 'Mar Mikhael', 'Armenia Street', NULL, 'Beirut', NULL, 'LB', 33.89712, 35.52571, false, NULL),
    ('dead.end.paradise', 'Dead End Paradise', 'Tiki dive bar in Gemmayzeh, Beirut, opened in early 2021 by Jad Ballout, Xin Lin and Andre Gerges after the 2020 port explosion destroyed their first bar, Electric Bing Sutt. The menu splits into a tropical Paradise side and a stranger Dead End side, with Asian and Middle Eastern flavours.', 'https://www.instagram.com/dead.end.paradise/', 'Gemmayzeh', 'Pasteur Street', NULL, 'Beirut', NULL, 'LB', 33.89607, 35.51379, false, NULL),
    ('electricbingsutt', 'Electric Bing Sutt', 'Neon-lit Asian and Middle Eastern all-day bar in a 1920s building in Gemmayze, Beirut, opened in October 2018 by Jad Ballout, Xin Lin and Andre Gerges. It won Best Bar in Middle East and Africa in 2019. The August 2020 port explosion wrecked it, and it never reopened; the team went on to Dead End Paradise.', NULL, 'Gemmayze', 'Gouraud Street', NULL, 'Beirut', NULL, 'LB', 33.895, 35.51231, true, 2020),
    ('buckandbreckberlin', 'Buck & Breck', 'Hidden Berlin speakeasy in Mitte, opened in 2010 by Gonçalo de Sousa Monteiro, who owns it and tends the bar. Found via an unmarked buzzer under a neon closed sign, with a tiny seating group, no phones and short, spirit-led drinks with a historical bent. It also releases its own London dry gin.', 'https://www.buckandbreck.com/', 'Mitte', 'Brunnenstraße 177', '10119', 'Berlin', NULL, 'DE', 52.53213, 13.39904, false, NULL),
    ('velvet.berlin', 'Velvet', 'Neukölln cocktail bar built around foraged and seasonal plants, with a menu that changes weekly and Tuesdays closed for lab work on tinctures, cordials and liqueurs. Led by bar manager Sarah S. Fischer and head bartender Ruben Neideck. Mixology Magazine named it Bar of the Year Germany in 2019 and 2023.', 'https://velvet-bar-berlin.de/', 'Neukölln', 'Ganghoferstraße 1', '12043', 'Berlin', NULL, 'DE', 52.479, 13.4385, false, NULL),
    ('waxonberlin', 'Wax On', 'Neukölln neighbourhood cocktail bar on Weserstraße, opened in 2021 by Sam Orrock, Damien Guichard and Rose-Manon Baux. A basement lab with rotary evaporators and centrifuges feeds a short list of highballs and classics at modest prices, walk-ins only. Mixology named it Bar of the Year Germany in 2024.', 'https://www.instagram.com/waxonberlin/', 'Neukölln', 'Weserstraße 208', '12047', 'Berlin', NULL, 'DE', 52.48815, 13.42988, false, NULL),
    ('lasaladelaura', 'La Sala de Laura', 'Cocktail bar on the upper floor of chef Leonor Espinosa''s restaurant Leo in Bogotá, opened in 2021 as its own space. Led by sommelier and anthropologist Laura Hernández Espinosa, it works with Colombian ecosystems, house Territorio distillates and native ingredients such as coca leaf and cacao.', 'https://restauranteleo.com/en/', 'Chapinero', 'Calle 65bis 4-23', NULL, 'Bogotá', NULL, 'CO', 4.64784, -74.05593, false, NULL),
    ('nuloungebar', 'Nu Lounge Bar', 'Cocktail bar just off Piazza Maggiore in Bologna''s Quadrilatero, founded around 2000 by four friends including Daniele Dalla Pola and for years one of Italy''s best-known tiki bars. It relaunched in September 2025 under new partners as a contemporary cocktail bar, with Vlad Tcaci as bar manager and Flavius Bodescu as head bartender.', 'https://www.nuloungebar.com/', 'Quadrilatero', 'Via de'' Musei 6', '40124', 'Bologna', NULL, 'IT', 44.49299, 11.34467, false, NULL),
    ('antiqueamericanbar_bratislava', 'Antique American Bar', 'Small classics-only cocktail bar in Bratislava''s Old Town, with a mirrored back bar, chandeliers and staff in white jackets. Erik Lorincz, formerly of the American Bar at London''s Savoy, created the drinks list. The menu leans on vintage-style classics, and has paired drinks with photographs by Karol Kallay.', 'https://www.antique-americanbar.com/', 'Staré Mesto', 'Rybárska brána 217/1', '811 01', 'Bratislava', NULL, 'SK', 48.14308, 17.10873, false, NULL),
    ('floreriaatlantico', 'Florería Atlántico', 'Florería Atlántico is a basement cocktail bar in Retiro, reached through a flower shop and a refrigerator door on Arroyo. Renato ''Tato'' Giovannoni opened it in 2013 as a tribute to the immigrants who shaped Argentina, with menus built around their home countries and local spirits. It has since opened sister venues abroad.', 'https://www.floreriaatlantico.com.ar/', 'Retiro', 'Arroyo 872', 'C1007AAB', 'Buenos Aires', NULL, 'AR', -34.59182, -58.37934, false, NULL),
    ('harrison.bsas', 'Nicky Harrison', 'A 1920s-style speakeasy hidden behind the Nicky sushi restaurant in Palermo Soho, entered by password and run with a no-phones rule. Live music, tarot readings and Prohibition-inspired cocktails are part of the night. It opened in the mid-2010s (sources say 2013 or 2014) and is now often simply called Harrison.', 'https://www.instagram.com/harrison.bsas/', 'Palermo Soho', 'Malabia 1764', 'C1414DON', 'Buenos Aires', NULL, 'AR', -34.58969, -58.42559, false, NULL),
    ('presidentebar', 'Presidente', 'Presidente is an elegant cocktail bar in Recoleta, with chandeliers over a long bar, a winter garden and a private library room called La Biblioteca. Bartender Seba García opened it in 2017 with partners, and a second venue followed in San Isidro in 2023. Classic cocktails sit beside house creations and a large whisky selection.', 'https://www.presidentebar.com.ar/', 'Recoleta', 'Avenida Presidente Manuel Quintana 188', 'C1014ACO', 'Buenos Aires', NULL, 'AR', -34.59096, -58.3868, false, NULL),
    ('victoraudiobar', 'Victor Audio Bar', 'Victor Audio Bar is Buenos Aires''s first listening bar, in Palermo Soho, opened in February 2025 by the teams behind Tres Monos and Niño Gordo. It pairs a Martini-led list of classic cocktails and American-style comfort food with vinyl records, a high-fidelity sound system and a headphone jukebox.', 'https://www.instagram.com/victoraudiobar/', 'Palermo Soho', 'Soler 5130', 'C1425BXH', 'Buenos Aires', NULL, 'AR', -34.58378, -58.42904, false, NULL),
    ('causeeffectcpt', 'Cause Effect Cocktail Kitchen', 'Cause Effect is an experiential cocktail kitchen at the V&A Waterfront in Cape Town. Kurt Schlechter opened it in December 2017 and moved it to its Rocket Shed home in 2019. Drinks draw on Cape fynbos, ocean and vineyards, with house-made vermouth, bitters and cordials and a focus on South African brandy.', 'https://causeandeffect.co.za/', 'V&A Waterfront', 'The Rocket Shed, 280 Dock Road', '8001', 'Cape Town', NULL, 'ZA', -33.90522, 18.41924, false, NULL),
    ('the_art_of_duplicity', 'The Art of Duplicity', 'The Art of Duplicity is a hidden 1920s-style speakeasy in an 1894 Victorian warehouse in central Cape Town, opened in October 2018 by David Donde and bartender Brent Perremore. Guests need a booking and a password to get in, and there is live jazz at weekends. It was named South Africa''s Cocktail Bar of the Year in 2020.', 'https://170120.co.za/', 'City Centre', '36 Buitenkant Street', '8001', 'Cape Town', NULL, 'ZA', -33.92814, 18.42261, false, NULL),
    ('thehouseofmachines_cpt', 'The House of Machines', 'The House of Machines is a Cape Town meeting house on Shortmarket Street that combines a cocktail bar with a coffee shop, custom motorbike workshop, menswear store, craft beer list and live music. Founded around 2013, it is known for a barrel-aged Old Fashioned. In late 2026 it announced a move into the adjoining space.', 'https://thehouseofmachines.com/', 'City Centre', '84 Shortmarket Street', '8001', 'Cape Town', NULL, 'ZA', -33.92132, 18.41877, false, NULL),
    ('lab22cardiff', 'Lab 22', 'Lab 22 is a science-themed cocktail bar up a narrow staircase on Caroline Street in Cardiff city centre. Its menus play on scientific ideas, use Welsh-sourced ingredients and link each drink to a QR-code explanation. It won the inaugural World''s Best Cocktail Menu award at The World''s 50 Best Bars in 2021.', 'https://www.lab22cardiff.com/', 'City Centre', '22 Caroline Street', 'CF10 1FG', 'Cardiff', NULL, 'GB', 51.47825, -3.17595, false, NULL),
    ('elbaroncafe', 'El Barón', 'Cocktail bar on Plaza San Pedro Claver in Cartagena''s old town, opened in 2013 in a former handicraft shop inside a family-owned house. It makes its own syrups, infusions and ice, grows herbs on the roof, and runs a sustainability programme. Owner Juan Diaz backs a Colombian team led by bar manager Luna Orellano.', 'https://www.elbaron.co/', 'Centro', 'Carrera 4 #31-7, Plaza San Pedro Claver', '130001', 'Cartagena', NULL, 'CO', 10.42201, -75.55082, false, NULL),
    ('barkumiko', 'Kumiko', 'Japanese dining bar in Chicago''s West Loop that opened on New Year''s Eve 2018 under Julia Momosé, formerly of Oriole. Cocktails blend Japanese and American ingredients, with sake, shochu and Japanese whisky, a spirit-free programme, a dining-room menu, a whisky bar and a weekend cafe. Won the 2025 James Beard Award for Outstanding Bar.', 'https://barkumiko.com/', 'West Loop', '630 W Lake St', '60661', 'Chicago', 'Illinois', 'US', 41.88587, -87.64406, false, NULL),
    ('lostlakechicago', 'Lost Lake', 'Tropical cocktail bar in Chicago''s Logan Square, opened in January 2015 by Paul McGee, formerly of Three Dots and a Dash, and co-owner Shelby Allison. Known for rum-driven drinks, elaborate garnishes and its namesake house cocktail. It dropped the tiki label during the pandemic and closed on 15 January 2022.', NULL, 'Logan Square', '3154 W Diversey Ave', '60647', 'Chicago', 'Illinois', 'US', 41.93213, -87.70712, true, 2022),
    ('aviarycocktails', 'The Aviary', 'Cocktail lounge in Chicago''s Fulton Market from the Alinea Group of chef Grant Achatz and Nick Kokonas, opened in 2011. Bartenders work in a kitchen-style bar with custom ice, bespoke glassware and theatrical serves, offering à la carte drinks and multi-course cocktail tasting menus. The Office speakeasy sits below.', 'https://www.theaviary.com/', 'Fulton Market', '955 W Fulton Market', '60607', 'Chicago', 'Illinois', 'US', 41.88646, -87.65202, false, NULL),
    ('bird.cph', 'Bird', 'Neighbourhood cocktail bar on Gammel Kongevej in Frederiksberg, Copenhagen, run by owner Peter Altenburg of Gilt fame. It opened in 2021 with a bottled-cocktail programme, jazz played on vinyl through custom speakers, and a monthly changing menu. Named 24th on Europe''s 50 Best Bars in 2026.', 'https://birdcph.dk/', 'Frederiksberg', 'Gl. Kongevej 102', '1850', 'Copenhagen', NULL, 'DK', 55.67582, 12.54468, false, NULL),
    ('rubycph', 'Ruby', 'Cocktail bar in a 1740 townhouse on Nybrogade in central Copenhagen, opened on 21 June 2007 in the building where the Danish Spirit Producers was founded in 1882. It has a modern Scandinavian front bar, a darker lounge to the rear and a basement lounge for private hire. Menus mix inventive house cocktails with classics.', 'https://rby.dk/', 'Indre By', 'Nybrogade 10', '1203', 'Copenhagen', NULL, 'DK', 55.67669, 12.57662, false, NULL),
    ('smokeandbitters', 'Smoke & Bitters', 'Beachside cocktail bar and smokehouse in a coconut grove at Hiriketiya on Sri Lanka''s south coast, opened in 2020 by Don Ranasinghe and chef Lahiru Perera. It builds cocktails around local arrack, gins, tea, spices and fruit, alongside wood-fire cooking, and employs a large team from nearby villages.', 'https://www.smokeandbitters.com', 'Hiriketiya', 'Pehebiya Road', NULL, 'Dickwella', NULL, 'LK', 5.96136, 80.70135, false, NULL),
    ('bulgaribardubai', 'Bulgari Bar', 'Hotel bar inside the Bulgari Resort Dubai on Jumeirah Bay Island, also called Il Bar, with beachfront and skyline views and chandeliers shaped like the Bulgari logo. Led by head bartender Dario Schiavoni, it serves Italian-leaning cocktails and shares the property with Il Ristorante Niko Romito.', 'https://www.bulgarihotels.com/en_US/dubai/bars-and-restaurants/il-bar', 'Jumeirah Bay Island', 'Jumeira Bay Island, Jumeira 2', NULL, 'Dubai', NULL, 'AE', 25.21104, 55.23467, false, NULL),
    ('ergo.dubai', 'Ergo', 'Bartender-led cocktail bar and Mediterranean kitchen on the mezzanine of The Dubai EDITION in Downtown Dubai, opened in August 2022 by Jimmy Barrat, formerly global bar development director at Zuma. It had a six-tap draught cocktail station and a UFO-shaped DJ booth. The hotel venue closed in 2023; the Ergo name continued through guest shifts and pop-ups.', NULL, 'Downtown Dubai', 'The Dubai EDITION, Mezzanine floor, Dubai Fountain Street', NULL, 'Dubai', NULL, 'AE', 25.19219, 55.2806, true, 2023),
    ('galaxybardxb', 'Galaxy Bar', 'Intimate late-night cocktail lounge in Dubai''s DIFC, opened in February 2019 by Natasha Sideris of the tashas group as a tribute to Athens. Star-lit ceiling, midnight-blue velvet, Greek Metaxa woven into the drinks, and a programme led by beverage director Krystian Hordejuk.', 'https://www.galaxy-bar.com/', 'DIFC', 'Unit C01, Ground Floor, Gate Village, Building 9', NULL, 'Dubai', NULL, 'AE', 25.21344, 55.28269, false, NULL),
    ('lpmdubai', 'LPM Restaurant & Bar Dubai', 'The Dubai outpost of La Petite Maison, a French Riviera style restaurant in DIFC''s Gate Village that opened in 2010. Its long bar runs nearly a whole wall and is home to the Tomatini. Cocktails come from group beverage director Tibor Krascsenics, including the themed Deja Vu menu.', 'https://lpmrestaurants.com/dubai', 'DIFC', 'Gate Village 08, DIFC', NULL, 'Dubai', NULL, 'AE', 25.21319, 55.28225, false, NULL),
    ('zumadubai', 'Zuma Dubai', 'Bar and lounge of Zuma''s Dubai restaurant in DIFC''s Gate Village, which opened in September 2008. A busy sake and cocktail bar with nightly DJs, it was long the region''s best-ranked bar on the world list. Zuma was founded in London by Rainer Becker.', 'https://www.zumarestaurant.com/en/dubai', 'DIFC', 'Gate Village 06, DIFC', NULL, 'Dubai', NULL, 'AE', 25.21344, 55.28269, false, NULL),
    ('1661bar', 'BAR 1661', 'Independent Dublin cocktail bar on Green Street, opened in April 2019 by Dave Mulligan, founder of the Ban poitin brand. It is built around poitin, the Irish spirit banned from 1661 until 1997, with Irish products across the back bar. Ireland''s Bar of the Year in 2022 and 2025.', 'https://bar1661.ie/', 'Rotunda', '1-5 Green Street', 'D07 YT6H', 'Dublin', NULL, 'IE', 53.34926, -6.27046, false, NULL),
    ('bramble_bar', 'Bramble', 'Edinburgh cocktail bar on Queen Street in the New Town, open since around 2007. Founded by Mike Aikman and Jason Scott, who also run Lucky Liquor Co and The Last Word Saloon and make spirits under the Mothership banner. Walk-in only, with a menu of house liqueur drinks and the Bramble classic it is named after.', 'https://www.bramblebar.co.uk/', 'New Town', '16a Queen Street', 'EH2 1JE', 'Edinburgh', NULL, 'GB', 55.95485, -3.19757, false, NULL),
    ('guccigiardino', 'Gucci Giardino 25', 'Gucci''s cafe and cocktail bar on Piazza della Signoria in Florence, opened on 14 February 2022 beside Gucci Osteria. A small, all-day room in a former florist''s shop, run by bar manager Martina Bonci, with cocktails and alcohol-free drinks built around the memories of her team.', 'https://guccipalazzo.gucci.com/#/en/gucci-giardino-25/', 'Piazza della Signoria', 'Piazza della Signoria 37r', '50122', 'Florence', NULL, 'IT', 43.76995, 11.25671, false, NULL),
    ('backdoorbodega', 'Backdoor Bodega', 'Hidden George Town cocktail bar opened in November 2016 behind a streetwear shop, presenting itself as an overpriced pin shop. Owner-run, with self-taught bartenders and a menu styled as a guide to Penang using local ingredients. Won the World''s Best Cocktail Menu award in 2025.', 'https://www.backdoorbodega.com', 'Sungai Pinang', '37 Jalan Gurdwara', '10300', 'George Town', NULL, 'MY', 5.41234, 100.32808, false, NULL),
    ('boilermaker.goa', 'Boilermaker', 'Dive-bar style neighbourhood bar in Siolim, north Goa, opened in late 2024 by beer entrepreneur Nakul Bhonsle and bartender Pankaj Balachandran. Corrugated steel, a long bar, house beers from Great State Aleworks and short cocktails with local flavours. Ranked No. 8 in Asia''s 50 Best Bars 2026.', 'https://www.instagram.com/boilermaker.goa/', 'Siolim', 'Church Vaddi', '403517', 'Goa', NULL, 'IN', 15.61717, 73.76301, false, NULL),
    ('tesouro.goa', 'Tesouro', 'Neighbourhood bar near Colva beach in south Goa, opened in December 2020 by Donovan Vaz with bartenders Arijit Bose and Pankaj Balachandran of Countertop India. Goan-Portuguese styling, an alfresco area and a back bar of rum, gin, agave spirits and feni. Reached No. 4 in Asia''s 50 Best Bars 2022.', NULL, 'Colva', 'Shop 2, L&L, Florida Gardens, Colva-Benaulim Road, Vaneli', '403708', 'Goa', NULL, 'IN', 15.27074, 73.92824, false, NULL),
    ('elgalloaltanero', 'El Gallo Altanero', 'Agave-focused cocktail bar in Guadalajara''s Colonia Americana, opened in the late 2010s by Freddy Andreasson and Nick Reid. It champions small independent tequila, raicilla and mezcal producers, pours tequila-led cocktails on a rotating menu, and hosts guest bartender takeovers and vinyl nights.', 'https://www.instagram.com/elgalloaltanero/', 'Colonia Americana', 'Calle Marsella 126', '44160', 'Guadalajara', NULL, 'MX', 20.67332, -103.37036, false, NULL),
    ('juliana.gye', 'Juliana', 'Cocktail bar on the top floor of the Museo Nacional del Cacao in Guayaquil''s historic centre, opened in January 2022 by Daniel and Agustín Febres-Cordero with bar director Sarah Ruiz. Its menus are built on Ecuadorian ingredients and producers. It won the 2022 Siete Misterios Best Cocktail Menu award.', 'https://julianabar.com', 'Centro Histórico', 'Imbabura 201 y Panamá, Museo Nacional del Cacao (3rd floor)', '090313', 'Guayaquil', NULL, 'EC', -2.18817, -79.87889, false, NULL),
    ('barlelion', 'Le Lion - Bar de Paris', 'Classic cocktail bar near Hamburg''s town hall, opened in 2007 by Jörg Meyer and restaurateur Rainer Wendt. Meyer created the Gin Basil Smash here in 2008, and the bar bills itself as its cradle. It serves classic cocktails and champagne in a dim, plush room with the Pine Room upstairs.', 'https://www.lelion.net/', 'Altstadt', 'Rathausstraße 3', '20095', 'Hamburg', NULL, 'DE', 53.55017, 9.99457, false, NULL),
    ('darksidehk', 'DarkSide', 'Jazz-age cocktail parlour on level two of Rosewood Hong Kong in Tsim Sha Tsui, opened in March 2019. Its name nods to the Kowloon side of the harbour. It pairs live jazz, rare aged spirits and vintage cigars with classic and locally inspired cocktails, run today by bar manager Marco Maiorano.', 'https://www.rosewoodhotels.com/en/hong-kong/dining/darkside', 'Tsim Sha Tsui', 'Level 2, Rosewood Hong Kong, 18 Salisbury Road', NULL, 'Hong Kong', NULL, 'HK', 22.2947, 114.17581, false, NULL),
    ('lobsterbarhk', 'Lobster Bar', 'Upmarket hotel bar on level six of Island Shangri-La at Pacific Place, Admiralty, beside the Lobster Bar and Grill restaurant. It has nautical touches, live jazz and soul most nights and a cocktail list of classics with Asian twists, plus a wine list and bar snacks.', 'https://www.shangri-la.com/hongkong/islandshangrila/dining/bars-lounges/lobster-bar/', 'Admiralty', 'Island Shangri-La, Level 6, Pacific Place, Supreme Court Road', NULL, 'Hong Kong', NULL, 'HK', 22.27707, 114.16451, false, NULL),
    ('stocktonhk', 'Stockton', 'Hidden Central speakeasy on Wyndham Street, run by Maximal Concepts (Blue Butcher, Brickhouse). Styled as a Victorian London drinking den, it was known for a whisky-heavy back bar and history-minded cocktails. It opened around 2013 and closed on 29 May 2025 after twelve years, with a promise of a future pop-up.', NULL, 'Central', '32 Wyndham Street', NULL, 'Hong Kong', NULL, 'HK', 22.27995, 114.15537, true, 2025),
    ('theoldman_hk', 'The Old Man', 'Hemingway-themed cocktail bar on Aberdeen Street in Soho, opened in July 2017 by Agung Prabowo, Roman Ghale and James Tamang. Every drink is named for a story or moment from the writer''s life. Nikita Matveev now runs operations. A Singapore sister bar followed in 2018.', 'https://theoldmanhongkong.com/', 'Soho', 'Lower G/F, 37 Aberdeen Street', NULL, 'Hong Kong', NULL, 'HK', 22.28278, 114.15171, false, NULL),
    ('thepontiachk', 'The Pontiac', 'Rock and roll dive bar on Old Bailey Street in Soho, founded in 2015 and celebrating ten years in October 2025. It has a jukebox, a lively daily happy hour and bold, fun cocktails, with a mezcal focus under general manager Jen Queen. It is known for an easygoing crowd and its all-female bar team.', NULL, 'Soho', '13 Old Bailey Street', NULL, 'Hong Kong', NULL, 'HK', 22.28158, 114.15354, false, NULL),
    ('thewiseking_hk', 'The Wise King', 'Basement cocktail bar in Hong Kong''s Soho, opened around 2018 by bartenders Joe Villanueva and Sandeep Kumar. Its Spanish and Mediterranean theme nods to Alfonso X of Castile and his rule that drinks come with food, so the menu leans on tapas-style flavours. It launched a new Mediterranean menu in 2025.', 'https://thewisekinghk.com', 'Soho', '25 Staunton Street (basement, Tsung Wing Lane)', NULL, 'Hong Kong', NULL, 'HK', 22.28212, 114.15275, false, NULL),
    ('anvilhouston', 'Anvil Bar & Refuge', 'Montrose cocktail bar in a former tire shop, opened in 2009 by Bobby Heugel and Kevin Floyd. It is widely credited with starting Houston''s craft cocktail scene, with a printed list of 100 classic drinks and a reputation for training bartenders. Heugel added Refuge, an upstairs bar, in 2022. Happy hour returned in 2025.', 'https://anvilhouston.com', 'Montrose', '1424 Westheimer Road', '77006', 'Houston', 'Texas', 'US', 29.74308, -95.39687, false, NULL),
    ('bargabriel.ist', 'Bar Gabriel', 'Walk-in neighbourhood cocktail bar with small bites in Istanbul''s Bostancı, on the Asian side. Founded by bartender Osman Baycan and opened in 2025, it takes cues from historic Silk Road harbour cities and uses local flavours such as künefe and the evil-eye bead. It became Türkiye''s first entry on the 50 Best Bars list in 2026.', 'https://www.instagram.com/bargabriel.ist/', 'Bostancı', 'Turab Sokak 6A', '34744', 'Istanbul', NULL, 'TR', 40.95618, 29.08741, false, NULL),
    ('sin_tax_bar', 'Sin+Tax', 'Rosebank cocktail bar in Johannesburg, opened in December 2016 by restaurateur Shayne Holt with head mixologist Julian Short. It began as a hidden speakeasy behind a pizza restaurant and grew into a courtyard bar with seasonal menus and bottled cocktails made with South African spirits. It was the only African bar on the 2019 list.', 'https://sintaxbar.com/', 'Rosebank', '2 Bolton Road (corner of Jan Smuts Avenue)', '2193', 'Johannesburg', NULL, 'ZA', -26.14915, 28.03506, false, NULL),
    ('tag.cocktails', 'TAG.', 'Cocktail bar in Kraków''s Old Town, opened in July 2020 by Maciej Mazur and Alicja Bączyk-Mazur. Its gallery-style room is themed around graffiti tags, and the menu pairs classics with modern twists. In 2022 it became the first Polish bar on the 50 Best Bars list, and in 2026 it ranked 39th on Europe''s list.', 'https://tagcocktails.com/', 'Old Town', 'Podwale 7/2', '31-118', 'Kraków', NULL, 'PL', 50.06339, 19.93241, false, NULL),
    ('bartrigona', 'Bar Trigona', 'Hotel cocktail bar in the Four Seasons Hotel Kuala Lumpur, named for a stingless bee species that makes prized honey. It focuses on sustainability and local ingredients, and the menu is split into four botanical profiles: fruit, leaf and flower, stem and seed, and root. It won Asia''s 50 Best Sustainable Bar award in 2019.', 'https://www.fourseasons.com/kualalumpur/dining/lounges/bar-trigona/', 'Golden Triangle', 'Four Seasons Hotel Kuala Lumpur, 145 Jalan Ampang', '50450', 'Kuala Lumpur', NULL, 'MY', 3.15809, 101.71368, false, NULL),
    ('penrose.kl', 'Penrose', 'Small cocktail bar on Jalan Petaling in Kuala Lumpur, opened in August 2022 and led by bartender Jon Lee. The menu is built on five basics (alcohol, flavour, taste, body and dilution) and uses seasonal ingredients, with a plain, quiet room and a bar counter. It debuted on Asia''s 50 Best Bars in 2023 and reached No. 10 in 2025.', 'https://www.instagram.com/penrose.kl/', 'City Centre', '149 Jalan Petaling', '50000', 'Kuala Lumpur', NULL, 'MY', 3.14142, 101.69791, false, NULL),
    ('herbsandrye', 'Herbs & Rye', 'Off-Strip Las Vegas steakhouse and cocktail bar opened in 2009 by Nectaly Mendoza. Known for a menu of classic drinks sorted by historical era, from the Gothic Age to Tiki Boom to Revival, each served with a short history lesson. Won a Spirited Award for best American high-volume cocktail bar in 2016.', 'https://www.herbsandrye.com/', 'West Sahara', '3713 W Sahara Ave', '89102', 'Las Vegas', 'Nevada', 'US', 36.1439, -115.19173, false, NULL),
    ('carnavalbar', 'Carnaval', 'Cocktail bar in Lima''s San Isidro opened in January 2018 by bartender Aaron Díaz, the first Peruvian bar on the World''s 50 Best Bars list. Built around conceptual cocktails, Peruvian ingredients and an on-site ice room where blocks are carved for each drink. Díaz left in 2026 and the bar continues under new management.', 'https://carnavalbar.com', 'San Isidro', 'Av. Pardo y Aliaga 662', '15073', 'Lima', NULL, 'PE', -12.10589, -77.03877, false, NULL),
    ('redfrogspeakeasy', 'Red Frog', 'Lisbon speakeasy opened in May 2015 by Emanuel Minêz and Paulo Gomes, widely described as the city''s first. Known for reworked classics built with culinary techniques and Portuguese touches. After the pandemic it moved into a hidden room at the back of sister bar Monkey Mash on Praça da Alegria.', 'https://www.redfrog.pt/', 'Avenida da Liberdade', 'Praça da Alegria 66b', '1250-004', 'Lisbon', NULL, 'PT', 38.71828, -9.14485, false, NULL),
    ('69colebrookerow', '69 Colebrooke Row', 'Small Islington cocktail bar opened in 2009 by Tony Conigliaro and long known as The Bar With No Name. Drinks lean on ingredients made in his Drink Factory lab, from distilled and infused flavours to a Prairie Oyster served in a shell. Live jazz, blues and rock and roll run on several nights.', 'http://www.69colebrookerow.com/', 'Angel', '69 Colebrooke Row', 'N1 8AA', 'London', NULL, 'GB', 51.53649, -0.10104, false, NULL),
    ('amarobarlondon', 'Amaro', 'Kensington cocktail bar that opened in December 2021, founded by former Savoy bartender Elon Soddu. It brings five-star hotel service to a neighbourhood bar, with polished classics, a vintage spirits collection and Italian-leaning small plates. A second site in Earl''s Court was announced for 2023.', 'https://www.amarobar.co.uk/', 'Kensington', '15 Kensington High Street', 'W8 5NP', 'London', NULL, 'GB', 51.50225, -0.1882, false, NULL),
    ('artesianbar', 'Artesian', 'Cocktail bar in The Langham hotel on Portland Place, named after the 360-foot artesian well beneath the building. Designed by David Collins Studio with purple leather chairs, it is a former four-time World''s Best Bar and now runs ingredient-led menus under head bartender Giulia Cuccurullo.', 'https://www.langhamhotels.com/en/the-langham/london/dine/artesian/', 'Marylebone', '1C Portland Place', 'W1B 1JA', 'London', NULL, 'GB', 51.51766, -0.14357, false, NULL),
    ('terminisoho', 'Bar Termini', 'Tiny Italian-style coffee and cocktail bar on Old Compton Street, opened in late 2014 by Tony Conigliaro with Marco Arrigo, then head of quality at Illy. Espresso by day and aperitivo from the afternoon, with a house Negroni in four versions and a short list of classics.', 'https://bar-termini-soho.com/', 'Soho', '7 Old Compton Street', 'W1D 5JE', 'London', NULL, 'GB', 51.51367, -0.12978, false, NULL),
    ('calloohcallaybar', 'Callooh Callay', 'Lewis Carroll-themed Shoreditch cocktail bar opened in November 2008 on Rivington Street by Richard Wynne and Kate Crutchley. Known for playful menus styled as cassette tapes and comic books and for the hidden JubJub bar upstairs. Recent menus, like The Cocktail Thesaurus, sort drinks by flavour pairings.', 'https://calloohcallaybar.com/', 'Shoreditch', '65 Rivington Street', 'EC2A 3AY', 'London', NULL, 'GB', 51.52629, -0.07988, false, NULL),
    ('coupettelondon', 'Coupette', 'A French-leaning neighbourhood cocktail bar in a former pub on Bethnal Green Road, opened in 2017 by Chris Moore. Known for calvados and Champagne serves and a relaxed bistro feel. It took Best New Opening in 2018 and served its last night at this address on 28 June 2026, with a move planned.', 'https://coupette.co.uk/', 'Bethnal Green', '423 Bethnal Green Road', 'E2 0AN', 'London', NULL, 'GB', 51.52727, -0.05913, true, 2026),
    ('dandelyan', 'Dandelyan', 'Botanical cocktail bar at the Mondrian hotel on London''s South Bank, opened in 2014 by Ryan Chetiyawardana (Mr Lyan) with Iain Griffiths. Known for seasonal, plant-led menus and inventive techniques, it topped The World''s 50 Best Bars in 2018 and closed in early 2019, reborn on the same site as Lyaness.', NULL, 'South Bank', '20 Upper Ground', 'SE1 9PD', 'London', NULL, 'GB', 51.50857, -0.10674, true, 2019),
    ('thedonovanbar', 'Donovan Bar', 'The cocktail bar at Brown''s Hotel in Mayfair, named after the fashion photographer Terence Donovan and dressed in 1960s prints and photography-led decor. Known for classic-focused menus with Salvatore Calabrese and for rare vintage serves. Federico Pavan is director of mixology.', 'https://www.roccofortehotels.com/hotels-and-resorts/brown-s-hotel/dining/donovan-bar/', 'Mayfair', '33 Albemarle Street', 'W1S 4BP', 'London', NULL, 'GB', 51.50908, -0.14217, false, NULL),
    ('happiness_hoxton', 'Happiness Forgets', 'An unmarked basement cocktail bar on Hoxton Square, opened in 2010 by Alastair Burgess. Brick walls, candlelight and a no-nonsense, friendly approach set the tone, with a short list of well-made drinks. It has a sister bar, No Nuisance, in St Albans.', 'https://www.happinessforgets.com/', 'Hoxton', 'Basement, 8-9 Hoxton Square', 'N1 6NU', 'London', NULL, 'GB', 51.52789, -0.08164, false, NULL),
    ('nightjar', 'Nightjar', 'A 1920s-style basement speakeasy on City Road, opened in late 2010 by Edmund Weil and Roisin Stimpson. Known for historic and inventive cocktails made with rare spirits, and live jazz, blues and swing every night. It celebrated fifteen years in 2025. Its West End sequel closed in September 2025.', 'https://www.barnightjar.com/', 'Shoreditch', '129 City Road', 'EC1V 1JB', 'London', NULL, 'GB', 51.52648, -0.08775, false, NULL),
    ('theoriolebar', 'Oriole', 'A speakeasy-style bar with live music from the team behind Nightjar. It opened in 2015 in Smithfield Market, closed there in December 2022, and reopened in August 2024 in Covent Garden with a basement restaurant and a ground-floor Bamboo Bar for aperitifs and draft cocktails. Founded by Edmund Weil and Roisin Stimpson.', 'https://www.oriolebar.com/', 'Covent Garden', '7-9 Slingsby Place', 'WC2E 9AB', 'London', NULL, 'GB', 51.51265, -0.12634, false, NULL),
    ('punchroomldn', 'Punch Room', 'A clubby, oak-panelled cocktail room inside The London EDITION hotel in Fitzrovia, opened in 2013 with the hotel. Dedicated to punch and shared serves, with drinks brought to the table in bowls, and menus that rework classics. Anthony Callegari is bars manager.', 'https://www.editionhotels.com/london/restaurants-and-bars/punch-room/', 'Fitzrovia', '10 Berners Street', 'W1T 3NP', 'London', NULL, 'GB', 51.51678, -0.13605, false, NULL),
    ('sagerandwilde', 'Sager + Wilde', 'Wine bar in a former pub on Hackney Road, founded by Michael Sager and Charlotte Wilde after a successful pop-up. Known for a long by-the-glass wine list, cold snacks and a signature grilled cheese toastie. Sager now runs it as sole owner and it also has its own importing arm, Sager and Wine.', 'https://www.sagerandwilde.com/', 'Hackney', '193 Hackney Road', 'E2 8JL', 'London', NULL, 'GB', 51.53099, -0.07213, false, NULL),
    ('scoutldn', 'Scout', 'Sustainability-led cocktail bar founded by Matt Whiley, known for drinks built on foraged and seasonal British ingredients and a low-waste kitchen. It opened on Great Eastern Street in 2017, moved to Graham Road in Hackney in 2018 with a keg-cocktail basement, Gold Tooth, and closed for good in July 2021.', NULL, 'Hackney', '224 Graham Road', 'E8 1BP', 'London', NULL, 'GB', 51.54656, -0.05613, true, 2021),
    ('thegibsonbar', 'The Gibson', 'A tiny green-tiled corner bar on Old Street, opened in 2015 by former Nightjar bar manager Marian Beke with Rusty Cerven. Famous for its Gibson with house-pickled onions and theatrical garnishes and glassware, and a long menu of monthly-themed drinks. It closed in March 2023 when its lease ended.', NULL, 'Clerkenwell', '44 Old Street', 'EC1V 9AQ', 'London', NULL, 'GB', 51.52393, -0.09632, true, 2023),
    ('threesheetsbars', 'Three Sheets Dalston', 'Neighbourhood cocktail bar on Kingsland Road opened in 2016 by brothers Max and Noel Venning. Its menu is sorted into One, Two and Three Sheets by flavour intensity, with clean, seasonal drinks and pre-batched serves such as a carbonated French 75. The brothers opened a second bar in Soho in 2024.', 'https://www.threesheets-bar.com/dalston', 'Dalston', '510b Kingsland Road', 'E8 4AB', 'London', NULL, 'GB', 51.54393, -0.07584, false, NULL),
    ('untitledbar', 'Untitled', 'Dalston cocktail bar opened in February 2017 by Tony Conigliaro, his third after 69 Colebrooke Row and Bar Termini. Styled after Warhol''s Silver Factory, with foil walls, a 20-seat communal table and twelve single-word cocktails from the Drink Factory built on unusual ingredients. It has since closed.', NULL, 'Dalston', '538 Kingsland Road', 'E8 4AH', 'London', NULL, 'GB', 51.54466, -0.07565, true, NULL),
    ('viajantebar', 'Viajante87', 'Basement cocktail bar under Notting Hill Gate from Thesleff Group, the team behind the Los Mochis restaurants. Menu inspired by Latin America is split into comfortable, curious and courageous drinks, with resident DJs playing Latin, disco, house and funk at weekends. Nut and gluten free kitchen.', 'https://viajantebar.com', 'Notting Hill', '87 Notting Hill Gate', 'W11 3JZ', 'London', NULL, 'GB', 51.50877, -0.19732, false, NULL),
    ('whitelyan', 'White Lyan', 'Ryan Chetiyawardana''s first bar, on Hoxton Street, run without ice, fresh citrus or branded spirits. Pre-made cocktails were kept in fridges in place of a back bar and the menu was fixed. It closed in 2017 and the site became the Cub restaurant, with the Super Lyan bar below.', NULL, 'Hoxton', '153 Hoxton Street', 'N1 6PJ', 'London', NULL, 'GB', 51.53135, -0.08035, true, 2017),
    ('deathandcompany.la', 'Death & Co Los Angeles', 'Los Angeles outpost of the New York cocktail bar, in a subterranean space in the Arts District that opened at the end of 2019. A 25-drink menu is sorted by style, with a walk-up bar, Standing Room, at the entrance. Run by owners David Kaplan and Alex Day with beverage director Tyson Buhler.', 'https://www.deathandcompany.com/location/dtla/', 'Arts District', '818 E 3rd Street', '90013', 'Los Angeles', 'California', 'US', 34.04572, -118.23572, false, NULL),
    ('mirate.losangeles', 'Mírate', 'Multi-level Mexican restaurant and agave bar in Los Feliz, opened in late 2022 by restaurateur Matthew Egan and chef Joshua Gil. Beverage director Max Reis runs a list built on small-producer Mexican spirits, pulque and ancestral drinks, with a dedicated mezcaleria and house-canned cocktails.', 'https://www.mirate.la/', 'Los Feliz', '1712 N Vermont Ave', '90027', 'Los Angeles', 'California', 'US', 34.1022, -118.29164, false, NULL),
    ('spareroomhwood', 'The Spare Room', 'Cocktail lounge and gaming parlour on the mezzanine of the Hollywood Roosevelt hotel, opened in 2011 with two vintage bowling lanes. Under Yael Vengroff it won Time Out LA''s 2016 Bar of the Year; it reopened in late 2021 with Tess Anne Sawyer''s new list.', 'https://www.thehollywoodroosevelt.com/menu/spareroom/', 'Hollywood', '7000 Hollywood Blvd', '90028', 'Los Angeles', 'California', 'US', 34.10103, -118.34168, false, NULL),
    ('thewalkerinn', 'The Walker Inn', 'Hidden 27-seat cocktail room behind the Normandie Club in Koreatown, opened in May 2015 by Proprietors LLC (Alex Day, David Kaplan, Devon Tarby) with 213 Hospitality. Known for themed, reservation-only cocktail omakase menus that changed every six to eight weeks. It has since closed; the Normandie Club remains.', NULL, 'Koreatown', '3612 W 6th St', '90020', 'Los Angeles', 'California', 'US', 34.06344, -118.30072, true, 2019),
    ('thunderboltla', 'Thunderbolt', 'Southern-inspired neighbourhood cocktail bar at the meeting point of Echo Park, Historic Filipinotown and downtown LA, opened in 2019 by Mike Capoferri, chef Johneric Concordia and Rahul Marwah. Known for technology-driven, low-waste drinks, an extensive Madeira collection and on-site canned cocktails.', 'https://www.thunderboltla.com/', 'Echo Park', '1263 W Temple St', '90026', 'Los Angeles', 'California', 'US', 34.06632, -118.25412, false, NULL),
    ('1862drybar', '1862 Dry Bar', 'Malasaña cocktail bar founded by former industrial engineer Alberto Martínez. Named for 1862, the year of Jerry Thomas''s first bartender''s guide and of the building itself. The list draws on Thomas-era recipes and classic technique, with a set of house signatures beside them.', 'https://www.instagram.com/1862drybar/', 'Malasaña', 'Calle del Pez, 27', '28004', 'Madrid', NULL, 'ES', 40.42414, -3.7066, false, NULL),
    ('madridangelita', 'Angelita', 'Wine bar, restaurant and basement cocktail room in Chueca, opened in 2016 by brothers David (wine) and Mario Villalón (cocktails). Known for ice-free, ingredient-led drinks made with produce from the family farm in Zamora. Won Best Cocktail Bar in Spain at FIBAR 2021.', 'https://madrid-angelita.es/es/', 'Chueca', 'Calle de la Reina, 4', '28004', 'Madrid', NULL, 'ES', 40.42035, -3.70037, false, NULL),
    ('savasbarmad', 'Savas Bar', 'Small cocktail bar in Lavapiés run by Lithuanian couple Gintautas Arlauskas and Dovile Krauzaite, who are also its only staff. Opened around 2019, it serves a short printed list of classics with a Nordic twist in a white-tiled room. Won the Madrid gastronomy academy''s bars award in 2021.', 'https://www.instagram.com/savasbarmad/', 'Lavapiés', 'Calle de la Sombrerería, 3', '28012', 'Madrid', NULL, 'ES', 40.40759, -3.69963, false, NULL),
    ('schofields.bar', 'Schofield''s Bar', 'Art Deco cocktail bar in Manchester''s Sunlight House, opened in April 2021 by brothers Joe and Daniel Schofield. Built around 12 fixed classics plus rotating seasonal drinks, served by white-coated staff. UK Bar of the Year at the CLASS awards in 2022 and 2024. A second bar in Covent Garden is due in late 2026.', 'https://www.schofieldsbar.com/', 'Spinningfields', 'Sunlight House, 3 Little Quay Street', 'M3 3JZ', 'Manchester', NULL, 'GB', 53.47867, -2.25091, false, NULL),
    ('carmenrestaurante', 'Bar Carmen', 'Bar inside Carmen, the El Poblado restaurant that chef Carmen Ángel and Rob Pevitts started in 2008. Bar director Maycoll Tobón builds cocktails from Colombian regional ingredients, from Andean herbs to native fruits and ancestral spirits, with culinary techniques and a low-waste approach.', 'https://carmenmedellin.com/en/', 'El Poblado', 'Carrera 36 #10A-27', NULL, 'Medellín', NULL, 'CO', 6.21005, -75.5656, false, NULL),
    ('mambanegra.22', 'Mamba Negra', 'Rooftop bar and ember-cooking restaurant on the 22nd floor of the Q Office building in El Poblado. Founded by bartender Juan David Zapata, it is built around a large oval bar and cocktails made with Colombian spirits and ingredients. Mamba Lab, a separate eight-drink tasting, opened in 2025.', 'https://mambanegra.co/', 'El Poblado', 'Calle 2 #20-50, piso 22', NULL, 'Medellín', NULL, 'CO', 6.19632, -75.55493, false, NULL),
    ('byrdimelb', 'Byrdi', 'Melbourne CBD cocktail bar opened in October 2019 by Luke Whearty and Aki Nishikura, previously behind Operation Dagger in Singapore. It served drinks built on native Australian ingredients, an ever-changing Martini and Japanese-leaning food, and closed in September 2026 after about seven years.', 'https://www.byrdi.com.au/', 'Melbourne CBD', '211 La Trobe Street', '3000', 'Melbourne', 'Victoria', 'AU', -37.81033, 144.96196, true, 2026),
    ('theeverleigh', 'The Everleigh', 'Upstairs classic cocktail bar on Gertrude Street, Fitzroy, opened in July 2011 by Michael Madrusan with Sasha Petraske and Lauren Schell; Zara Madrusan joined in 2013. Known for bartender''s choice, fresh juice per drink and hand-cut ice. It closed in March 2025 after debts from the Covid years.', NULL, 'Fitzroy', 'Level 1, 150-156 Gertrude Street', '3065', 'Melbourne', 'Victoria', 'AU', -37.8062, 144.97968, true, 2025),
    ('baltrabar', 'Baltra Bar', 'Relaxed Condesa cocktail bar from the Licorería Limantour group, themed around Charles Darwin and the Galápagos island it is named for. Beverage director José Luis León rewrites the menu each season, with a warm, neighbourhood feel and a mix of playful and refined drinks. It opened about a decade ago.', 'https://baltra.bar/', 'Hipódromo Condesa', 'Iztaccíhuatl 36D', '06100', 'Mexico City', NULL, 'MX', 19.40952, -99.16884, false, NULL),
    ('barmauromx', 'Bar Mauro', 'Italian aperitivo bar in Roma Norte that opened in October 2024, run by brothers Ricardo and Eduardo Nava in honour of their grandfather Mauro Mendoza. A 1970s Milan look, low-ABV drinks and a well-known cheeseburger. Won the Campari One To Watch Award in 2025.', 'https://www.instagram.com/barmauromx/', 'Roma Norte', 'Tabasco 149', '06700', 'Mexico City', NULL, 'MX', 19.41937, -99.15932, false, NULL),
    ('brujasmex', 'Brujas', 'All-women-run cocktail bar in Roma Norte, set inside the 1908 building known as the Casa de las Brujas. Owner Walter Meyenberg opened it in 2019. The list draws on Mexican herbalism and honours women writers, activists and witches from history, and menus are presented as illustrated stories.', NULL, 'Roma Norte', 'Calle Río de Janeiro 56, Local B', '06700', 'Mexico City', NULL, 'MX', 19.42121, -99.15979, false, NULL),
    ('fiftymils', 'Fifty Mils', 'Hotel cocktail bar inside the Four Seasons Mexico City on Paseo de la Reforma, with an indoor lounge and a garden courtyard. Its menus lean on Mexican spirits such as tequila, mezcal and sotol. It relaunched its list in 2022 under bar manager Nico Castro and was ranked fourth among the world''s hotel bars by Food & Wine in 2025.', 'https://www.fourseasons.com/mexico/dining/lounges/fifty_mils/', 'Juárez', 'Paseo de la Reforma 500', '06600', 'Mexico City', NULL, 'MX', 19.42266, -99.17391, false, NULL),
    ('fomabar.mx', 'Form + Matter', 'Roma Norte cocktail bar and working lab, known as FO+MA, opened in late 2024 by Handshake alumni David Rocha and José Olivas with restaurateur Po Tsai. A rotovap and centrifuge sit in the room, and drinks use clarification, fat-washing and byproduct reuse. It entered the 50 Best list in 2026.', 'https://fomabar.com/', 'Roma Norte', 'San Luis Potosí 37', '06700', 'Mexico City', NULL, 'MX', 19.41481, -99.15647, false, NULL),
    ('hankypankydf', 'Hanky Panky', 'Hidden speakeasy in Colonia Juárez, entered through an adjoining Oaxacan restaurant. Owner Walter Meyenberg opened it in 2016 with bartenders Gina Barbachano and Ismael Martínez, who later became partners. Known for travel-themed menus, guest-bartender takeovers and taking its team on tour to bars abroad.', 'https://www.hankypanky.mx', 'Juárez', 'Turín 52', '06600', 'Mexico City', NULL, 'MX', 19.42704, -99.15565, false, NULL),
    ('kaitodelvalle', 'Kaito del Valle', 'Japanese izakaya and cocktail bar founded in 2016 as the first bar in Latin America run entirely by women, co-founded by Claudia Cabrera. It left its original Del Valle home and reopened in August 2025 in Colonia Juárez, with a vending-machine entrance. Known for sake-led drinks, anime-inspired menus and custom glassware.', 'https://www.kaitodelvalle.com', 'Juárez', 'Hamburgo 70B', '06600', 'Mexico City', NULL, 'MX', 19.42707, -99.16244, false, NULL),
    ('limantourmx', 'Licorería Limantour', 'Roma Norte cocktail bar that opened in April 2011 and is widely credited with starting Mexico City''s modern cocktail era. Founded by Benjamin Padrón and run by bar manager José Luis León from a two-story art deco building, with a Polanco branch added in 2013. Known for drinks built on Mexican ingredients.', 'https://limantour.tv', 'Roma Norte', 'Álvaro Obregón 106', '06700', 'Mexico City', NULL, 'MX', 19.41813, -99.15941, false, NULL),
    ('rayocdmx', 'Rayo', 'Cocktail bar in a Porfirian-style mansion in Roma Norte, opened in January 2022 by founder Víctor Garibay. Built around the myth of Mayahuel and Mexican spirits such as mezcal, sotol, charanda and pox, with a multi-cocktail tasting menu and a scent-led menu. Named Best New Opening at North America''s 50 Best in 2023.', 'https://rayococktailbar.com', 'Roma Norte', 'Salamanca 85', '06700', 'Mexico City', NULL, 'MX', 19.41823, -99.16955, false, NULL),
    ('cafelatrovamiami', 'Café La Trova', 'Cuban cantinero-style bar and restaurant in Little Havana, opened in 2019 by Julio Cabrera with chef Michelle Bernstein, David Martinez and Orestes Pajón. Known for thrown Hotel Nacionals, classic Cuban cocktails, live trova music and a Cuban menu from Bernstein''s kitchen. Ranked No. 42 on North America''s 50 Best in 2026.', 'https://www.cafelatrova.com', 'Little Havana', '971 SW 8th Street', '33130', 'Miami', 'Florida', 'US', 25.76618, -80.21047, false, NULL),
    ('sweetlibertymia', 'Sweet Liberty Drinks & Supply Company', 'South Beach cocktail bar near the Bass Museum in Collins Park, opened in 2015 by bartender John Lermayer, Dan Binkiewicz and David Martinez, with chef Michelle Bernstein. Known for high-volume craft cocktails and late-night hours. Miami-Dade proclaimed Sweet Liberty Day in June 2026.', 'https://www.mysweetliberty.com', 'Collins Park', '237 20th Street', '33139', 'Miami Beach', 'Florida', 'US', 25.79612, -80.12978, false, NULL),
    ('brokenshaker', 'The Broken Shaker', 'Garden cocktail bar in the courtyard of the Freehand hotel in Miami Beach. Gabriel Orta and Elad Zvi of Bar Lab started it as a pop-up in 2011 and it became permanent in 2012. Known for cocktails using herbs grown on site. The founders sold in 2024 and Authentic Hospitality now runs it, with sister bars in other US cities.', 'https://www.brokenshaker.com', 'Indian Creek', '2727 Indian Creek Drive', '33140', 'Miami Beach', 'Florida', 'US', 25.80462, -80.12641, false, NULL),
    ('camparinoingalleria', 'Camparino in Galleria', 'Historic Milan aperitivo bar founded by Davide Campari in 1915 inside the Galleria Vittorio Emanuele II, beside the Duomo. It has a street-level bar di passo, the Sala Spiritello and the by-reservation Sala Gaspare, with Tommaso Cecca leading the bar. Known for Campari-led classics and a menu with one drink per decade of its history.', 'https://www.camparino.com/', 'Duomo', 'Piazza del Duomo 21', '20121', 'Milan', NULL, 'IT', 45.46492, 9.18988, false, NULL),
    ('cera_milano', 'Cera & Bruno Vanzan', 'Cocktail bar opened in June 2021 on the ground floor of Cera, a two-floor multi-concept venue at Via Sirtori 34 near Porta Venezia. Champion bartender Bruno Vanzan fronted the drinks, with Mario Farulla as general manager. Its 17.5 metre open bar was built around the idea of guests watching drinks being made.', NULL, 'Porta Venezia', 'Via Giuseppe Sirtori 34', '20129', 'Milan', NULL, 'IT', 45.47498, 9.20683, false, NULL),
    ('dariocomini', 'Nottingham Forest', 'Family-run Milan cocktail bar at Viale Piave 1, opened in 1970 by Carlo Comini and led since 1980 by his son Dario. A pioneer of molecular and barchef mixology in Italy, with tropical travel-trinket decor, a rum-heavy back bar, a walk-in-only door policy and a counter reclaimed from New York''s Knickerbocker Hotel.', 'https://www.nottingham-forest.com/', 'Porta Monforte', 'Viale Piave 1', '20129', 'Milan', NULL, 'IT', 45.46872, 9.20671, false, NULL),
    ('officina_milano', 'Officina Milano', 'Cocktail lounge in a hidden courtyard of former workshops near the Navigli, opened in June 2016 by Giorgio Santambrogio and motorbike-workshop owner Raffaello Polchi. Vintage motorcycles and cars set a 1950s Milan mood; the bar is known for classics reworked with house-made ingredients and a Sunday brunch.', 'https://www.instagram.com/officina_milano/', 'Ticinese', 'Via Giovenale 7', '20136', 'Milan', NULL, 'IT', 45.44991, 9.1844, false, NULL),
    ('le_parfum_montpellier', 'Le Parfum', 'Montpellier cocktail bar and dim sum kitchen in the Beaux-Arts quarter, opened by London-trained bartender Sacha Molodskikh, who became known for sculpted-ice serves. Red lanterns and an illuminated bar set the scene; the menu is themed on scent and changes seasonally. Open Tuesday to Saturday evenings.', 'https://www.barleparfum.com/', 'Beaux-Arts', '55 bis rue de la Cavalerie', '34090', 'Montpellier', NULL, 'FR', 43.61809, 3.88207, false, NULL),
    ('chainayateandcocktails', 'Chainaya. Tea & Cocktails', 'Hidden basement bar near Belorusskaya metro in a former Chinese tea room, opened in 2011 by bartender Roman Milostivy. Vermouth-forward classics, tea and Chinese food in a dim opium-den style, entry by phone reservation. Konstantin Plesovskikh now co-owns it, and it marked its 15th year in 2026.', 'http://chainaya.org/', 'Tverskoy', '1st Tverskaya-Yamskaya Street 29, building 1', '125047', 'Moscow', NULL, 'RU', 55.77595, 37.5852, false, NULL),
    ('insider.bar.lab', 'Insider Bar', 'Futuristic cocktail lab bar on Sretenka in Moscow, opened in 2021 within the Galaktion and Elina Tabidze restaurant group. Rammed-earth walls, Baccarat crystal and a custom bar station built with Behind Bars of Oslo. Alexandr Tsurkan runs the bar; open Thursday to Saturday nights.', 'https://insiderbar.com/', 'Meshchansky', 'Sretenka Street 22/1, building 1', NULL, 'Moscow', NULL, 'RU', 55.76946, 37.63243, false, NULL),
    ('circle.bar.munich', 'Circle by Cihan Anadologlu', 'Oval craft cocktail bar on the first floor of the Hearthouse members club in Munich''s former stock exchange on Lenbachplatz, co-owned by bartender Cihan Anadologlu. It won the Fizzz Award for Most Innovative Bar in 2016 and reached Drinks International''s Top 100. Anadologlu left in 2020.', NULL, 'Maxvorstadt', 'Lenbachplatz 2a', '80333', 'Munich', NULL, 'DE', 48.14092, 11.56771, true, 2020),
    ('schumanns_house', 'Schumann''s Bar am Hofgarten', 'Charles Schumann''s Munich bar, opened in 1982 on Maximilianstrasse and at Odeonsplatz beside the Hofgarten since 2003. It runs from breakfast to late night as a classic-cocktail bar and restaurant, and grew into a small family of Schumann''s venues.', 'https://schumanns.de/en/schumanns-bar.html', 'Altstadt-Lehel', 'Odeonsplatz 6-7', '80539', 'Munich', NULL, 'DE', 48.14393, 11.57862, false, NULL),
    ('hero_nairobi', 'Hero Bar', 'Comic-book-themed rooftop bar on the ninth floor of the Trademark Hotel in Gigiri, Nairobi, opened in 2019 by Tribe Hotels Group co-founder Shamim Ehsani. Drinks are sorted into heroes, sidekicks and villains, with Kenyan ingredients and a Japanese-inspired food menu.', 'https://www.hero-kenya.com', 'Gigiri', '9th Floor, Trademark Hotel, Limuru Road, Village Market', NULL, 'Nairobi', NULL, 'KE', -1.23069, 36.80404, false, NULL),
    ('lantiquario_napoli', 'L''Antiquario', 'Speakeasy-style cocktail bar in Naples'' Chiaia district, opened in October 2015 by bartender Alex Frezza and partners. Art-nouveau wallpaper, red velvet and a backlit back bar set the scene for classics and house creations, plus a big champagne list.', 'https://lantiquarionapoli.superbexperience.com/', 'Chiaia', 'Via Vannella Gaetani 2', '80121', 'Naples', NULL, 'IT', 40.83296, 14.24224, false, NULL),
    ('lamp.bar', 'Lamp Bar', 'Nara cocktail bar opened in December 2011 by Michito Kaneko, winner of Diageo World Class in 2015. Three themed rooms follow a spirits-around-the-world idea, and there is no printed menu: drinks are made to the guest, often with Nara ingredients.', 'https://www.lamp-bar.com/', 'Tsunofuri-cho', '1F Iseya Building, 26 Tsunofuri-cho', '630-8224', 'Nara', NULL, 'JP', 34.68243, 135.82703, false, NULL),
    ('mr.hoots', 'Hoots''', 'Small, dim speakeasy tucked below the wine bar Perch in Vasant Vihar, New Delhi. Its short list of reworked classics is known for numbered drink names, an Old Fashioned with miso and a Whisky Sour with chamomile foam. Cigars and cheese boards are on the side.', 'https://www.instagram.com/mr.hoots/', 'Vasant Vihar', '18-A, 1st Floor, Basant Lok Market', '110057', 'New Delhi', NULL, 'IN', 28.55898, 77.16418, false, NULL),
    ('lair.newdelhi', 'Lair', 'Modernist speakeasy in Basant Lok Market, Vasant Vihar, New Delhi, with cocktails on one level and pan-Asian dining on another. The black concrete and glass interior by studio Renesa nods to film noir, and drinks lean on Indian ingredients.', 'https://www.lairdelhi.com', 'Vasant Vihar', '15 Market, Basant Lok', '110057', 'New Delhi', NULL, 'IN', 28.55898, 77.16418, false, NULL),
    ('sidecarindia', 'Sidecar', 'Two-level Delhi bar opened in 2018 by Yangdup Lama and Minakshi Singh, the team behind Cocktails & Dreams Speakeasy. A Hachette bookshop and Subko coffee sit downstairs, with a wood-panelled cocktail bar, live music and yearly signature menus upstairs.', 'https://www.sidecarindia.com', 'Greater Kailash II', 'M-29, First Floor, M Block Market', '110048', 'New Delhi', NULL, 'IN', 28.53441, 77.24378, false, NULL),
    ('amoryamargo', 'Amor y Amargo', 'East Village bar opened in 2011 by Ravi DeRossi and Sother Teague as the first bar in the US built around bitters. It pours aromatic bitters, Italian amari and fortified wines, and has been a reference point for the amaro revival. It closed at the end of 2023 and is back at the same address.', 'https://www.amoryamargo.com', 'East Village', '443 E 6th Street', '10009', 'New York', 'New York', 'US', 40.7257, -73.98426, false, NULL),
    ('angelssharenyc', 'Angel''s Share', 'Japanese-style, walk-in-only cocktail bar founded in 1993 in the East Village by Tony Yoshida, an early influence on New York''s craft cocktail revival. The original closed in 2022 when its lease ended. It reopened in 2023 in a West Village townhouse basement at 45 Grove Street, run by Erina Yoshida, with the old angel mural.', 'https://www.angelssharenyc.com/', 'West Village', '45 Grove Street', '10014', 'New York', 'New York', 'US', 40.73301, -74.00433, false, NULL),
    ('bargoto_nyc', 'Bar Goto', 'Japanese-minded cocktail bar on the Lower East Side, opened in 2015 by Kenta Goto after his years at Pegu Club. A small, walk-in room known for the Sakura Martini, shochu and sake drinks, and okonomiyaki. A second bar, Bar Goto Niban, followed in Brooklyn.', 'https://www.bargoto.com/', 'Lower East Side', '245 Eldridge Street', '10002', 'New York', 'New York', 'US', 40.72276, -73.98986, false, NULL),
    ('blacktailnyc', 'BlackTail', 'Havana-themed rum bar from Sean Muldoon and Jack McGarry of The Dead Rabbit. It opened in July 2016 on the second floor of Pier A Harbor House in Battery Park, recreating a 1920s Cuban bar with a long list of daiquiris, mojitos and Cuban classics. It closed after service on 11 January 2020.', NULL, 'Battery Park', '22 Battery Place (Pier A Harbor House)', '10004', 'New York', 'New York', 'US', 40.70441, -74.0179, true, 2020),
    ('cloverclubny', 'Clover Club', 'Victorian-style cocktail bar on Smith Street in Brooklyn, opened in 2008 by Julie Reiner and Susan Fedroff. Known for classic and seasonal cocktails, a back room with a fireplace, weekend brunch and its namesake gin-raspberry sour. In 2024 the team opened a casual sibling, The Saloon, next door.', 'https://www.cloverclubny.com/', 'Cobble Hill, Brooklyn', '210 Smith Street', '11201', 'New York', 'New York', 'US', 40.68457, -73.99208, false, NULL),
    ('dantenewyorkcity', 'Dante', 'Greenwich Village aperitivo bar in a landmark building that has served the block as Caffe Dante since 1915. Linden Pride and Nathalie Hudson took it over in 2015 and made it known for its negroni page, Garibaldis and a sit-down cafe feel. It was named The World''s Best Bar in 2019.', 'https://www.dante-nyc.com/', 'Greenwich Village', '79-81 MacDougal Street', '10012', 'New York', 'New York', 'US', 40.72879, -74.00166, false, NULL),
    ('dearirving', 'Dear Irving', 'Cocktail bar at 55 Irving Place in Gramercy, laid out as a railroad of period-themed rooms including a Victorian parlour and an Art Deco lounge. It comes from the team behind Raines Law Room, with cocktails curated by bar director Meaghan Dorman, and has since added sites in Hell''s Kitchen and on Broadway.', 'https://www.dearirving.com/', 'Gramercy', '55 Irving Place', '10003', 'New York', 'New York', 'US', 40.73614, -73.98741, false, NULL),
    ('deathandcompany', 'Death & Co', 'East Village cocktail bar that opened on New Year''s Eve 2006, widely credited with helping start the craft cocktail movement. It is known for a long, creative menu and the book Death & Co: Modern Classic Cocktails, and grew into a group with bars in Denver, Los Angeles, Washington DC and Seattle.', 'https://www.deathandcompany.com/', 'East Village', '433 East 6th Street', '10009', 'New York', 'New York', 'US', 40.72594, -73.98466, false, NULL),
    ('elephantbarnomad', 'Elephant Bar', 'Hotel bar inside the NoMad Hotel at Broadway and 28th Street, ranked in the World''s 50 Best Bars in 2014, 2015 and 2016. Its plush seating and mahogany bar recalled classic New York hotel lounges. The NoMad Hotel closed permanently in March 2021; the building now houses The Ned NoMad.', NULL, 'NoMad', '1170 Broadway', '10001', 'New York', 'New York', 'US', 40.74489, -73.9886, true, 2021),
    ('katanakitten_nyc', 'Katana Kitten', 'Japanese-American cocktail bar at 531 Hudson Street in the West Village, opened in summer 2018 by Masahiro Urushido with partners Greg Boehm and James Tune. Known for highballs, the Hinoki Martini, Japanese whisky and a rock and roll room. Won Best New Opening in 2019.', 'https://www.katanakitten.com/', 'West Village', '531 Hudson Street', '10014', 'New York', 'New York', 'US', 40.73425, -74.00641, false, NULL),
    ('leyendabk', 'Leyenda', 'Pan-Latin cocktail bar on Smith Street in Carroll Gardens, Brooklyn. Opened in 2015 by Ivy Mix with mentor Julie Reiner, it focused on Latin American spirits like mezcal, sotol and raicilla. It earned James Beard recognition and closed at the end of March 2025, weeks before its tenth anniversary.', NULL, 'Carroll Gardens', '221 Smith Street', '11231', 'New York', 'New York', 'US', 40.68427, -73.99191, true, 2025),
    ('macebarnyc', 'Mace', 'Spice-driven cocktail bar in Greenwich Village, opened in 2015 in the East Village by French bartender Nico de Soto and Greg Boehm of Cocktail Kingdom. It moved to larger premises on West 8th Street in 2019. The menu is a dozen drinks, each built around a single spice.', 'https://www.macenewyork.com/', 'Greenwich Village', '35 West 8th Street', '10011', 'New York', 'New York', 'US', 40.73309, -73.99808, false, NULL),
    ('pdtnyc', 'PDT', 'Speakeasy cocktail bar in the East Village, entered through a phone booth inside the Crif Dogs hot dog shop. Opened in 2007 by Jim Meehan with Brian Shebairo, it helped drive the modern speakeasy revival and won the first James Beard award for Outstanding Bar Program. Jeff Bell owns it today.', 'https://www.pdtnyc.com/', 'East Village', '113 St. Marks Place', '10009', 'New York', 'New York', 'US', 40.72712, -73.98377, false, NULL),
    ('pouring_ribbons', 'Pouring Ribbons', 'Second-floor cocktail bar at 225 Avenue B in the East Village, the flagship of Alchemy Consulting and designed by Warren Red. Joaquin Simo''s thematic, grid-style menus made it a fixture of the New York scene, and it won Imbibe''s cocktail bar of the year for 2012. It has closed permanently.', NULL, 'East Village', '225 Avenue B', '10009', 'New York', 'New York', 'US', 40.72902, -73.97803, true, 2022),
    ('aviarynyc', 'The Aviary NYC', 'New York outpost of Grant Achatz and Nick Kokonas''s Chicago cocktail bar, on the 35th floor of the Mandarin Oriental at Columbus Circle. It opened in 2017 alongside the speakeasy-style Office and served theatrical, kitchen-driven drinks with park views. Both bars closed on 15 April 2020.', NULL, 'Columbus Circle', '80 Columbus Circle', '10023', 'New York', 'New York', 'US', 40.76901, -73.98291, true, 2020),
    ('thelongislandbar', 'The Long Island Bar', 'Neighbourhood bar in a silver-sided diner on Atlantic Avenue in Cobble Hill, Brooklyn. Open since 1951, it was restored and reopened in 2013 by Toby Cecchini (the bartender credited with the Cosmopolitan) and Joel Tompkins. Classic-leaning cocktails, a full kitchen and a loyal local crowd.', 'https://www.thelongislandbar.com/', 'Cobble Hill', '110 Atlantic Avenue', '11201', 'New York', 'New York', 'US', 40.69064, -73.99643, false, NULL),
    ('nomadbarnyc', 'The NoMad Bar', 'Hotel bar in the NoMad hotel at 1170 Broadway, run by Leo Robitschek from 2012 as part of the Eleven Madison Park team''s NoMad project. Its large-format cocktails and classic-driven menu earned it Best Bar in North America in 2017 and 2018. It closed with the hotel in March 2021.', NULL, 'NoMad', '1170 Broadway', '10001', 'New York', 'New York', 'US', 40.74489, -73.9886, true, 2021),
    ('lostandfounddrinkery', 'Lost + Found Drinkery', 'Tiny cocktail bar in central Nicosia, opened in November 2013 by Dinos Constantinides. Retro chequerboard-floor room seating about twenty, a menu built as a flavour map, house syrups and bitters, and an upstairs drinks lab. It helped put Cyprus on the international cocktail map.', 'https://www.instagram.com/lostandfounddrinkery/', 'Trypiotis', '38 Lord Byron Street', '1096', 'Nicosia', NULL, 'CY', 35.16656, 33.35226, false, NULL),
    ('andy_wahloo', 'Andy Wahloo', 'Marais cocktail bar opened in the early 2000s by restaurateur Mourad Mazouz, next door to his 404 restaurant. Moroccan-meets-pop-art decor with coloured cement tiles, a small dance floor and DJs at weekends. Bar manager Kaled Derouiche has run the drinks since 2013 with a seasonal signature menu.', 'https://www.andywahloo-bar.com/', 'Marais', '69 rue des Gravilliers', '75003', 'Paris', NULL, 'FR', 48.86451, 2.35415, false, NULL),
    ('dirtydickparis', 'Dirty Dick', 'Tiki bar in Pigalle, opened in 2013 by bartender Scotty Schuder in a former brothel on Rue Frochot, keeping the old name. Fresh juices and house syrups, classic Don the Beachcomber style drinks alongside originals, served in custom vessels by tiki artist Baï. A leading name in Paris''s tiki revival.', 'https://www.instagram.com/dirtydickparis/', 'Pigalle', '10 rue Frochot', '75009', 'Paris', NULL, 'FR', 48.88153, 2.33754, false, NULL),
    ('frequenceparis', 'Fréquence', 'Vinyl-led cocktail bar near Bastille, opened in 2018 by Matthieu Biron and Guillaume Quenza, both formerly of Andy Wahloo. The back bar holds records rather than bottles. A short seasonal menu leans low-ABV with Japanese spirits like sake and umeshu, and DJs play vinyl at weekends.', 'https://www.instagram.com/frequenceparis/', 'Bastille', '20 rue Keller', '75011', 'Paris', NULL, 'FR', 48.8548, 2.37593, false, NULL),
    ('lemaryceleste', 'Le Mary Celeste', 'Oyster and cocktail bar on a Haut-Marais corner, opened in 2013 by the team behind Candelaria and Glass (now Quixotic Projects). Nautical whitewashed room around a semicircular bar, natural wines, changing small plates, seasonal cocktails and a daily happy hour on oysters.', 'https://www.lemaryceleste.com/', 'Haut-Marais', '1 rue Commines', '75003', 'Paris', NULL, 'FR', 48.86174, 2.365, false, NULL),
    ('mabelparis', 'Mabel', 'Rum-focused cocktail den in the Sentier, opened in November 2014 by Joseph Akhavan and his partner Samantha behind a grilled cheese counter at 58 rue d''Aboukir. Seated service, over a hundred rums and a menu of inventive rum-led drinks. It has since closed permanently.', NULL, 'Sentier', '58 rue d''Aboukir', '75002', 'Paris', NULL, 'FR', 48.86743, 2.3461, true, 2020),
    ('zapotebar', 'Zapote Bar', 'Yucatan-inspired cocktail bar and open-fire restaurant inside Rosewood Mayakoba, south of Playa del Carmen. Named for the zapote tree, a Mayan symbol of hospitality, it works with small-batch Mexican spirits and regional produce, and runs a Guest Bartender Series with live DJs. Open to non-guests.', 'https://www.rosewoodhotels.com/en/mayakoba-riviera-maya/dining/zapote-bar', 'Mayakoba', 'Carretera Federal Cancún-Playa del Carmen Km 298', '77710', 'Playa del Carmen', NULL, 'MX', 20.69362, -87.0264, false, NULL),
    ('hemingwaybarprague', 'Hemingway Bar', 'Prague cocktail bar themed around Ernest Hemingway''s favourite drinks, with a deep rum list, rare absinthes and champagne. Opened in 2009 on Karolíny Světlé and owned by Aleš Půta. In 2025 it moved across Národní třída to Opatovická street, adding a full kitchen.', 'https://www.hemingwaybar.cz', 'Staré Město', 'Opatovická 1737/3', '110 00', 'Prague', NULL, 'CZ', 50.07928, 14.41629, false, NULL),
    ('baccanoroma', 'Baccano', 'Paris-style bistro, cocktail bar and oyster bar near the Trevi Fountain, modelled by its founder on the atmosphere of Balthazar in New York. A long bar, retro interiors and a big bottle list sit alongside Mediterranean food. Bar manager Mario Farulla led the drinks when it entered the 50 Best list.', 'https://www.baccanoroma.com', 'Trevi', 'Via delle Muratte 23', '00187', 'Rome', NULL, 'IT', 41.90037, 12.48236, false, NULL),
    ('freniefrizioni', 'Freni e Frizioni', 'Trastevere bar in a converted mechanic''s workshop, opened on 4 July 2005 by four co-founders including Riccardo Rossi. It brought the northern Italian buffet aperitivo to Rome and grew into a high-volume cocktail bar with playful, character-themed menus, still busy every night on its little piazza.', 'https://www.freniefrizioni.com', 'Trastevere', 'Via del Politeama 4', '00153', 'Rome', NULL, 'IT', 41.89128, 12.47067, false, NULL),
    ('jerrythomas.speakeasy', 'Jerry Thomas Speakeasy', 'Rome''s first hidden cocktail bar, opened in 2010 by bartenders Leonardo Leuci, Antonio Parlapiano, Roberto Artusio and Alessandro Procoli. Named for the nineteenth-century American bartender, it runs on a members-only, daily-password system and focuses on classic recipes, house twists and its own Vermouth del Professore.', 'https://www.thejerrythomasproject.it/en/', 'Parione', 'Vicolo Cellini 30', '00186', 'Rome', NULL, 'IT', 41.89785, 12.46792, false, NULL),
    ('thecourtrome', 'The Court', 'Cocktail bar on the terrace of the Palazzo Manfredi hotel, with views of the Colosseum and the ruins of the Ludus Magnus. A long travertine counter and a lab-style setup drive a menu of theatrical, Rome-inspired drinks alongside classics. Matteo Zed has been named as its bar manager.', 'https://www.manfredihotels.com/en/the-court/', 'Monti', 'Via Labicana 125', '00184', 'Rome', NULL, 'IT', 41.89019, 12.4956, false, NULL),
    ('abvsf', 'ABV', 'Mission District bar on 16th Street from three bartending partners, known for a relaxed room, a deep tequila and mezcal list and cocktails grouped by base spirit rather than complexity. Serves a kitchen menu until midnight, with an upstairs bar called Over Proof for private events.', 'https://www.abvsf.com', 'Mission Dolores', '3174 16th Street', '94103', 'San Francisco', 'California', 'US', 37.76495, -122.42354, false, NULL),
    ('pch_sf', 'Pacific Cocktail Haven', 'Union Square cocktail bar opened in 2016 by Kevin Diedrich, with drinks drawing on the flavours of Asia and the Pacific: pandan, calamansi, shochu and tropical ingredients. It moved to 550 Sutter Street after a 2021 fire and now takes walk-ins only, Monday to Saturday.', 'https://www.pacificcocktailsf.com', 'Union Square', '550 Sutter Street', '94102', 'San Francisco', 'California', 'US', 37.78934, -122.40953, false, NULL),
    ('smugglerscovesf', 'Smuggler''s Cove', 'Three-storey tiki and rum bar in Hayes Valley opened in December 2009 by Martin Cate, now co-owned with his wife Rebecca. Known for one of the largest rum collections in the US, a menu spanning centuries of rum drinks and its Rumbustion Society tasting programme.', 'https://www.smugglerscovesf.com', 'Hayes Valley', '650 Gough Street', '94102', 'San Francisco', 'California', 'US', 37.7794, -122.42334, false, NULL),
    ('tommysmexican', 'Tommy''s Mexican Restaurant', 'Family-run Yucatecan restaurant on Geary Boulevard in the Richmond District, opened in 1965 by Tomas and Elmy Bermejo. Their son Julio runs the tequila program, with around 300 100% agave bottles. It is the birthplace of the Tommy''s Margarita, made with agave syrup in place of orange liqueur, and a regular stop for visiting bartenders.', 'https://www.tommysmexican.com/', 'Outer Richmond', '5929 Geary Boulevard', '94121', 'San Francisco', 'California', 'US', 37.77998, -122.48313, false, NULL),
    ('trickdogbar', 'Trick Dog', 'Warehouse-style cocktail bar in the Mission, opened in January 2013 by Josh Harris and Scott Baird of Bon Vivants. Its trademark is a complete menu overhaul about twice a year, each built around a new theme and often a printed artefact (the current one is shaped like a wrestling belt). Still busy in 2026 under Harris, with a food menu upstairs.', 'https://www.trickdogbar.com/', 'Mission District', '3010 20th Street', '94110', 'San Francisco', 'California', 'US', 37.75922, -122.41119, false, NULL),
    ('truelaurelsf', 'True Laurel', 'Mission District cocktail bar and restaurant from the team behind Lazy Bear, opened in December 2017 by chef David Barzelay and bar director Nicolas Torres. The drinks lean on California produce, whole-fruit use and low waste, with a seasonal small-plates menu and weekend brunch. Won the Ketel One Sustainable Bar Award in 2024.', 'https://truelaurelsf.com/', 'Mission District', '753 Alabama Street', '94110', 'San Francisco', 'California', 'US', 37.7595, -122.41149, false, NULL),
    ('otro___bar', 'Otro Bar', 'Listening-room cocktail bar on the second floor of Bar La Buenos Aires, a 1905 cantina in San José''s Barrio Aranjuez. It opened in February 2025 from founders Fernando and Manuel Crespo as the younger sibling of Isolina. Vinyl sets the mood while a visible lab turns Costa Rican corn, coffee, tapa de dulce and banana into clarified and fermented drinks.', 'https://www.instagram.com/otro___bar/', 'Barrio Aranjuez', 'Avenida 9 y Calle 23 (segundo piso, Bar La Buenos Aires)', '10101', 'San José', NULL, 'CR', 9.93681, -84.06674, false, NULL),
    ('lafactoriapr', 'La Factoría', 'Old San Juan cocktail bar opened in 2013 by Leslie Cofresí, Roberto Berdecía and Pablo Rodríguez in a former nightlife space. It strings together themed rooms, from a front bar and wine room to a salsa room and a hidden speakeasy, and put Puerto Rican flavours at the centre of its drinks. Widely seen as the island''s leading cocktail destination.', 'https://lafactoriavsj.com/', 'Old San Juan', '148 Calle San Sebastián', '00901', 'San Juan', NULL, 'PR', 18.46724, -66.1174, false, NULL),
    ('sietenegronis', 'Siete Negronis', 'Negroni-only cocktail bar that opened in Santiago in 2016 in Bellavista, with a permanent menu of seven takes on the Negroni, from clarified and chocolate versions to barrel-aged ones. Partners Matías Supán and Matías Peredo have brought it back to the Bellavista area, on the second floor of Terrazas San Cristóbal, with a late-night, disco-leaning room.', 'https://sietenegronis.cl/', 'Bellavista', 'Constitución 241, Terrazas San Cristóbal (2nd floor)', NULL, 'Santiago', NULL, 'CL', -33.43154, -70.63498, false, NULL),
    ('canonseattle', 'Canon', 'Small Capitol Hill cocktail bar and restaurant that Jamie Boudreau opened in 2011, built around a backbar of about 4,000 spirit labels and billed as the largest public spirits collection in the US. Known for rare and vintage bottles by the glass, deep whiskey and amaro lists and a serious cocktail menu. Boudreau also wrote The Canon Cocktail Book.', 'https://www.canonseattle.com/', 'Capitol Hill', '928 12th Avenue', '98122', 'Seattle', 'Washington', 'US', 47.61127, -122.31648, false, NULL),
    ('potatoheadbali', 'Potato Head Beach Club', 'Oceanfront beach club on Petitenget beach in Seminyak, opened in 2010 and now the centrepiece of Desa Potato Head. Founded by Ronald Akili and designed with architect Andra Matin, with an amphitheatre of reclaimed timber shutters. Its bars use upcycled citrus and local spirits, and it won the first Sustainable Bar Award at Asia''s 50 Best Bars in 2018.', 'https://seminyak.potatohead.co/', 'Petitenget', 'Jalan Petitenget No. 51B', '80361', 'Seminyak', 'Bali', 'ID', -8.67941, 115.14996, false, NULL),
    ('alice_cheongdam', 'Alice Cheongdam', 'Alice in Wonderland-themed basement bar in Cheongdam-dong, opened in April 2015 by bartender Kim Yong-joo (Terry Kim) after stints at Seoul hotel bars. Guests follow white-rabbit markers and go down through a flower shop entrance. Theatrical, story-led cocktails that use molecular techniques and Korean ingredients. It has appeared on Asia''s 50 Best Bars every year since 2016.', 'https://www.instagram.com/alice_cheongdam/', 'Cheongdam-dong', '47 Dosan-daero 55-gil, B1', '06014', 'Seoul', NULL, 'KR', 37.52666, 127.04105, false, NULL),
    ('bar.cham', 'Bar Cham', 'Small cocktail bar in a restored hanok in Seochon, run by owner-bartender Lim Byung-jin. Cham means oak, and the room is built around an oak counter. The menu centres on Korean soju, makgeolli and rice spirits, with regional stories and native ingredients driving each drink.', 'https://www.instagram.com/bar.cham', 'Tongin-dong (Seochon)', '34 Jahamun-ro 7-gil, Jongno-gu', NULL, 'Seoul', NULL, 'KR', 37.57856, 126.97066, false, NULL),
    ('charleshseoul', 'Charles H.', 'Speakeasy in the lower levels of Four Seasons Hotel Seoul, opened in 2015 and named for the travelling drinks writer Charles H. Baker Jr. Its menus reinterpret his global recipes. Head bartender Odd Strandbakken and beverage creative director Alyssa Heidt lead the program.', 'https://www.fourseasons.com/seoul/dining/lounges/charles_h/', 'Gwanghwamun', '97 Saemunan-ro, Jongno-gu (Four Seasons Hotel Seoul)', '03183', 'Seoul', NULL, 'KR', 37.57067, 126.97535, false, NULL),
    ('keepers_seoul', 'Keepers''', 'Basement cocktail bar in Cheongdam run by Korean bartending figure Laki Yoo. Known for a high-ceilinged room and for changing its whole theme, menu and decor every few months, often with visiting guest bartenders, plus a strong whisky list.', NULL, 'Cheongdam-dong', '18 Seolleung-ro 152-gil, Gangnam-gu', '06014', 'Seoul', NULL, 'KR', 37.52406, 127.04095, false, NULL),
    ('le_chamber', 'Le Chamber', 'Cheongdam speakeasy opened in 2014 by World Class veterans Eom Do-hwan (Louis Eom) and Lim Jae-jin. Guests enter through a hidden bookshelf into a high-ceilinged room with leather seating, a 200-strong whisky list and hardcover menus of storytelling cocktails.', 'https://www.instagram.com/le_chamber', 'Cheongdam-dong', '42 Dosan-daero 55-gil, Gangnam-gu', '06014', 'Seoul', NULL, 'KR', 37.52626, 127.04113, false, NULL),
    ('epic_bar_shanghai', 'E.P.I.C.', 'Three-floor neighbourhood cocktail bar in Xuhui opened in 2014 by bartender Cross Yu, with a funk-and-disco feel and the slogan Do Epic Sh*t. It won the Campari One To Watch award in 2021, the first mainland Chinese bar to do so. It closed in June 2026 after ten years.', NULL, 'Xuhui (former French Concession)', '17 Gaoyou Road (Jinfuxing West Road), Xuhui', NULL, 'Shanghai', NULL, 'CN', 31.21168, 121.43338, true, 2026),
    ('sober_company', 'Sober Company', 'Shingo Gokan''s multi-concept Shanghai venue: Sober Kissa, Sober Izakaya, Sober Sakaba and the token-access speakeasy Tipsy. Opened in 2017, closed in June 2022 when its lease ended, and reopened in October 2023 at 109 Yandang Road beside Fuxing Park. Motto: come sober, leave tipsy.', 'https://sg-management.jp/en/establishments/sober/', 'Huangpu (Fuxing Park)', 'F106-107, 109 Yandang Road', NULL, 'Shanghai', NULL, 'CN', 31.21979, 121.4657, false, NULL),
    ('speaklow_shanghai', 'Speak Low', 'Hidden speakeasy opened in 2014 by Shingo Gokan in Shanghai''s former French Concession. The entrance is a door inside the barware shop OCHO, leading up to three stacked bars that get more exclusive on each floor, the top one an omakase-style tasting. Named for Gokan''s Bacardi Legacy winning drink.', 'https://sg-management.jp/en/establishments/speaklow/', 'Former French Concession, Huangpu', '579 Fuxing Middle Road', NULL, 'Shanghai', NULL, 'CN', 31.21674, 121.46125, false, NULL),
    ('uniontradingco', 'The Union Trading Company', 'Neighbourhood cocktail bar in Shanghai''s former French Concession, opened in August 2014 by bartender Yao Lu and chef Austin Hu. It pairs American bar hospitality with local flavours and changes its menu regularly. Moved to Hengshan Road after its Fenyang Road lease ended.', 'https://www.instagram.com/uniontradingco', 'Xuhui (former French Concession)', '306 Hengshan Road', NULL, 'Shanghai', NULL, 'CN', 31.20455, 121.44023, false, NULL),
    ('mobarshenzhen', 'MO Bar Shenzhen', 'Hotel cocktail bar on the 79th floor of Mandarin Oriental, Shenzhen, in the Futian district. It opened in early 2022 and is led by Tiger Chang. Known for skyline views, a 270-degree terrace and menus built on Chinese themes, currently Colours of China, arranged around the 24 solar terms.', 'https://www.mandarinoriental.com/en/shenzhen/futian/dine/mo-bar', 'Futian', '79/F, Mandarin Oriental, 5001 Huanggang Road', '518071', 'Shenzhen', NULL, 'CN', 22.56022, 114.06674, false, NULL),
    ('28hongkongstreet', '28 HongKong Street', 'Speakeasy-style cocktail bar behind a plain 1960s shophouse front near Boat Quay. It opened on 31 October 2011, founded by three former New York lawyers, with Michael Callahan as founding barman. Known for American-style craft drinks, comfort food and hip hop. Currently pouring its Now & Then menu.', 'https://28hks.com/', 'Boat Quay', '28 Hongkong Street', '059667', 'Singapore', NULL, 'SG', 1.28768, 103.84695, false, NULL),
    ('analogueinitiative', 'Analogue Initiative', 'Plant-based, sustainability-driven cocktail bar in CHIJMES by Vijay Mudaliar of Native, opened in 2021. Famed for a bar counter 3D-printed from 1,600 kg of recycled plastic bottles and mycelium tabletops. It closed at CHIJMES in November 2024, with the team saying it was looking for a new home.', NULL, 'Civic District', '30 Victoria Street, #01-31 CHIJMES', '187996', 'Singapore', NULL, 'SG', 1.29521, 103.85211, true, 2024),
    ('barbarycoastsg', 'Barbary Coast', 'Two-storey Boat Quay bar opened in early 2020 by Celia Schoonraad and Michael Callahan, themed on Gold Rush San Francisco. The Ballroom upstairs was the ranked cocktail room, with a lab kitchen and champagne-led drinks. The Ballroom reportedly closed in February 2025; Deadfall Cantina remains on the ground floor.', NULL, 'Boat Quay', '16 North Canal Road, #02-01', '048828', 'Singapore', NULL, 'SG', 1.28691, 103.84701, true, 2025),
    ('d.bespoke', 'D.Bespoke', 'Ginza-style bar and gallery in Chinatown led by owner and head bartender Daiki Kanetaka, whose first initial gives the bar its name. Drinks are made to each guest''s taste in a small, wood-clad room, backed by sherries, calvados, armagnac and rare rums. Has a younger sibling, RPM by D.Bespoke.', 'http://dbespoke.sg', 'Chinatown', '2 Bukit Pasoh Road', '089816', 'Singapore', NULL, 'SG', 1.27866, 103.84102, false, NULL),
    ('gibsonbarsg', 'Gibson', 'Chinatown cocktail bar on the second floor of a 1930s shophouse on Bukit Pasoh Road, from Jigger & Pony Group founders Indra Kantono and Guoyi Gan. Opened in 2015 as a tribute to the Gibson martini, with ingredient-led classics, a green marble bar and oyster pairings. Principal Bartender is Gabriel Gan.', 'https://www.gibsonbar.sg/', 'Chinatown', '20 Bukit Pasoh Road, Level 2', '089834', 'Singapore', NULL, 'SG', 1.27958, 103.84047, false, NULL),
    ('mobarsg', 'MO Bar', 'Cocktail bar on level 3 of Mandarin Oriental, Singapore, overlooking Marina Bay. Relaunched in 2018 with Proof & Company and again after the hotel''s renovation in November 2023, under bar manager Charlie Kim. Runs numbered menus themed on Singapore, most recently Modern Localism in March 2026.', 'https://www.mandarinoriental.com/en/singapore/marina-bay/dine/mo-bar', 'Marina Bay', 'Level 3, Mandarin Oriental, 5 Raffles Avenue', '039797', 'Singapore', NULL, 'SG', 1.29066, 103.85832, false, NULL),
    ('manhattan_sg', 'Manhattan', 'Grand hotel bar on level 2 of Conrad Singapore Orchard (formerly Regent Singapore), styled on New York''s golden age of cocktails. It opened on 24 April 2014 and was named Asia''s best bar in 2017 and 2018. Home to the world''s first in-hotel rickhouse for barrel-aged cocktails; Zana Möhlmann is head bartender.', 'https://www.hilton.com/en/hotels/sinodci-conrad-singapore-orchard/dining/manhattan/', 'Orchard', 'Level 2, Conrad Singapore Orchard, 1 Cuscaden Road', '249715', 'Singapore', NULL, 'SG', 1.30462, 103.82485, false, NULL),
    ('night.hawk.sg', 'Night Hawk', 'A small, walk-in cocktail bar on Tanjong Pagar Road behind an unmarked door, opened in May 2022 by Peter Chua. Its retro-futuristic room takes cues from Edward Hopper''s Nighthawks painting, and it pairs strong, spirit-forward drinks with a low-waste approach. It won the Bareksten Best Bar Design Award in 2023.', 'https://nighthawk.sg', 'Tanjong Pagar', '43 Tanjong Pagar Road', '088464', 'Singapore', NULL, 'SG', 1.27892, 103.84411, false, NULL),
    ('nosleepclubsg', 'No Sleep Club', 'An all-day Keong Saik Road shophouse bar that served coffee and snacks by day and inventive highballs and cocktails by night. Juan Yi Jun and Jessica Hutchinson started it as a tiny Club Street bar in 2019 and moved to the shophouse that November. It closed in 2026, and the team moved on to Third Floor Social.', 'https://www.instagram.com/nosleepclubsg/', 'Keong Saik', '20 Keong Saik Road', '089127', 'Singapore', NULL, 'SG', 1.28005, 103.84162, true, 2026),
    ('operationdagger', 'Operation Dagger', 'A basement cocktail bar on Ann Siang Hill, opened in 2015 by Luke Whearty and known for experimental drinks, a back bar of unlabelled bottles and mostly house-made ingredients. Thomas Girard took over the bar programme in 2019. It closed its Ann Siang Hill home on 31 October 2020.', NULL, 'Ann Siang Hill', '7 Ann Siang Hill', '069791', 'Singapore', NULL, 'SG', 1.2815, 103.84579, true, 2020),
    ('republicbarsg', 'Republic', 'A 1960s-themed lounge and bar in The Ritz-Carlton, Millenia Singapore, opened in 2021 in the former Chihuly Lounge in collaboration with Proof & Company. Its menus explore the decade through Singapore, the UK, the US and Italy, with vintage spirits and pop-culture cocktails. It reached Asia''s 50 Best in 2022.', 'https://www.republicbar.com.sg', 'Marina Centre', '7 Raffles Avenue', '039799', 'Singapore', NULL, 'SG', 1.29053, 103.86007, false, NULL),
    ('sagohouse.sg', 'Sago House', 'A neighbourhood cocktail bar opened in 2020 by Jay Gray, Desiree Jane Silva and Abhishek C George, built largely by hand from upcycled materials. Its menu changes weekly, with six classic-style drinks. It moved from Sago Street to 37 Duxton Hill in October 2023.', 'https://sagohouse.sg', 'Duxton Hill', '37 Duxton Hill', '089615', 'Singapore', NULL, 'SG', 1.27845, 103.84289, false, NULL),
    ('theoldman_sg', 'The Old Man Singapore', 'A Hemingway-themed cocktail bar on Keong Saik Road, opened in May 2019 as the first overseas branch of Hong Kong''s The Old Man, with Andrew Yap as managing partner. Its drinks were named after Hemingway novels. It renamed itself Papa Doble in 2022 and has since closed.', NULL, 'Keong Saik', '55 Keong Saik Road', '089158', 'Singapore', NULL, 'SG', 1.28071, 103.84151, true, 2022),
    ('theotherroomsg', 'The Other Room', 'A hidden drinking house inside the Marriott Tang Plaza Hotel on Orchard Road, opened in July 2016 by bartender Dario Knox. It is known for its cask-finished spirits, finished in barrels in-house, and a Prohibition-era feel. Knox sold the bar in 2019; it still trades with a mix of cocktails, spirits and tapas.', 'https://www.theotherroom.com.sg', 'Orchard', '320 Orchard Road', '238865', 'Singapore', NULL, 'SG', 1.30511, 103.83288, false, NULL),
    ('tipplingclub', 'Tippling Club', 'A progressive restaurant and cocktail bar from chef-owner Ryan Clift, opened in 2008 in Dempsey Hill and moved to Tanjong Pagar Road in 2013. It paired tasting menus with inventive drinks, including the gummy-bear menu, and trained many of Singapore''s bar leads. It closed after service on 31 December 2024.', NULL, 'Tanjong Pagar', '38 Tanjong Pagar Road', '088461', 'Singapore', NULL, 'SG', 1.27949, 103.84376, true, 2024),
    ('elcopitasbar', 'El Copitas', 'Semi-secret Mexican taqueria and cocktail bar in a courtyard basement on Kolokolnaya Street, opened in 2015 by Igor Zernov, Nikolay Kiselev and Artem Peruk of the Follow The Rabbits group. Guests book by phone. Known for tequila and mezcal drinks and a weekly changing menu, it reopened after a full redesign in January 2025.', 'https://www.instagram.com/elcopitasbar/', 'Vladimirsky', 'Kolokolnaya Street, 2/18', '191025', 'St Petersburg', NULL, 'RU', 59.9293, 30.34858, false, NULL),
    ('abarcalledgemma', 'A Bar Called Gemma', 'Owner-built cocktail bar on Grev Turegatan in Östermalm, opened in 2019 by bartender Johan Evers after years of planning. The name is an acronym of its values, among them generosity and artisan craft. It offered signature drinks beside classic riffs and taught guests home bartending. It closed on 28 March 2026.', NULL, 'Östermalm', 'Grev Turegatan 30', '114 38', 'Stockholm', NULL, 'SE', 59.33711, 18.07712, true, 2026),
    ('lucysstockholm', 'Lucy''s Flower Shop', 'Hidden basement bar on Birger Jarlsgatan in central Stockholm, reached through a shuttered flower shop. Opened in November 2019 by bartenders Ola Carlson and Alex Skärlén, it seats about 38 and pours a short list of nine drinks that lean on Nordic ingredients such as lingonberry, sea buckthorn and birch.', 'https://www.lucysstockholm.se/', 'Östermalm', 'Birger Jarlsgatan 20', '114 34', 'Stockholm', NULL, 'SE', 59.33663, 18.07196, false, NULL),
    ('tjoget', 'Tjoget', 'Neighbourhood restaurant and cocktail bar in Hornstull on Södermalm, opened in 2012 and listed by The World''s 50 Best Bars first as Linje Tio. It is run by the 20-gruppen team and mixes Mediterranean-leaning classics and seasonal drinks, with a dining room, wine bodega and beer café alongside the bar.', 'https://tjoget.com/', 'Hornstull', 'Hornsbruksgatan 24', '117 34', 'Stockholm', NULL, 'SE', 59.31614, 18.03479, false, NULL),
    ('bulletinplacesydney', 'Bulletin Place', 'Tiny first-floor cocktail bar in a sandstone building near Circular Quay, opened in December 2012 by Tim Philips-Johansson, Rob Sloan and Adi Ruiz. It seated about 45, built a short daily menu around market produce and made its own ferments. It closed on 28 May 2021, citing bushfires, light rail works and Covid.', NULL, 'Circular Quay', '10-14 Bulletin Place', '2000', 'Sydney', 'New South Wales', 'AU', -33.86258, 151.20957, true, 2021),
    ('re.sydney', 'Re', 'Zero-waste cocktail bar in the South Eveleigh railway workshops, opened in April 2021 by Matt Whiley and Maurice Terzini. It was built from recycled materials and ran on rescued produce, and won the Ketel One Sustainable Bar award in 2021. It closed in February 2024; a planned move to Redfern''s Norfolk Hotel was cancelled.', NULL, 'Eveleigh', '2 Locomotive Street', '2015', 'Sydney', 'New South Wales', 'AU', -33.89444, 151.19625, true, 2024),
    ('thelobo_syd', 'The Lobo', 'Basement rum bar on Clarence Street in Sydney''s CBD, opened in July 2013 by Jared Merlino with partners. Named for Cuban sugar baron Julio Lobo, it stocks hundreds of rums and serves daiquiris and Caribbean-leaning cocktails. It opened as Lobo Plantation and dropped the word from its name in July 2020.', 'https://www.thelobo.com.au/', 'Sydney CBD', 'Basement Lot 1, 209 Clarence Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.86997, 151.20507, false, NULL),
    ('disco_pantera', 'Tigra + Disco Pantera', 'Two-level bar at 11 Young Street in Quay Quarter Lanes, opened in September 2024 by Scottish brothers Gordon and Ross Purnell. Tigra downstairs is an aperitif and small plates bar; Disco Pantera upstairs is a 1970s New York style cocktail lounge. Built from reclaimed pieces, it won Best Bar Design at The World''s 50 Best Bars 2025.', 'https://www.bartigra.com.au/', 'Quay Quarter', '11 Young Street', '2000', 'Sydney', 'New South Wales', 'AU', -33.863, 151.21124, false, NULL),
    ('eximiabar', 'Exímia', 'Cocktail bar on the second floor of a Rua Manuel Guedes building in Itaim Bibi, São Paulo, opened in 2024. Bartender and partner Márcio Silva writes drinks around native Brazilian ingredients such as amburana and cambuci, and chef Manu Buffara designed the food. It reopened in April 2026.', 'https://www.instagram.com/eximiabar/', 'Itaim Bibi', 'Rua Manuel Guedes, 369, 2º piso', '04536-070', 'São Paulo', NULL, 'BR', -23.58371, -46.67906, false, NULL),
    ('frankbarsp', 'Frank Bar', 'Hotel bar in the lobby of the Maksoud Plaza near Avenida Paulista in São Paulo, opened in 2015 with a retro look built around Frank Sinatra''s 1981 visit. Head bartender Spencer Amereno Jr. made it a destination for classic-leaning cocktails. It closed in December 2021 when the hotel shut down.', NULL, 'Jardim Paulista', 'Alameda Campinas, 150 (Maksoud Plaza)', NULL, 'São Paulo', NULL, 'BR', -23.56319, -46.65117, true, 2021),
    ('guilhotinabar', 'Guilhotina Bar', 'Laid-back cocktail bar in Pinheiros, São Paulo, opened in December 2016 by Márcio Silva, Rafael Berçot and Marcello Nazareth. It has an easy, no-fuss style with a motto of leaving pretence at the door, and reopened in 2026 after a four-month renovation for its tenth year.', 'https://www.instagram.com/guilhotinabar/', 'Pinheiros', 'Rua Costa Carvalho, 84', '05429-000', 'São Paulo', NULL, 'BR', -23.56068, -46.69924, false, NULL),
    ('subastor', 'SubAstor', 'Speakeasy-style cocktail bar in the basement of Bar Astor in Vila Madalena, São Paulo, opened in June 2009 by the Cia. Tradicional de Comércio group. Directed by Fabio La Pietra, it is known for its Biomes of Brazil menu, with one drink per Brazilian ecosystem. It now has sister rooms on Paulista and in a former bank vault.', 'https://subastor.com.br/', 'Vila Madalena', 'Rua Delfina, 163 (subsolo)', '05443-010', 'São Paulo', NULL, 'BR', -23.55404, -46.69427, false, NULL),
    ('venderbar', 'Vender', 'Speakeasy in Taichung''s West District opened in 2019 by Summer Chen and Darren Lim, who came back to Taiwan after bartending in Singapore. You enter through a vending machine with a coin, and the drinks use Southeast Asian herbs and spices, each named after a type of vending machine.', 'https://www.instagram.com/venderbar/', 'West District', 'No. 118, Wuquan West 4th Street', NULL, 'Taichung', NULL, 'TW', 24.13557, 120.6625, false, NULL),
    ('ahasaloon', 'AHA Saloon', 'Da''an District cocktail bar opened in 2017 by three Diageo World Class Taiwan champions: Kae Yin, Victor Yang and Jeffrey Chang. It served inventive drinks built on Taiwanese and wider Asian ingredients in a vinyl-and-bookshelf living room, and closed on 30 September 2024 because of neighbourhood urban renewal.', NULL, 'Da''an', 'No. 138, Section 2, Fuxing South Road', '106', 'Taipei', NULL, 'TW', 25.02894, 121.5433, true, 2024),
    ('barmood_taipei', 'Bar Mood', 'Cocktail bar in Taipei''s Da''an district, opened in September 2017 by bartender Nick Wu as one of Taiwan''s first craft cocktail bars. It pairs classic Western technique with local flowers, herbs, teas and fruit, with a bar-top garden for garnishes, handmade furniture and a bistro-style food menu.', 'https://www.instagram.com/barmood_taipei/', 'Da''an', 'No. 53, Lane 160, Section 1, Dunhua South Road', '106', 'Taipei', NULL, 'TW', 25.04366, 121.54659, false, NULL),
    ('draftland', 'Draft Land', 'Taipei bar in Da''an that pours cocktails from taps, an idea founded by Angus Zou and opened in late 2017. Guests taste before buying, and a small upstairs room serves fuller cocktails. The concept has spread to Hong Kong and other Asian cities.', 'https://www.draftland.tw/tpe', 'Da''an', '1F, No. 2, Lane 248, Section 4, Zhongxiao East Road', '106', 'Taipei', NULL, 'TW', 25.0411, 121.55404, false, NULL),
    ('indulgebistro', 'Indulge Experimental Bistro', 'Bistro and cocktail bar on a quiet Da''an lane, opened in 2009 by owner Aki Wang. Wang makes his own liqueurs from hand-picked Taiwanese teas, and the drinks sit alongside modern European food built on local produce. A regular on both Asia''s and the world''s 50 Best Bars lists.', 'https://indulgebistrotaipei.blogspot.com', 'Da''an', 'No. 11, Lane 219, Section 1, Fuxing South Road', '106', 'Taipei', NULL, 'TW', 25.03914, 121.54481, false, NULL),
    ('room_by_le_kief', 'Room by Le Kief', 'Experimental Taipei cocktail bar opened in 2018 by Seven Yi as the second venue in his Le Kief group. Its curved counter worked like a stage, and it paired food with themed cocktails that changed with the season. It paused trading at its Da''an address in 2024 to look for a new home.', NULL, 'Da''an', 'No. 10, Alley 5, Lane 107, Section 1, Fuxing South Road', '106', 'Taipei', NULL, 'TW', 25.0437, 121.54443, true, 2024),
    ('bellboy.tlv', 'Bellboy', 'Playful 1920s-styled cocktail bar in the lobby of Hotel B Berdichevsky in central Tel Aviv, opened in 2014 by bartender Ariel Leizgold. Known for story-led, inventive drinks, it also hides Butler, a small speakeasy for classic cocktails and oysters. Open daily from the evening.', 'https://bellboygroup.com/bellboy-tlv/', 'Lev HaIr', '14 Berdyczewski Street', '6425813', 'Tel Aviv', NULL, 'IL', 32.071, 34.78029, false, NULL),
    ('imperialcocktailbar', 'Imperial Craft Cocktail Bar', 'Tel Aviv craft cocktail bar tucked inside the Imperial Hotel on Hayarkon Street, opened in 2012 by bartenders Dror Alterovich, Bar Shira and Gilad Livnat. Colonial-Asian styling and house-made syrups made it Best Bar in Africa and the Middle East in 2017. It closed in October 2025 ahead of the building''s redevelopment.', NULL, 'Lev HaIr', '66 Hayarkon Street', NULL, 'Tel Aviv', NULL, 'IL', 32.07566, 34.76686, true, 2025),
    ('lacapilla.tequila', 'La Capilla', 'Small, unsigned cantina on Calle Miguel Hidalgo in the town of Tequila, Jalisco, run for decades by Don Javier Delgado Corona (1924-2020), who is credited with inventing the Batanga: tequila, lime and cola stirred with the bar''s knife. Family-run since his death, it remains a pilgrimage stop for cocktail fans.', NULL, 'Centro', 'Calle Miguel Hidalgo 33', '46400', 'Tequila', 'Jalisco', 'MX', 20.8815, -103.84025, false, NULL),
    ('barhighfive', 'Bar High Five', 'Basement bar in Tokyo''s Ginza opened in 2008 by Hidetsugu Ueno and moved to its current address in 2015. There is no menu: Ueno and head bartender Kaori Kurakami build drinks from a conversation with each guest, with a strong Japanese whisky backbar. It won the Heering Legend of the List award in 2020.', 'https://www.barhighfive.com/', 'Ginza', 'Efflore Ginza 5 Building B1F, 5-4-15 Ginza, Chuo-ku', '104-0061', 'Tokyo', NULL, 'JP', 35.6716, 139.76294, false, NULL),
    ('barorchardginza', 'Bar Orchard Ginza', 'Ginza cocktail bar opened in 2007 by Takuo Miyanohara and his wife Sumire, built around fresh seasonal fruit chosen by the guest at the counter. Known for theatrical presentation, such as smoking pine cones and tiny bathtubs, and for drinks tailored to each guest''s taste and strength. On the seventh floor of the Sanraku Building.', 'https://www.instagram.com/barorchardginza/', 'Ginza', 'Sanraku Building 7F, 6-5-16 Ginza, Chuo-ku', '104-0061', 'Tokyo', NULL, 'JP', 35.67111, 139.76238, false, NULL),
    ('bar_trench', 'Bar Trench', 'A tiny, dimly lit bar down a back alley in Ebisu, opened in 2010 as the second bar from the Bar Tram team. Known for absinthe served the traditional way, herbal liqueurs, a huge bitters collection and inventive cocktails. Head bartender Rogerio Igarashi leads the counter; a Kyoto branch followed.', 'https://small-axe.net/bar-trench/', 'Ebisu', '1-5-8 Ebisunishi', '150-0021', 'Tokyo', NULL, 'JP', 35.64842, 139.70792, false, NULL),
    ('bargenyamamoto', 'Gen Yamamoto', 'Eight-seat cocktail bar in Tokyo''s Azabu-Juban, opened in 2013 by bartender Gen Yamamoto after his years in New York. It serves a cocktail omakase, a set run of drinks built from seasonal Japanese fruit, vegetables and spirits that changes almost weekly. Reservations are taken by phone only.', 'http://www.genyamamoto.jp/', 'Azabu-Juban', 'Anniversary Building 1F, 1-6-4 Azabu-Juban, Minato-ku', '106-0045', 'Tokyo', NULL, 'JP', 35.65649, 139.73428, false, NULL),
    ('star__bar', 'Star Bar Ginza', 'Hisashi Kishi''s basement bar in Ginza, open since December 2000. It is a benchmark for precise classic Japanese bartending: hand-cut clear "ninja ice", a famed Sidecar, and fresh-fruit drinks. Kishi has trained many bartenders who later opened their own bars in Tokyo.', 'https://www.starbar.jp/', 'Ginza', 'Moderns Ginza B1F, 1-5-13 Ginza', '104-0061', 'Tokyo', NULL, 'JP', 35.6748, 139.76703, false, NULL),
    ('the_sg_club', 'The SG Club', 'Shingo Gokan''s Tokyo flagship, opened in summer 2018 in Shibuya''s Jinnan. Guzzle on the ground floor is casual, Sip in the basement is the serious cocktail room, and Savor upstairs is a members'' cigar lounge. Built around an 1860s Japan-meets-New-York story, with most ingredients made in house.', 'https://sg-management.jp/en/establishments/sgclub/', 'Jinnan', '1-7-8 Jinnan', '150-0041', 'Tokyo', NULL, 'JP', 35.66425, 139.69924, false, NULL),
    ('barpompette_to', 'Bar Pompette', 'A walk-in-only College Street bar in Toronto''s Little Italy, opened in 2021 by the team behind French bistro Pompette. Cocktail director Maxime Hoerth, a French Meilleur Ouvrier barman, and co-founder Hugo Togni pair lab-made ingredients with a relaxed, neighbourhood feel. Named best bar in Canada in 2024 and 2025.', 'https://www.pompette.ca/barpompette', 'Little Italy', '607 College Street', 'M6G 1B5', 'Toronto', NULL, 'CA', 43.655, -79.41435, false, NULL),
    ('bar_raval', 'Bar Raval', 'A Gaudi-inspired Spanish tapas and cocktail bar on College Street, opened in February 2015 by chef Grant van Gameren. A sinuous mahogany bar and standing room set the tone for pintxos, sherry, vermouth and a tight house cocktail list, now overseen by bar manager Bex Figueiredo. Walk-in only.', 'https://www.thisisbarraval.com/', 'Little Italy', '505 College Street', 'M6G 1A5', 'Toronto', NULL, 'CA', 43.65583, -79.40992, false, NULL),
    ('civlibto', 'Civil Liberties', 'A no-menu cocktail bar on Bloor Street West that has poured bespoke drinks since 2014. Guests describe what they want and bartenders build it from 210-plus spirits and a set of house liqueurs. Nick Kennedy is the lead owner. It closed for about six months after a flood in 2025 and has since reopened.', 'https://www.civillibertiesbar.com/', 'Bloorcourt', '878 Bloor Street West', 'M6G 1M5', 'Toronto', NULL, 'CA', 43.66222, -79.42521, false, NULL),
    ('arcatulum', 'Arca', 'A jungle-set restaurant and bar on the Tulum beach road, opened in 2015 by chef José Luis Hinostroza. Open-fire cooking and a cocktail list organised by Mayan-jungle stages (seeds, leaves, flowers, fruits), led at the bar by Carlos Mora with Mexican spirits and local botanicals. Open evenings daily.', 'https://arcatulum.com/', 'Boca Paila Road', 'Carretera Tulum-Boca Paila Km 7.6', '77780', 'Tulum', NULL, 'MX', 20.14944, -87.45944, false, NULL)
) AS v("handle", "name", "bio", "website", "locality", "address_line", "postcode", "city", "region", "country_code",
       "latitude", "longitude", "is_closed", "closed_year")
-- Not a second copy of a bar someone already added (add_venue's rule).
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profiles" p
    WHERE p.kind = 'bar' AND p.latitude BETWEEN v.latitude - 0.002 AND v.latitude + 0.002
      AND private.venue_name_key(p.display_name) = private.venue_name_key(v.name)
      AND private.distance_km(v.latitude, v.longitude, p.latitude, p.longitude) <= 0.15
)
ON CONFLICT ("handle") DO NOTHING;

-- --- Places and awards ---

-- One spelling per award, without the sponsor.
UPDATE "public"."profile_awards" a
SET "title" = v.title
FROM (VALUES
    ('Art of Hospitality Award', 'Art of Hospitality'),
    ('Highest Climber Award', 'Highest Climber'),
    ('One To Watch Award', 'One To Watch'),
    ('Ketel One Sustainable Bar Award', 'Sustainable Bar')
) AS v("old", "title")
WHERE a.award = 'The World''s 50 Best Bars' AND a.title = v.old
  AND NOT EXISTS (SELECT 1 FROM "public"."profile_awards" b
                  WHERE b.profile_id = a.profile_id AND b.award = a.award AND b.year = a.year AND b.title = v.title);

