-- --- The people ---

INSERT INTO "public"."profiles" ("kind", "handle", "display_name", "bio", "website", "is_public", "city")
SELECT 'person', v.handle, v.name, v.bio, v.website::text, true, v.city::text
FROM (VALUES
    ('aaron.diaz', 'Aaron Díaz', 'Bartender who founded Carnaval in 2018 and developed its ''coctelería conceptual'' approach. Left in 2026 to help Super Group open new Lima bars including Lima Sour and Superbar.', NULL, 'Lima'),
    ('abhishek.george', 'Abhishek C George', 'Co-founder of Sago House, with earlier bar experience at Spiffy Dapper and Oriental Elixir in Singapore.', NULL, 'Singapore'),
    ('adam.tsou', 'Adam Tsou', 'Original co-founder of Quixotic Projects and Le Mary Celeste in Paris, alongside Joshua Fontaine and Carina Soto Velásquez. Left the group in 2020.', NULL, 'Paris'),
    ('adi.ruiz', 'Adi Ruiz', 'Bartender who co-founded Bulletin Place in 2012 and left in 2016 to move to Tasmania. Australia''s first winner of the World Class title.', NULL, 'Sydney'),
    ('agung.prabowo', 'Agung Prabowo', 'Bartender who co-founded The Old Man in 2017 and led its concept and cocktails until stepping down in 2020. He then opened the Penicillin and Dead & bars in Hong Kong.', NULL, 'Hong Kong'),
    ('agustin.febrescordero', 'Agustín Febres-Cordero', 'Creative director and co-founder of Juliana in Guayaquil. He accepted the Best Cocktail Menu award on the bar''s behalf in 2022.', NULL, 'Guayaquil'),
    ('aidan.bowie', 'Aidan Bowie', 'Bartender who led the New York Aviary and Office bars for Alinea Group after working at Dandelyan in London.', NULL, 'New York'),
    ('ajit.gurung', 'Ajit Gurung', 'Bartender who joined COA in Hong Kong in December 2020 and co-founded The Savory Project with Jay Khan in 2023.', NULL, 'Hong Kong'),
    ('aki.nishikura', 'Aki Nishikura', 'Co-founder of Byrdi in Melbourne with Luke Whearty, and part of the team that ran Operation Dagger in Singapore before that.', NULL, 'Melbourne'),
    ('aki.wang', 'Aki Wang', 'Taipei bartender and owner of Indulge Experimental Bistro since 2009, known for liqueurs made from native Taiwanese teas. He launched the Tê tea liqueur brand and a cocktail-focused liquor shop.', NULL, 'Taipei'),
    ('alastair.burgess', 'Alastair Burgess', 'Founder of Happiness Forgets, opened in 2010, after bar management roles in London and a stint at New York''s Pegu Club. Also behind Original Sin and the Petit Pois bistro on Hoxton Square.', NULL, 'London'),
    ('alberto.martinez', 'Alberto Martínez', 'Founder and owner of 1862 Dry Bar in Madrid. Left a 12-year engineering career during Spain''s economic crisis to bartend, and is known for classic-led cocktails such as his Sherry & Cherry Cobbler.', NULL, 'Madrid'),
    ('aleksandr.tsurkan', 'Aleksandr Tsurkan', 'Manager and head bartender of Insider Bar in Moscow, working within the Tabidze restaurant holding. Wrote the bar''s May 2025 cocktail menu.', NULL, 'Moscow'),
    ('ales.puta', 'Aleš Půta', 'Owner of Hemingway Bar Prague, which opened in 2009 and moved to Opatovická street in 2025. He fronts the bar''s Hemingway-inspired cocktail concept and the addition of a full kitchen.', NULL, 'Prague'),
    ('alessandro.procoli', 'Alessandro Procoli', 'Co-founder of the Jerry Thomas Project in Rome, who joined the original trio to open the speakeasy in 2010.', NULL, 'Rome'),
    ('alex.day', 'Alex Day', 'Bar owner and author, partner in Proprietors LLC with David Kaplan and Devon Tarby. Co-author of Death & Co and Cocktail Codex, and COO of Death & Co''s parent company Gin & Luck.', NULL, 'Los Angeles'),
    ('alex.dowd', 'Alex Dowd', 'Co-owner of Cantina OK!, the tiny Sydney mezcal bar opened in 2019. Co-founder of Mucho Group with Jeremy Blackmore and Daisy Tulley.', NULL, 'Sydney'),
    ('alex.francis', 'Alex Francis', 'Bar director of Little Red Door until early 2024.', NULL, 'Paris'),
    ('alex.frezza', 'Alex Frezza', 'Neapolitan bartender who co-founded L''Antiquario in 2015 and leads its bar. He also founded the training outfit Bar in Movimento and opened the tiki-style Platanos in 2019.', NULL, 'Naples'),
    ('alex.gilmour', 'Alex Gilmour', 'Bar manager at Cantina OK! around its 2019 opening, known as Happy. Helped shape the venue''s development.', NULL, 'Sydney'),
    ('alex.sepulchro', 'Alex Sepulchro', 'Head of bar for SubAstor, Bar Astor and Bar do Cofre in São Paulo, responsible for cocktail menus and concepts. Won the Brazilian stage of the Chivas Masters in 2018.', NULL, 'São Paulo'),
    ('alex.skarlen', 'Alex Skärlén', 'Stockholm bartender who co-founded Lucy''s Flower Shop with Ola Carlson. Previously worked in bars in London, New York and Paris, and is known for house-made vinegars in drinks.', NULL, 'Stockholm'),
    ('alicja.baczyk', 'Alicja Bączyk-Mazur', 'Bar manager and co-owner of TAG. in Kraków. She won Diageo World Class Poland in 2022 and placed fourth in the global final that year.', NULL, 'Kraków'),
    ('alina.lucia', 'Alina Lucia', 'Co-owner and operational director of Flying Dutchmen Cocktails, where she started as a bartender. Runs day-to-day operations and team management.', NULL, 'Amsterdam'),
    ('alyssa.heidt', 'Alyssa Heidt', 'Beverage creative director for Four Seasons Hotel Seoul since October 2022, shaping the Charles H. menus alongside the head bartender. Earlier worked at The Violet Hour and in the Alinea Group, contributing to The Aviary Cocktail Book.', NULL, 'Seoul'),
    ('amanda.cheung', 'Amanda Cheung', 'Hong Kong food and beverage operator who worked with Shingo Gokan to create Gokan. Known for the 888FatFatFat pop-up alongside Russell Stradmoor.', NULL, 'Hong Kong'),
    ('andre.gerges', 'Andre Gerges', 'Business partner in Electric Bing Sutt and later Dead End Paradise in Beirut, alongside Jad Ballout and Xin Lin.', NULL, 'Beirut'),
    ('andreas.bergman', 'Andreas Bergman', 'Stockholm restaurateur and co-owner of the 20-gruppen group behind Tjoget and its sister venues. Publicly described as an award-winning bartender turned operator.', NULL, 'Stockholm'),
    ('andres.rolando', 'Andrés Rolando', 'Buenos Aires restaurateur named as an owner of Nicky Harrison, the sushi restaurant and hidden speakeasy in Palermo. He is also associated with other city venues including Uptown BA and Trade Sky Bar.', NULL, 'Buenos Aires'),
    ('andrew.yap', 'Andrew Yap', 'Singapore hospitality operator who launched The Old Man Singapore in 2019 and later rebranded it as Papa Doble. He spent eight years in Hong Kong, where he directed the opening of Stockton, before returning to Singapore.', NULL, 'Singapore'),
    ('angelo.sparvoli', 'Angelo Sparvoli', 'Started as a barback at The Savoy''s American Bar in 2016, worked up to senior bartender, and returned as head bartender in March 2024 before leaving in January 2026.', NULL, 'London'),
    ('angus.zou', 'Angus Zou', 'Bartender who won Diageo World Class Taiwan in 2009 and founded Draft Land, the cocktails-on-tap concept that grew from Taipei to Hong Kong and beyond.', NULL, 'Taipei'),
    ('anna.sebastian', 'Anna Sebastian', 'Bar manager at Artesian from late 2017, joining with Remy Savage from Little Red Door. Co-developed the Moments menu launched in April 2018.', NULL, 'London'),
    ('anthony.callegari', 'Anthony Callegari', 'Bars manager at The London EDITION, where he runs the Punch Room and led its 2022 relaunch menu and the 2025 recipe book.', NULL, 'London'),
    ('anton.forte', 'Anton Forte', 'Bartender who co-founded Sydney''s Swillhouse Group in 2008 and is its CEO. The group opened Shady Pines Saloon and The Baxter Inn in 2010.', NULL, 'Sydney'),
    ('antonio.lai', 'Antonio Lai', 'Hong Kong bartender who opened Quinary in 2012 and made it a pioneer of multisensory, molecular-style mixology. Co-owner of Tastings Group and co-founder of The Opposites and Draft Land. Trained under Tony Conigliaro in London.', NULL, 'Hong Kong'),
    ('antonio.parlapiano', 'Antonio Parlapiano', 'Co-founder of the Jerry Thomas Project in Rome, one of the four bartenders who opened the speakeasy in 2010.', NULL, 'Rome'),
    ('arathorn.grey', 'Arathorn Grey', 'Head bartender of Tippling Club in its final years. He created the 2023 ''Guide to Modern Drinking, Volume III: 6 Decades of Music'' menu of 31 drinks.', NULL, 'Singapore'),
    ('ariel.leizgold', 'Ariel Leizgold', 'Tel Aviv bartender and restaurateur who opened the city''s first cocktail bar, 223, in 2008 and later founded Bellboy and its Butler speakeasy. He reached the final six of Diageo World Class 2015 and teaches a storytelling-through-cocktails masterclass.', NULL, 'Tel Aviv'),
    ('arkadiusz.rybak', 'Arkadiusz Rybak', 'Mixology master on DarkSide''s opening team in 2019 and director of bars at Rosewood Hong Kong by 2022, when the bar reopened with a menu of forgotten classics.', NULL, 'Hong Kong'),
    ('arnon.hoontrakul', 'Arnon Hoontrakul', 'Restaurateur and bar owner known as KK, who conceived Opium Bar around the history of the Potong building and the ''liquid surreality'' concept. Owns restaurants, bars and coffee shops in Thailand and France.', NULL, 'Bangkok'),
    ('arron.grendon', 'Arron Grendon', 'Head bartender at Tropic City in Bangkok according to Difford''s Guide, and winner of the Global Chivas Masters in 2018.', NULL, 'Bangkok'),
    ('artem.peruk', 'Artem Peruk', 'Co-founder of El Copitas and of the Follow The Rabbits bar group in St Petersburg, which also runs Paloma Cantina, Tagliatella Caffe and the Bartenders FAQtory school.', NULL, 'St Petersburg'),
    ('attaporn.desilva', 'Attaporn De-Silva', 'Bartender named by Asia''s 50 Best alongside Niks Anuman-Rajadhon as a creative force behind G.O.D. Earlier bars from the same team centred on gin, wild honey and fermentation.', NULL, 'Bangkok'),
    ('audrey.hands', 'Audrey Hands', 'Joined Rayo in 2024 as head of strategic partnerships and guest experiences and is now its creative and strategy director. Previously worked at Trailer Happiness and for Havana Club.', NULL, 'Mexico City'),
    ('aurelie.panhelleux', 'Aurélie Panhelleux', 'Co-owner of CopperBay, the 10th-arrondissement cocktail bar she opened with two partners in 2014. Trained in hospitality management and worked in luxury hotels and at Le Forum before opening her own bar.', NULL, 'Paris'),
    ('bar.shira', 'Bar Shira', 'Tel Aviv bartender and co-founder of Imperial Craft Cocktail Bar. With his partners he also runs La Otra and Bushwick.', NULL, 'Tel Aviv'),
    ('barney.okane', 'Barney O''Kane', 'Head bartender at Little Red Door until early 2024.', NULL, 'Paris'),
    ('beckaly.franks', 'Beckaly Franks', 'Bar manager on The Pontiac''s opening team in 2015, previously at Portland''s Clyde Common. She led the bar through its early years on Asia''s 50 Best list.', NULL, 'Hong Kong'),
    ('benjamin.padron', 'Benjamin Padrón', 'Founder of Licorería Limantour, which opened in Roma Norte in 2011 and helped launch Mexico City''s craft cocktail movement. He previously worked as a Ketel One brand ambassador.', NULL, 'Mexico City'),
    ('bex.figueiredo', 'Bex Figueiredo', 'Bar manager at Bar Raval, credited with tightening its cocktail program around sherry, vermouth and amaro. Won the Michelin Guide Toronto and Region 2025 Exceptional Cocktails Award.', NULL, 'Toronto'),
    ('billy.gilroy', 'Billy Gilroy', 'Founding partner of Employees Only, who brought the business side to the bar when it opened in the West Village in 2004.', NULL, 'New York'),
    ('bob.louison', 'Bob Louison', 'Director of bars at Rosewood Hong Kong, overseeing the hotel''s bar programmes including DarkSide. Previously worked at Rosewood properties in Saint Barthelemy and Phnom Penh.', NULL, 'Hong Kong'),
    ('bobby.heugel', 'Bobby Heugel', 'Houston bar owner who opened Anvil in 2009 and has since founded The Pastry War (2013), Tongue-Cut Sparrow and Better Luck Tomorrow (2017) and the upstairs bar Refuge (2022). Known for shaping Houston''s drinks scene and for staff training.', NULL, 'Houston'),
    ('bobby.hiddleston', 'Bobby Hiddleston', 'Co-founded Swift in Soho in November 2016 with Mia Johansson and led its bar program. He sold his shares and left the group in summer 2024, with a consultancy role during the handover.', NULL, 'London'),
    ('brent.perremore', 'Brent Perremore', 'Cape Town bartender and consultant known as ''The Rabbit'', with more than 25 years in the trade including London and Cape Town''s underground bars. Co-founder and head bartender of The Art of Duplicity.', NULL, 'Cape Town'),
    ('carina.soto.velasquez', 'Carina Soto Velásquez', 'Co-founder of Quixotic Projects in Paris, the group behind Candelaria, Glass, Le Mary Celeste, Hero and Les Grands Verres. Began as a bartender and moved into ownership and management, and in 2025 took over the bistro À La Renaissance with Joshua Fontaine.', NULL, 'Paris'),
    ('carlos.mora', 'Carlos Mora', 'Bartender, known as Berry, who leads the bar at Arca in Tulum. Earlier worked in London and at Selva in Oaxaca, and acts as a Condesa Gin ambassador.', NULL, 'Tulum'),
    ('carmen.angel', 'Carmen Ángel', 'Chef and founder of the Carmen restaurant group in Medellín, which houses Bar Carmen. She started the restaurant in 2008 with her partner Rob Pevitts and has since added a Cartagena venue.', NULL, 'Medellín'),
    ('celia.schoonraad', 'Celia Schoonraad', 'Bartender and co-founder of Barbary Coast in Singapore, where she was proprietor and creative director. Also creative director of The Compound Collective and holds a master''s in distilling from the Institute of Brewing & Distilling.', NULL, 'Singapore'),
    ('chalee.kader', 'Chalee Kader', 'Chef behind the nose-to-tail restaurant 100 Mahaseth, which sits below Mahaniyom, and named by Chomp as one of the bar''s founders.', NULL, 'Bangkok'),
    ('chanel.adams', 'Chanel Adams', 'Head bartender at The Bamboo Bar, Mandarin Oriental, Bangkok, known for putting hyper-local Thai flavours on the menu. Her Green Mango Bee''s Knees has been a hit at guest shifts in several Asian cities.', NULL, 'Bangkok'),
    ('charles.schumann', 'Charles Schumann', 'Munich bartender and author who opened Schumann''s American Bar in 1982 and moved it to Odeonsplatz in 2003. He wrote the reference books Schumann''s Barbuch and American Bar and is known for a back-to-basics classic-cocktail approach.', NULL, 'Munich'),
    ('charlie.kim', 'Charlie Kim', 'Bar manager of MO Bar at Mandarin Oriental, Singapore, appointed for its late-2023 reopening. Created the Miss Samsui and Mandarin Martini for the Echoes of Singapore menu.', NULL, 'Singapore'),
    ('charlotte.wilde', 'Charlotte Wilde', 'Co-founder of Sager + Wilde with Michael Sager, the east London wine bar business that started with a pop-up and grew to a Hackney Road bar and a Paradise Row restaurant.', NULL, 'London'),
    ('chelsie.bailey', 'Chelsie Bailey', 'Bartender who became head bartender of The Savoy''s American Bar in July 2022, coming from general manager duties at Happiness Forgets in Shoreditch. She led the bar until early 2024.', NULL, 'London'),
    ('chennarong.bhumichitr', 'Chennarong Bhumichitr', 'Bartender known as Jan or Janz who co-founded Mahaniyom in 2022 with Ronnaporn Kanivichaporn. Previously worked at Find the Locker Room.', NULL, 'Bangkok'),
    ('choti.leenutaphong', 'Choti Leenutaphong', 'Restaurateur and co-founder, with Debby Leenutaphong, of Foodie Collection, the Bangkok group behind Vesper, La Dotta, 80/20 and 4th Wall. He opened Vesper in 2014 and steered it toward a cocktail-only format in 2017.', NULL, 'Bangkok'),
    ('chris.moore', 'Chris Moore', 'Founder of Coupette in Bethnal Green, which opened in 2017 and reached the World''s 50 Best Bars list in 2018 and 2019. Bartender with a Savoy background before opening his own bar.', NULL, 'London'),
    ('christina.foka', 'Christina Foka', 'Co-founder of Naked Athens (NKD), with a background in bartending, service and concept development.', NULL, 'Athens'),
    ('christine.williams', 'Christine Williams', 'General manager who became a partner in Clover Club in 2014.', NULL, 'New York'),
    ('cihan.anadologlu', 'Cihan Anadologlu', 'Bartender and author who worked in New York, London and Hong Kong before co-owning Circle in Munich. Wrote the cocktail books Bar Bibel/Bar Bible and created the Mexica cocktail for Patron.', NULL, 'Munich'),
    ('cinthia.mina', 'Cinthia Mina', 'Bar manager at Kaito del Valle, part of the all-women team behind the bar.', NULL, 'Mexico City'),
    ('claudia.cabrera', 'Claudia Cabrera', 'Bartender known as Klaw, with over 20 years behind the bar. She co-founded Kaito del Valle in 2016 and is a vocal advocate for women in bartending. She also works as a brand ambassador and consultant in Mexico City.', NULL, 'Mexico City'),
    ('connor.bloomfield', 'Connor Bloomfield', 'Moved up from bar manager at Swift Shoreditch to head of bars in 2024, overseeing the cocktail programme across the Swift sites in London.', NULL, 'London'),
    ('coral.anderson', 'Coral Anderson', 'With Swift since its 2016 Soho launch, she rose from operations manager to managing director and co-owner in 2024, taking a stake in the business as the founding bar team stepped back.', NULL, 'London'),
    ('craig.schoettler', 'Craig Schoettler', 'Led The Aviary''s first drinks programme after making small edible cocktails for Alinea. He later moved to Las Vegas and is executive director of beverage at MGM Resorts International.', NULL, 'Chicago'),
    ('cristian.bugiada', 'Cristian Bugiada', 'Co-founder of Freni e Frizioni who ran its bar before leaving to open La Punta, and who described the venue as a harbour for a mixed crowd in the bar''s 20th anniversary story.', NULL, 'Rome'),
    ('cross.yu', 'Cross Yu', 'Shanghai bartender who founded E.P.I.C. in 2014 and ran it for a decade. Began in hotel bars and clubs and learned cocktails in 2005. China champion at the 2014 Chivas Masters.', NULL, 'Shanghai'),
    ('daiki.kanetaka', 'Daiki Kanetaka', 'Bartender who runs D.Bespoke in Singapore and mixes its drinks himself. Trained in Tokyo at Star Bar and High Five, later ran a bar in Beijing, and earned a sherry venenciador certification after time in Jerez. Also behind RPM by D.Bespoke.', NULL, 'Singapore'),
    ('damien.guichard', 'Damien Guichard', 'Co-founder of Wax On in Berlin-Neukölln, named Bartender of the Year at the 2024 Mixology Bar Awards.', NULL, 'Berlin'),
    ('dan.binkiewicz', 'Dan Binkiewicz', 'Bar owner and co-owner of Schmuck in New York, and of Sweet Liberty and Medium Cool in Miami and Old Glory in Nashville.', NULL, 'Miami Beach'),
    ('daniel.febrescordero', 'Daniel Febres-Cordero', 'Creative director and co-founder of Juliana in Guayaquil, who helped shape the bar''s concept around Ecuadorian ingredients and its award-winning Diverso menu.', NULL, 'Guayaquil'),
    ('daniel.oconnor', 'Daniel O''Connor', 'Co-founder of Offtrack in Singapore, and part of the Ice Cream Sundays music collective.', NULL, 'Singapore'),
    ('daniel.schofield', 'Daniel Schofield', 'Bartender and co-owner of Schofield''s with his brother Joe, after time at Coupette in London and Little Red Door in Paris.', NULL, 'Manchester'),
    ('daniele.dallapola', 'Daniele Dalla Pola', 'Bologna bartender and co-founder of Nu Lounge, where he built its tiki reputation. Part of the Italian team that won the 42 Below Cocktail World Cup in 2011, later known for Esotico Miami and its Kaona Room.', NULL, 'Bologna'),
    ('danny.punjabi', 'Danny Punjabi', 'Owner of La Borracha, the tequila-focused Mexican cantina in Accra. Featured in an AKADi Magazine interview after the bar joined the 2026 extended World''s 50 Best Bars list.', NULL, 'Accra'),
    ('dario.comini', 'Dario Comini', 'Third-generation bartender who has run Nottingham Forest in Milan since 1980 and became Italy''s best-known molecular mixologist after exploring the technique around 2000. Author of several cocktail books and co-founder of the consultancy Bartender.it.', NULL, 'Milan'),
    ('dario.knox', 'Dario Knox', 'Bartender who created The Other Room in 2016 and built its cask-finished spirits programme. He sold the bar in 2019 and now runs a beverage consultancy.', NULL, 'Singapore'),
    ('darren.lim', 'Darren Lim', 'Co-founder of Vender in Taichung who looks after guests and explains ingredients to them.', NULL, 'Taichung'),
    ('dave.mulligan', 'Dave Mulligan', 'Founder of BAR 1661 in Dublin and of the Ban poitin brand. He opened the bar in 2019 to bring poitin back into Irish cocktail culture, and also runs the sister venue The Sackville Lounge.', NULL, 'Dublin'),
    ('david.andrle', 'David Andrle', 'Bar manager at Hemingway Bar Prague, quoted in 2025 on the bar''s approach to cocktails as a full sensory experience during the move to its new site.', NULL, 'Prague'),
    ('david.barzelay', 'David Barzelay', 'Chef and owner of the two-Michelin-star Lazy Bear, who opened True Laurel with Nicolas Torres as its bar-forward sibling.', NULL, 'San Francisco'),
    ('david.donde', 'David Donde', 'Cape Town entrepreneur who co-founded The Art of Duplicity with bartender Brent Perremore. The speakeasy opened in October 2018.', NULL, 'Cape Town'),
    ('david.kaplan', 'David Kaplan', 'Co-owner of Death & Co, which he helped open in New York in 2006, and partner in Proprietors LLC. Co-author of Death & Co and Cocktail Codex.', NULL, 'Los Angeles'),
    ('david.martinez', 'David Martinez', 'Miami restaurateur and partner in Café La Trova. He is also a co-founder of Sweet Liberty and is linked to Michy''s and Sra. Martinez.', NULL, 'Miami'),
    ('david.nyamekye', 'David Nyamekye', 'Co-founder of Front/Back in Accra. Helped lead the first Accra Bar Show in March 2024, aimed at building shared knowledge across the city''s hospitality trade.', NULL, 'Accra'),
    ('david.rocha', 'David Rocha', 'Bartender and co-founder of Form + Matter (FO+MA) in Mexico City. He met his co-founders while working at Handshake.', NULL, 'Mexico City'),
    ('david.villalon', 'David Villalón', 'Sommelier and co-owner who runs Angelita''s wine bar and cellar of thousands of references, alongside his brother Mario''s cocktail bar.', NULL, 'Madrid'),
    ('davide.cavallari', 'Davide Cavallari', 'Co-founder of Nu Lounge in Bologna and one of the four partners behind its September 2025 relaunch.', NULL, 'Bologna'),
    ('dean.chew', 'Dean Chew', 'Co-founder of Offtrack, the music-led bar and restaurant at 34 North Canal Road, Singapore, opened in 2022. Also known as a DJ and co-founder of the Darker Than Wax collective.', NULL, 'Singapore'),
    ('debby.leenutaphong', 'Debby Leenutaphong', 'Co-founder of Foodie Collection with Choti Leenutaphong and co-creator of Vesper, which opened in Bangkok in 2014. The group also runs La Dotta, 80/20 and 4th Wall.', NULL, 'Bangkok'),
    ('demie.kim2', 'Demie Kim', 'Was head bartender at Alice Cheongdam in 2019 after time at a Seoul hotel bar. Created the Green Thumb and Stay Here cocktails.', NULL, 'Seoul'),
    ('desiree.silva', 'Desiree Jane Silva', 'Co-founder of Sago House, a Singapore bartender who previously worked at 28 HongKong Street and EC Proof. She has spoken publicly about hospitality being the bar''s first priority.', NULL, 'Singapore'),
    ('devon.tarby', 'Devon Tarby', 'Bartender and partner in Proprietors LLC, which helped open Death & Co Los Angeles. Co-author with Alex Day and David Kaplan on the Death & Co: Welcome Home recipe book.', NULL, 'Los Angeles'),
    ('dinos.constantinides', 'Dinos Constantinides', 'Creator of Lost + Found Drinkery in Nicosia, which opened in 2013 and has been on the World''s 50 Best Bars list several times. Known for tiki-influenced drinks made with fresh fruit, house syrups and bitters, and filtered ice.', NULL, 'Nicosia'),
    ('don.ranasinghe', 'Don Ranasinghe', 'Bartender-owner and co-founder of Smoke & Bitters in Hiriketiya. He built the bar''s Sri Lankan-ingredient cocktail programme after a decade in London venues.', NULL, 'Dickwella'),
    ('dovile.krauzaite', 'Dovile Krauzaite', 'Co-owner of Savas who handles guests and service, with a background as head of service and sommelier at several Madrid restaurants.', NULL, 'Madrid'),
    ('dror.alterovich', 'Dror Alterovich', 'Tel Aviv bartender and co-founder of Imperial Craft Cocktail Bar, which he opened with two partners and ran for about 13 years. The group also runs the restaurant La Otra and the bar Bushwick.', NULL, 'Tel Aviv'),
    ('dushan.zaric', 'Dushan Zaric', 'One of the five founding partners of Employees Only, which opened in the West Village in November 2004. Trained at Pravda under Dale DeGroff, and later opened Macao Trading Company in Tribeca.', NULL, 'New York'),
    ('edmund.weil', 'Edmund Weil', 'Partner in Speakeasy Entertainment, which owns Swift, Nightjar and Oriole in London. He co-founded Swift in 2016 and remained a principal of the group after the original bar team left in 2024.', NULL, 'London'),
    ('eduardo.nava', 'Eduardo Nava', 'Co-founder of Bar Mauro with his brother Ricardo. He has a background in coffee service, bartending at Limantour and Café Paraíso, and hospitality management.', NULL, 'Mexico City'),
    ('elad.zvi', 'Elad Zvi', 'Miami hospitality operator who co-founded Bar Lab Hospitality and the Broken Shaker with Gabriel Orta. He also helped open Margot Bar & Bistro near Sunset Harbour in 2024.', NULL, 'Miami Beach'),
    ('elina.tabidze', 'Elina Tabidze', 'Moscow restaurateur who, with Galaktion Tabidze, established Insider Bar as part of their restaurant group.', NULL, 'Moscow'),
    ('elon.soddu', 'Elon Soddu', 'Bartender turned owner of Amaro in Kensington. Previously head bartender of the Savoy''s Beaufort Bar and then head of the hotel''s bars until 2021. Announced a second Amaro site in Earl''s Court.', NULL, 'London'),
    ('emanuel.minez', 'Emanuel Minêz', 'Lisbon bar owner behind Red Frog, Monkey Mash and Cais da Praia, and founder of the Lisbon Bar Show in 2014. A finalist for the Havana Club Bar Entrepreneur of the Year award.', NULL, 'Lisbon'),
    ('emilio.giovanazzi', 'Emilio Giovanazzi', 'Head bartender of The American Bar at Gleneagles, leading the team behind its 1920s-styled service and themed menus such as The Rose Compendium.', NULL, 'Auchterarder'),
    ('enric.rebordosa', 'Enric Rebordosa', 'Barcelona hospitality entrepreneur and co-founder, with Lito Baldovinos, of Grup Confiteria, whose venues include La Confiteria, L''Alegria, El Maravillas, Paradiso and Dr. Stravinsky.', NULL, 'Barcelona'),
    ('eom.dohwan', 'Eom Do-hwan', 'Seoul bartender known internationally as Louis Eom. Co-founded Le Chamber in Cheongdam in 2014 and has since built a small group of Seoul cocktail venues around it. A 2010 Diageo World Class runner-up.', NULL, 'Seoul'),
    ('erik.lorincz', 'Erik Lorincz', 'London bartender who was head bartender at The Savoy''s American Bar for around eight years, through its rise to World''s Best Bar in 2017. He opened Kwãnt in Mayfair in 2019 and reopened it on Stratton Street in 2023.', NULL, 'Bratislava'),
    ('erina.yoshida', 'Erina Yoshida', 'Owner and operator of Angel''s Share, who led its move from the East Village to Grove Street and reopening in 2023.', NULL, 'New York'),
    ('esmeralda.castrogiovanni', 'Esmeralda Castrogiovanni', 'Head bartender at Atlas in Singapore, where she created the 2026 Daughters of ATLAS cocktail menu.', NULL, 'Singapore'),
    ('evan.stroeve', 'Evan Stroeve', 'Sydney bartender who helped run Re''s bar and later co-launched the mistelle label RHUBI with Tim Philips-Johansson.', NULL, 'Sydney'),
    ('fabio.lapietra', 'Fabio La Pietra', 'Italian-trained bartender who has directed SubAstor in São Paulo since 2013 and drives its Biomes of Brazil menus, working with a botanist on native ingredients.', NULL, 'São Paulo'),
    ('federico.balzarini', 'Federico Balzarini', 'Bartender who took over Argo''s beverage programme at Four Seasons Hotel Hong Kong in March 2023. Before Hong Kong he worked at Vesper in Bangkok, Hubbard & Bell in London and The Savoy''s American Bar.', NULL, 'Hong Kong'),
    ('federico.daniele', 'Federico Daniele', 'Bartender who manages the bar at Boadas Cocktails in Barcelona under owners Simone Caporale and Marc Alvarez.', NULL, 'Barcelona'),
    ('federico.pavan', 'Federico Pavan', 'Director of mixology at the Donovan Bar, Brown''s Hotel, where he led the 2026 Our Way menu with Salvatore Calabrese.', NULL, 'London'),
    ('fernando.crespo', 'Fernando Crespo', 'Co-founder of Otro Bar, the San José cocktail room that opened in 2025.', NULL, 'San José'),
    ('flavius.bodescu', 'Flavius Bodescu', 'Head bartender at Nu Lounge in Bologna, continuing from the bar''s earlier team into its 2025 relaunch.', NULL, 'Bologna'),
    ('francesco.immorlano', 'Francesco Immorlano', 'Bartender who moved from Zuma Dubai, where he was bar supervisor, to become head bartender and assistant bar manager at Ergo. In September 2024 he was named bars manager at SLS Dubai.', NULL, 'Dubai'),
    ('francis.stansky', 'Francis Stansky', 'Bar manager at Pacific Cocktail Haven, credited on the bar''s site as the creator of the Eggplant Wizard.', NULL, 'San Francisco'),
    ('freddy.andreasson', 'Freddy Andreasson', 'Co-founder and figurehead of El Gallo Altanero in Guadalajara, known for backing independent agave distillers and collaborating with producers on small-batch bottlings. Peer-voted Altos Bartenders'' Bartender in 2026.', NULL, 'Guadalajara'),
    ('gabriel.fullen', 'Gabriel Fullen', 'Executive at Grupo Locale, the hospitality group that owns Exímia, where he is named as one of the two owners alongside Nicholas Fullen.', NULL, 'São Paulo'),
    ('gabriel.gan', 'Gabriel Gan', 'Principal bartender at Gibson in Singapore, leading the bar team for over ten years alongside senior bartenders Jarryl Goh and Reina Hsu.', NULL, 'Singapore'),
    ('gabriel.lowe', 'Gabriel Lowe', 'Co-founder of Cat Bite Club in Singapore. Opened several bars in Bogota and was beverage director for The Standard''s Bangkok launch in 2019.', NULL, 'Singapore'),
    ('gabriel.orta', 'Gabriel Orta', 'Miami bartender and hospitality operator who co-founded Bar Lab Hospitality and the Broken Shaker in 2012. Bar Lab has grown to over 20 venues across several US cities and Madrid.', NULL, 'Miami Beach'),
    ('galaktion.tabidze', 'Galaktion Tabidze', 'Moscow restaurateur who, with Elina Tabidze, established Insider Bar as part of their restaurant group.', NULL, 'Moscow'),
    ('gen.yamamoto', 'Gen Yamamoto', 'Tokyo bartender who returned from New York, where he managed the bar at Japanese restaurant Brushstroke, to open his own eight-seat bar in Azabu-Juban. He is known for the cocktail omakase format built on seasonal produce.', NULL, 'Tokyo'),
    ('george.kavaklis', 'George Kavaklis', 'Co-founder and owner of Barro Negro, Athens'' first tequila and mezcal bar, opened in 2019 with Stelios Papadopoulos.', NULL, 'Athens'),
    ('german.sitz', 'Germán Sitz', 'Co-founder of the Buenos Aires restaurant Niño Gordo and one of the partners behind Victor Audio Bar, where his team runs the kitchen.', NULL, 'Buenos Aires'),
    ('gilad.livnat', 'Gilad Livnat', 'Tel Aviv bartender and co-founder of Imperial Craft Cocktail Bar. With his partners he also runs La Otra and Bushwick.', NULL, 'Tel Aviv'),
    ('gilfredo.martinez', 'Gilfredo Martínez', 'Head bartender at Bar Carmen in Medellín, working alongside bar director Maycoll Tobón. Known in the team as Gil.', NULL, 'Medellín'),
    ('gina.barbachano', 'Gina Barbachano', 'Bartender who leads the Hanky Panky team and became a business partner in the bar around 2021. She helped shape its travel-inspired menus and international guest takeovers.', NULL, 'Mexico City'),
    ('gintautas.arlauskas', 'Gintautas Arlauskas', 'Bartender and co-owner of Savas, who makes the bar''s classic-based drinks with house infusions and syrups.', NULL, 'Madrid'),
    ('giorgio.santambrogio', 'Giorgio Santambrogio', 'Mixologist and entrepreneur who co-founded Officina Milano in 2016 and runs it as owner and bar manager. Entered bartending with no formal background and focuses on atmosphere and service alongside the drinks.', NULL, 'Milan'),
    ('giulia.cuccurullo', 'Giulia Cuccurullo', 'Head bartender at Artesian, where she has worked since 2018 and took over the bar''s creative direction in 2019. Won the global Patrón Perfectionist competition in 2020.', NULL, 'London'),
    ('goncalo.monteiro', 'Gonçalo de Sousa Monteiro', 'Founder and owner of Berlin''s Buck & Breck, which he opened in 2010 and still works behind. Known for his command of classic cocktails and their history, and for launching the bar''s own London dry gin.', NULL, 'Berlin'),
    ('gordon.purnell', 'Gordon Purnell', 'Bar operator who opened Tigra and Disco Pantera in Sydney with his brother Ross in 2024. Previously worked at Hawksmoor and Panda & Sons.', NULL, 'Sydney'),
    ('grant.achatz', 'Grant Achatz', 'Chef and co-owner of the Alinea Group, which created The Aviary in 2011 as a cocktail counterpart to Alinea. The bar treats drinks with a kitchen''s tools and techniques.', NULL, 'Chicago'),
    ('grant.vangameren', 'Grant van Gameren', 'Toronto chef and restaurateur who opened Bar Raval in 2015. He is also behind other Toronto venues including the Michelin-starred Quetzal, and shapes the bar''s Spanish-influenced food.', NULL, 'Toronto'),
    ('guillaume.quenza', 'Guillaume Quenza', 'Co-founder of Fréquence in Paris, where music sits at the centre of the bar concept. Previously behind the bar at Sherry Butt and Andy Wahloo, and in 2024 was preparing a seasonal restaurant with a cocktail programme in Porto-Vecchio, Corsica.', NULL, 'Paris'),
    ('gunn.lee', 'Gunn Lee', 'Business partner of Niks Anuman-Rajadhon in the group behind five bars around Soi Nana in Bangkok''s Chinatown, G.O.D. among them.', NULL, 'Bangkok'),
    ('gus.vocke2', 'Gus Vocke', 'Partner in Tres Monos in Buenos Aires, joining Sebastián Atienza and Charly Aguinsky, and part of the team behind Victor Audio Bar.', NULL, 'Buenos Aires'),
    ('hayden.lambert', 'Hayden Lambert', 'Owner and lead bartender of Above Board, a small Collingwood bar built around a short list of cocktails he can make perfectly. He trained at the Merchant Hotel in Belfast and at Bar Americano before opening in Melbourne.', NULL, 'Melbourne'),
    ('hedda.bruce', 'Hedda Bruce', 'Bar manager at Tjoget, having joined about six years before she stepped up to the role. Recognised for bartending in Sweden.', NULL, 'Stockholm'),
    ('hidetsugu.ueno', 'Hidetsugu Ueno', 'Owner-bartender of Bar High Five in Ginza, who trained for nearly two decades at Tokyo''s Star Bar under Hisashi Kishi before opening his own bar in 2008. He is one of Japan''s best-known bartenders and tours the bar''s guest shifts worldwide.', NULL, 'Tokyo'),
    ('hisashi.kishi', 'Hisashi Kishi', 'Owner and head bartender of Star Bar Ginza. In 1996 he became the first Japanese bartender to win the IBA world cocktail championship, and he later directed technical research at the Nippon Bartenders Association. Known for classic technique and mentoring.', NULL, 'Tokyo'),
    ('hugo.togni', 'Hugo Togni', 'Co-founder and general manager of Bar Pompette, from Alsace in France, with a fine-dining background in Michelin-starred kitchens. Runs day-to-day operations and started at Pompette as a bartender.', NULL, 'Toronto'),
    ('iain.griffiths', 'Iain Griffiths', 'Australian-trained bartender who co-created White Lyan and Dandelyan with Ryan Chetiyawardana, and later launched the Trash Tiki project and Bar Snack in New York.', NULL, 'London'),
    ('igor.hadzismajlovic', 'Igor Hadzismajlovic', 'Founding partner of Employees Only in New York (2004) and of its Singapore outpost, which opened in 2016. Began as a bartender at Pravda before founding the West Village bar.', NULL, 'New York'),
    ('igor.zernov', 'Igor Zernov', 'Co-founder of El Copitas and of the Follow The Rabbits bar group in St Petersburg. The group also runs Paloma Cantina, Tagliatella Caffe and the Bartenders FAQtory school.', NULL, 'St Petersburg'),
    ('ismael.martinez', 'Ismael Martínez', 'Bartender on the Hanky Panky core team since its early years, and a business partner in the bar. He travels with the team on international guest shifts.', NULL, 'Mexico City'),
    ('ivy.mix', 'Ivy Mix', 'Bartender and author who opened Leyenda in Brooklyn in 2015 and co-founded the Speed Rack competition. Now co-owns the Crown Heights wine bar Whoopsie Daisy. Named a 2026 James Beard semifinalist for Outstanding Professional in Cocktail Service.', NULL, 'New York'),
    ('jack.mcgarry', 'Jack McGarry', 'Co-founded The Dead Rabbit on Water Street in 2013 and has run it alone since 2022, growing the brand to Austin and Jersey City with more cities planned. Co-author of two Dead Rabbit books.', NULL, 'New York'),
    ('jad.ballout', 'Jad Ballout', 'Beirut bartender and bar owner. Opened Electric Bing Sutt in 2018, then rebuilt as Dead End Paradise in 2021 after the 2020 port explosion. Later launched a Barcelona sibling of Dead End Paradise, reported in 2023.', NULL, 'Beirut'),
    ('james.tune', 'James Tune', 'Restaurateur and co-owner of Katana Kitten, alongside Masahiro Urushido and Greg Boehm.', NULL, 'New York'),
    ('james.wheeler', 'James Wheeler', 'Joined Dandelyan as assistant general manager in March 2015 and helped steer it into Lyaness. He later took over as director of Lyan Bars, overseeing Lyaness and Seed Library among other venues.', NULL, 'London'),
    ('jamie.boudreau', 'Jamie Boudreau', 'Bartender and owner of Canon in Seattle, who designed its backbar of roughly 4,000 spirit labels. Author of The Canon Cocktail Book.', NULL, 'Seattle'),
    ('jared.merlino', 'Jared Merlino', 'Sydney bar owner who co-founded The Lobo Plantation in 2013 after years with Merivale, including running Ivy Pool Club. Also owns Kittyhawk and Big Poppa''s.', NULL, 'Sydney'),
    ('jason.kosmas', 'Jason Kosmas', 'Founding partner of Employees Only in New York, which opened in 2004 and celebrated its 20th anniversary in December 2024. Part of the original Pravda-trained team behind the bar.', NULL, 'New York'),
    ('jason.scott', 'Jason Scott', 'Edinburgh bar owner who co-founded Bramble with Mike Aikman, then Lucky Liquor Co (2013) and The Last Word Saloon (2012). The team also makes spirits and liqueurs under the Mothership umbrella.', NULL, 'Edinburgh'),
    ('javier.de.las.muelas', 'Javier de las Muelas', 'Barcelona bartender and entrepreneur who founded Gimlet in 1979 and took over Dry Martini in 1996, turning it into an international bar brand with outposts on several continents. He also consults for hotel groups and created the Droplets flavouring line.', NULL, 'Barcelona'),
    ('jay.cozma', 'Jay Cozma', 'General manager of The Baxter Inn in 2022, named Bar Manager of the Year that year. Previously managed Shady Pines Saloon within Swillhouse.', NULL, 'Sydney'),
    ('jay.gray', 'Jay Gray', 'Co-founder of Sago House and its former CEO. He worked behind bars in Europe and Australia and was Southeast Asia brand ambassador for Monkey Shoulder before opening Sago House in 2020. He now leads Idle Hands.', NULL, 'Singapore'),
    ('jeff.bell', 'Jeff Bell', 'Joined PDT as a barback in 2010, rose to head bartender and bought the bar and Crif Dogs in 2020. Former Diageo World Class Bartender of the Year.', NULL, 'New York'),
    ('jeffrey.chang', 'Jeffrey Chang', 'Bartender and co-founder of AHA Saloon, winner of Diageo World Class Taiwan in 2014 and eighth at the global final.', NULL, 'Taipei'),
    ('jen.queen', 'Jen Queen', 'General manager and mezcalier at The Pontiac in Hong Kong with more than twenty years in the industry. She led the bar''s tenth-anniversary menu in 2025.', NULL, 'Hong Kong'),
    ('jeremy.blackmore', 'Jeremy Blackmore', 'Co-owner of Cantina OK! in Sydney and co-founder of Mucho Group, which also runs Tio''s Cerveceria and Centro 86.', NULL, 'Sydney'),
    ('jesse.vida', 'Jesse Vida', 'Former head bartender at Atlas, which he joined in late 2018, and co-founder of Singapore''s Cat Bite Club. Earlier worked at Booker and Dax, The Dead Rabbit and BlackTail in New York.', NULL, 'Singapore'),
    ('jessica.hutchinson', 'Jessica Hutchinson', 'Co-founder of No Sleep Club, where she handled the guest experience and day-to-day running of the bar alongside Juan Yi Jun.', NULL, 'Singapore'),
    ('jillian.vose', 'Jillian Vose', 'Beverage director at The Dead Rabbit until 2022 and co-author of The Dead Rabbit: Mixology & Mayhem. She left with Sean Muldoon to work on a Charleston venture.', NULL, 'New York'),
    ('jim.meehan', 'Jim Meehan', 'Bartender and author who opened PDT in 2007 and wrote the PDT Cocktail Book. Earlier worked at Gramercy Tavern and Pegu Club. Stepped back from day-to-day PDT in 2014 after moving to Portland.', NULL, 'New York'),
    ('jimmy.barrat', 'Jimmy Barrat', 'Bartender and bar developer who spent about 15 years at Zuma, latterly as global bar development director, before opening Ergo at The Dubai EDITION in 2022. Reached the World Class final in 2012 and is credited with the Tomatini.', NULL, 'Dubai'),
    ('joaquin.simo', 'Joaquin Simo', 'Bartender who spent five and a half years on the opening team at Death & Co before becoming a partner in Alchemy Consulting and Pouring Ribbons. Known for concept-driven menus plotted on a grid.', NULL, 'New York'),
    ('joash.conceicao', 'Joash Conceicao', 'Head bartender at Offtrack, running its cocktail programme. Formerly at Jigger and Pony.', NULL, 'Singapore'),
    ('joe.schofield', 'Joe Schofield', 'Bartender who led the Tippling Club bar from 2016 after The Savoy in London. He developed its scent-based Sensorium menu and the gummy-bear Dreams and Desires menu with Ryan Clift.', NULL, 'Manchester'),
    ('joe.villanueva', 'Joe Villanueva', 'Bartender who co-founded The Wise King in Hong Kong''s Soho with Sandeep Kumar. He previously worked at Lobster Bar, another Hong Kong venue that has featured on Asia''s 50 Best Bars.', NULL, 'Hong Kong'),
    ('joel.soderback', 'Joel Söderbäck', 'Stockholm restaurateur and co-owner of the 20-gruppen hospitality group behind Tjoget, Hornstulls Bodega, Liebling and other Stockholm venues.', NULL, 'Stockholm'),
    ('joel.tompkins', 'Joel Tompkins', 'Restaurateur who co-founded the underground restaurant Coach Peaches and, with Toby Cecchini, restored and reopened The Long Island Bar in 2013.', NULL, 'New York'),
    ('johan.evers', 'Johan Evers', 'Stockholm bartender who built and ran A Bar Called Gemma from 2019 until it closed in March 2026, then co-founded the cocktail bar Jokes Aside on Regeringsgatan. Career bartender and competition winner.', NULL, 'Stockholm'),
    ('john.coronado', 'John Coronado', 'Bar manager at Penicillin in Central, Hong Kong, running day-to-day service at the closed-loop sustainable bar.', NULL, 'Hong Kong'),
    ('johneric.concordia', 'Johneric Concordia', 'Chef and co-founder of The Park''s Finest barbecue, who co-founded Thunderbolt next door and leads its Southern-inspired food.', NULL, 'Los Angeles'),
    ('jon.lee.penrose', 'Jon Lee', 'Kuala Lumpur bartender who leads Penrose and sets its approach to drinks. He previously worked at Wildflowers in Kuala Lumpur and Tippling Club in Singapore.', NULL, 'Kuala Lumpur'),
    ('jonathan.bauer', 'Jonathan Bauer', 'Sommelier and co-owner behind Pompette, responsible for wine and operations. Named Meilleur Sommelier de France in 2014, according to Tastet.', NULL, 'Toronto'),
    ('jonathan.gabbay', 'Jonathan Gabbay', 'Beverage manager at Four Seasons Hotel Hong Kong, where he leads the cocktail programme at Argo. He has worked in luxury hospitality across Europe, North America and Asia, and directs the bar''s Argo Exploration menu built around Hong Kong craftspeople.', NULL, 'Hong Kong'),
    ('jorg.meyer', 'Jörg Meyer', 'Hamburg bartender and owner of Le Lion, which he opened in 2007. Creator of the Gin Basil Smash in 2008, and he also runs other Hamburg bars and designs bar concepts for hotels.', NULL, 'Hamburg'),
    ('jose.hinostroza', 'José Luis Hinostroza', 'Executive chef and co-owner of Arca. Trained in California and worked on the research team behind Noma Mexico''s Tulum pop-up before opening Arca in 2015.', NULL, 'Tulum'),
    ('joseluis.leon', 'José Luis León', 'Mexico City bar director who has led Baltra since its start and also directs Licorería Limantour and Xaman. He writes seasonal menus for Baltra, recently framed as travellers'' guides.', NULL, 'Mexico City'),
    ('jose.olivas', 'José Olivas', 'Bartender and co-founder of Form + Matter (FO+MA) in Mexico City, who worked at Handshake before opening the lab-style bar with David Rocha and Po Tsai.', NULL, 'Mexico City'),
    ('joseph.akhavan', 'Joseph Akhavan', 'Paris bartender who founded Mabel, the rum-led speakeasy on rue d''Aboukir. Earlier he trained at Mama Shelter and was head bartender at La Conserverie.', NULL, 'Paris'),
    ('joseph.venanzio', 'Joseph Venanzio', 'Head bartender at Boadas Cocktails in Barcelona, where he works on the bar''s historic classics and a set of modern reinterpretations.', NULL, 'Barcelona'),
    ('josh.harris', 'Josh Harris', 'Founder of the Bon Vivants hospitality group (BVHospitality) and creator of Trick Dog, where he set the twice-yearly menu-reinvention format. Also opened Bon Voyage (2018, closed 2023) and Quik Dog (January 2026, Mission Bay).', NULL, 'San Francisco'),
    ('joshua.boissy', 'Joshua Boissy', 'Co-founded Maison Premiere in Williamsburg in 2011 and runs the hospitality group Premiere Enterprises. Co-author of The Maison Premiere Almanac (2023).', NULL, 'New York'),
    ('joshua.fontaine', 'Joshua Fontaine', 'Co-founder of Quixotic Projects, the Paris group behind Candelaria, Glass and Le Mary Celeste, and in 2025 the takeover of the bistro À La Renaissance. Started in Paris at Experimental Cocktail Club and also founded the Lutèce aperitif brand.', NULL, 'Paris'),
    ('joshua.gil', 'Joshua Gil', 'Chef and co-owner of Mírate, and chef-owner of Mírame in Beverly Hills, known for Alta California takes on regional Mexican cooking.', NULL, 'Los Angeles'),
    ('juandavid.zapata', 'Juan David Zapata', 'Medellín bartender and co-founder of Mamba Negra, where he also leads the Mamba Lab tasting project. He is behind spirits and drinks brands including Selva Gin, Carbón Ron and Juniper, and founded Medellín Cocktail Week in 2025.', NULL, 'Medellín'),
    ('juan.diaz', 'Juan Diaz', 'Owner of El Barón in Cartagena, which he opened in 2013 in a family property on Plaza San Pedro Claver. In 2025 he brought the bar''s cocktails to the Casa Carolina hotel through a menu collaboration.', NULL, 'Cartagena'),
    ('juan.yijun', 'Juan Yi Jun', 'Co-founder and head bartender of No Sleep Club, who wrote its cocktail list. She came to bartending from graphic design and trained at Tippling Club and Operation Dagger before opening her own bar.', NULL, 'Singapore'),
    ('julia.momose', 'Julia Momosé', 'Bartender turned restaurateur who opened Kumiko in 2018 and became its executive chef in December 2024. She is known for shochu cocktails and her spirit-free drink programme, and led the Cocktails For Hope campaign for takeaway drinks in Illinois.', NULL, 'Chicago'),
    ('julian.short', 'Julian Short', 'Johannesburg bartender who has led the drinks at Sin+Tax since it opened in 2016 and holds a share in the bar. He was approached by the founders to shape the concept and is credited with its seasonal menus.', NULL, 'Johannesburg'),
    ('julie.reiner', 'Julie Reiner', 'Brooklyn bar owner behind Clover Club, an early figure in New York''s craft cocktail revival, and a mentor to many bartenders. She also co-founded Flatiron Lounge, Leyenda and Milady''s.', NULL, 'New York'),
    ('julien.lopez', 'Julien Lopez', 'Co-founder of CopperBay in Paris, which opened in late 2014. Also linked to the CopperBay sister bar in Marseille.', NULL, 'Paris'),
    ('juliette.larrouy', 'Juliette Larrouy', 'Co-founder and beverage director of Schmuck in New York. Formerly beverage director at Two Schmucks in Barcelona, and earlier worked at Le Syndicat in Paris.', NULL, 'New York'),
    ('julio.bermejo', 'Julio Bermejo', 'Son of the founders of Tommy''s and the person who runs its tequila-focused bar. Created the Tommy''s Margarita in 1990 and is a long-time educator on 100% agave tequila. The restaurant''s site says he is recognized by Mexico''s tequila chamber (CNIT) as its North American Tequila Ambassador.', NULL, 'San Francisco'),
    ('julio.cabrera', 'Julio Cabrera', 'Cuban-trained cantinero who founded Café La Trova in 2019 and is a leading voice for the cantinero tradition in the US. He studied cantinero craft in Cuba in 1989, worked in Italy and Mexico, and led bar programs in Miami at Michy''s and Sra. Martinez.', NULL, 'Miami'),
    ('kae.yin', 'Kae Yin', 'Bartender who co-founded AHA Saloon and won Diageo World Class Taiwan in 2012, then placed third globally. After AHA closed he opened Wu (Nothingness) in Taipei.', NULL, 'Taipei'),
    ('kaito.ohba', 'Kaito Ohba', 'Bartender who co-leads the bar at Gokan in Central, Hong Kong. Tatler describes his approach as classic Japanese bartending. He came to Gokan from Bar Beso in Osaka.', NULL, 'Hong Kong'),
    ('kaled.derouiche', 'Kaled Derouiche', 'Bartender who has led the bar programme at Andy Wahloo in Paris, working there since 2013 and returning as bar manager in late 2021. Created a Suntory whisky cocktail series there in 2016.', NULL, 'Paris'),
    ('kaori.kurakami', 'Kaori Kurakami', 'Head bartender at Bar High Five in Ginza, where she works alongside owner Hidetsugu Ueno building drinks from guest conversation. She also has her own section of specials on the bar''s menu.', NULL, 'Tokyo'),
    ('katy.ghale', 'Katy Ghale', 'Co-founder of Penicillin, Hong Kong''s first closed-loop sustainable bar, opened in November 2020 with Agung Prabowo, Laura Prabowo and Roman Ghale.', NULL, 'Hong Kong'),
    ('kenta.goto', 'Kenta Goto', 'Tokyo-trained bartender who worked at Pegu Club before opening his own bar on the Lower East Side in 2015. Runs Bar Goto and its Brooklyn sibling, Bar Goto Niban.', NULL, 'New York'),
    ('kevin.diedrich', 'Kevin Diedrich', 'Founder and owner of Pacific Cocktail Haven in San Francisco, which he opened in 2016. Creator of its signature Leeward Negroni and a leading voice for Asia-Pacific flavours in cocktails.', NULL, 'San Francisco'),
    ('kevin.floyd', 'Kevin Floyd', 'Co-opened Anvil Bar & Refuge in 2009 with Bobby Heugel. Around 2017 the two separated their business interests and he gave up his stake in Anvil, The Pastry War and The Nightingale Room.', NULL, 'Houston'),
    ('kojo.aidoo', 'Kojo Aidoo', 'Co-founder of Front/Back in Accra, where he works as general manager. Helped lead the first Accra Bar Show in March 2024, a trade event for the city''s hospitality industry.', NULL, 'Accra'),
    ('konstantin.plesovskikh', 'Konstantin Plesovskikh', 'Moscow bartender who leads the team at Chainaya and is a co-owner. Started in restaurant service and nightclubs before joining, and works as a brand ambassador for Camus cognac.', NULL, 'Moscow'),
    ('krystian.hordejuk', 'Krystian Hordejuk', 'Beverage director at Galaxy Bar and across the tashas group. He joined tashas in 2017 for the Flamingo Room opening, built Galaxy''s cocktail programme, created its Cosmos Club, and wrote the recipes for the bar''s 2025 cocktail book.', NULL, 'Dubai'),
    ('krystof.zizka', 'Krystof Zizka', 'Co-founded Maison Premiere in 2011 and co-owns Premiere Enterprises, the design and hospitality firm behind it. Co-author of The Maison Premiere Almanac (2023).', NULL, 'New York'),
    ('kurt.schlechter', 'Kurt Schlechter', 'Cape Town bartender with more than 25 years in the trade, founder and owner of Cause Effect. He trains bartenders across Africa and in 2026 was appointed director of education for Cape Town Cocktail Week.', NULL, 'Cape Town'),
    ('lahiru.perera', 'Lahiru Perera', 'Co-founder and chef of Smoke & Bitters, who leads the wood-fire kitchen that sits alongside the cocktail programme. Known as Lalla.', NULL, 'Dickwella'),
    ('laura.hernandez.espinosa', 'Laura Hernández Espinosa', 'Sommelier and anthropologist who founded and directs La Sala de Laura in Bogotá. Works on what she calls Colombian liquid gastronomy, with house Territorio distillates tied to the country''s ecosystems and indigenous drink traditions.', NULL, 'Bogotá'),
    ('laura.prabowo', 'Laura Prabowo', 'Co-founder and managing director of Penicillin in Central, Hong Kong, the city''s first closed-loop sustainable bar, which opened in November 2020.', NULL, 'Hong Kong'),
    ('leo.robitschek', 'Leo Robitschek', 'Bartender who built the drinks programmes at Eleven Madison Park and the NoMad hotels in New York, Los Angeles and Las Vegas. Now creating the menu for NoMad Bar Miami.', NULL, 'New York'),
    ('leonardo.leuci', 'Leonardo Leuci', 'Co-founder of the Jerry Thomas Project in Rome, opened in 2010. Former bar manager at Supperclub Rome, and a driving force behind the Vermouth del Professore line and Italian classic-cocktail revival.', NULL, 'Rome'),
    ('leslie.cofresi', 'Leslie Cofresí', 'Bartender and co-owner of La Factoría, who later set up Licorería Miramar, a supply business for local bars. Previously worked at Santaella.', NULL, 'San Juan'),
    ('liana.oster', 'Liana Oster', 'Bartender who has directed drinks at NoMad London, including Side Hustle and Nomad Bar, since 2022. Before that she rose from bartender to head bartender and bar manager at Dante in New York, and started at Bar Americano in Melbourne.', NULL, 'London'),
    ('lim.byungjin', 'Lim Byung-jin', 'Seoul bartender, known as BJ Lim, who owns and runs Bar Cham. He champions Korean spirits and native ingredients in modern cocktails and also operates the nearby bar Pomme.', NULL, 'Seoul'),
    ('lim.jaejin', 'Lim Jae-jin', 'Bartender who co-founded Le Chamber in 2014 with Eom Do-hwan. A Diageo World Class competitor who finished fourth in 2009.', NULL, 'Seoul'),
    ('linden.pride', 'Linden Pride', 'Hospitality operator who bought Dante with Nathalie Hudson in 2015 and led its rise to number one on The World''s 50 Best Bars in 2019. He oversaw its 2025 Claridge''s residency.', NULL, 'New York'),
    ('lissa.barquero', 'Lissa Barquero', 'Creative director of Otro Bar, credited alongside the founders with the room''s design that pairs preserved 1905 woodwork with stainless steel and a visible lab.', NULL, 'San José'),
    ('lito.baldovinos', 'Lito Baldovinos', 'Barcelona hospitality entrepreneur and co-founder, with Enric Rebordosa, of Grup Confiteria, whose venues include La Confiteria, L''Alegria, El Maravillas, Paradiso and Dr. Stravinsky.', NULL, 'Barcelona'),
    ('lorenza.pezzetta', 'Lorenza Pezzetta', 'Bar manager at Artesian in The Langham, London, with previous experience in private members'' clubs and five-star hotel bars.', NULL, 'London'),
    ('luca.conzato', 'Luca Conzato', 'Co-founder of Freni e Frizioni in Rome, quoted in the bar''s 20th anniversary story on its role in bringing the northern Italian aperitivo ritual to the capital.', NULL, 'Rome'),
    ('luis.miguel.cardona', 'Luis Miguel Cardona', 'Head bartender at Rayo since late 2024, after previously working at Alquimico in Mexico City.', NULL, 'Mexico City'),
    ('lukas.kaufmann', 'Lukas Kaufmann', 'General manager of 28 HongKong Street, representing the bar at its August 2025 guest shift at Bar Albert in Auckland.', NULL, 'Singapore'),
    ('luke.whearty', 'Luke Whearty', 'Bartender who co-founded Operation Dagger in 2015 and led its creative direction until he left in 2019. Earlier he headed the bar at Der Raum in Melbourne and worked at Tippling Club in Singapore.', NULL, 'Melbourne'),
    ('luna.orellano', 'Luna Orellano', 'Bar manager at El Barón since 2021, having risen from barback to bartender at the bar after arriving in Cartagena in 2017. She leads the drinks team and developed the Casa Carolina hotel cocktail menu with the bar in 2025.', NULL, 'Cartagena'),
    ('maciej.mazur', 'Maciej Mazur', 'Owner and co-founder of TAG. in Kraków, which opened in 2020 and entered the World''s 50 Best Bars list in 2022. A Diageo World Class 2019 finalist.', NULL, 'Kraków'),
    ('manu.buffara', 'Manu Buffara', 'Curitiba chef named Best Chef of Latin America by Latin America''s 50 Best Restaurants in 2022. She is a partner in Exímia and designed its food menu to sit alongside the cocktails.', NULL, 'São Paulo'),
    ('manu.potoi', 'Manu Potoi', 'Melbourne hospitality operator and business partner in Above Board alongside Hayden Lambert. Also involved with Rockwell & Sons and Bar Liberty.', NULL, 'Melbourne'),
    ('manuel.crespo', 'Manuel Crespo', 'Co-founder of Otro Bar, the San José cocktail room that opened in 2025.', NULL, 'San José'),
    ('marcello.nazareth', 'Marcello Nazareth', 'Partner and co-owner of Guilhotina in São Paulo since its 2016 opening; he spoke about the bar''s 2026 renovation for its tenth anniversary.', NULL, 'São Paulo'),
    ('marcio.silva', 'Márcio Silva', 'Bartender who trained in London from the mid-1990s and later consulted and opened bars across many countries. He helped develop SubAstor in 2009, co-founded Guilhotina in 2016, and is now a partner and the drinks author at Exímia in São Paulo.', NULL, 'São Paulo'),
    ('marco.arrigo', 'Marco Arrigo', 'Coffee specialist who worked with Illy for about twenty years and partnered with Tony Conigliaro to create Bar Termini''s coffee programme.', NULL, 'London'),
    ('marco.maiorano', 'Marco Maiorano', 'Bar manager of DarkSide at Rosewood Hong Kong. He built his career in New York and nine years in London, including the Connaught Bar and Scarfes Bar, before leading DarkSide.', NULL, 'Hong Kong'),
    ('marian.beke', 'Marian Beke', 'Bartender who spent about five years at Nightjar before opening The Gibson in London in 2015. Opened a Gibson in Berlin in 2024 and works with the Bellboy Group.', NULL, 'London'),
    ('mario.farulla', 'Mario Farulla', 'Bar manager of Baccano in Rome at the time it entered the World''s 50 Best Bars list in 2019, after around fifteen years working in London and Dubai. Known for a guest-first, classics-friendly approach.', NULL, 'Milan'),
    ('mario.villalon', 'Mario Villalón', 'Bartender and co-owner who leads Angelita''s cocktail room. Champions ice-free, ferment-driven drinks made with ingredients from his family''s organic farm in Zamora.', NULL, 'Madrid'),
    ('markus.basset', 'Markus Basset', 'Head of bars at The Savoy in London, overseeing the American Bar as of January 2026.', NULL, 'London'),
    ('markus.thesleff', 'Markus Thesleff', 'Founder and CEO of Thesleff Group, the London hospitality company that owns Viajante87 alongside Los Mochis, Sale e Pepe and MA/NA. Around 25 years in restaurants and bars as owner, operator and consultant.', NULL, 'London'),
    ('martin.cate', 'Martin Cate', 'Founder of Smuggler''s Cove in San Francisco and co-author with Rebecca Cate of the James Beard Award-winning book on rum and tiki. Started in transportation logistics before moving into bars.', NULL, 'San Francisco'),
    ('martina.bonci', 'Martina Bonci', 'Bar manager of Gucci Giardino 25 in Florence since its 2022 opening. She spent seven years at Gesto before joining and shapes the bar''s alcoholic and alcohol-free menu around the team''s shared memories.', NULL, 'Florence'),
    ('martine.bauer', 'Martine Bauer', 'Chef and co-owner behind Pompette, the Toronto bistro and bar. She previously cooked at the Official Residence of the French Prime Minister before moving to Canada.', NULL, 'Toronto'),
    ('masa.urushido', 'Masahiro Urushido', 'Bartender who opened Katana Kitten in 2018 after seven years as bar manager at Saxon + Parole. Still works behind the bar. Voted Altos Bartenders'' Bartender by North America''s head bartenders in 2022.', NULL, 'New York'),
    ('mason.park', 'Mason Park', 'Head bartender at Alice Cheongdam, leading the team under owner Terry Kim.', NULL, 'Seoul'),
    ('massimiliano.berardi', 'Massimiliano Berardi', 'Runs the bar team at Angelita, where he works with Mario Villalón on the ice-free approach and speaks publicly about allergen safety in cocktail bars.', NULL, 'Madrid'),
    ('matias.peredo', 'Matías Peredo', 'Original partner of Siete Negronis who helped lead its relaunch at Terrazas San Cristóbal.', NULL, 'Santiago'),
    ('matias.supan', 'Matías Supán', 'Original partner of Siete Negronis who helped lead its relaunch at Terrazas San Cristóbal.', NULL, 'Santiago'),
    ('matt.whiley', 'Matt Whiley', 'London bartender who founded Scout and earlier Purl and Worship Street Whistling Shop. Also known as Talented Mr Fox. Later took Scout to Sydney and opened the low-waste venue Re.', NULL, 'London'),
    ('matteo.cadeddu', 'Matteo Cadeddu', 'Bar manager who leads the drinks programme at Opium Bar in Bangkok. His career in mixology has taken in Amsterdam, Australia, Singapore and Mumbai.', NULL, 'Bangkok'),
    ('matthew.belanger', 'Matthew Belanger', 'Head bartender at Death & Co Los Angeles at its opening, working with beverage director Tyson Buhler on the launch menu.', NULL, 'Los Angeles'),
    ('matthew.egan', 'Matthew Egan', 'Restaurateur and co-owner of Mírate. Brought Max Reis in to lead the venue''s Mexican-spirits beverage program.', NULL, 'Los Angeles'),
    ('matthieu.biron', 'Matthieu Biron', 'Co-founder of Fréquence, the vinyl and cocktail bar in Paris''s 11th arrondissement. Previously worked at Andy Wahloo.', NULL, 'Paris'),
    ('maurice.terzini', 'Maurice Terzini', 'Sydney restaurateur behind Icebergs Dining Room and Bar and the Dolphin Hotel, who partnered with Matt Whiley to open Re.', NULL, 'Sydney'),
    ('mauricio.santana', 'Mauricio Santana', 'Clover Club bar manager who worked his way up from barback.', NULL, 'New York'),
    ('maurizio.gerosa', 'Maurizio Gerosa', 'Co-founder of Nu Lounge in Bologna and one of the four partners behind its September 2025 relaunch.', NULL, 'Bologna'),
    ('max.reis', 'Max Reis', 'Beverage director at Mírate, focused on Mexican agave spirits and small-producer sourcing. Built the bar''s canned cocktails and pulque-led list, and teaches mezcal classes to industry peers.', NULL, 'Los Angeles'),
    ('max.venning', 'Max Venning', 'Runs Three Sheets with his brother Noel. They opened the Dalston original in 2016 and the Soho bar in March 2024, and also run Little Mercies in Crouch End. Known for simple, clean cocktails and early adoption of pre-batching.', NULL, 'London'),
    ('maxim.schulte', 'Maxim Schulte', 'Bartender who took over as head bartender of The Savoy''s American Bar in 2018 and left in 2020. Earlier he ran Kol Mezcaleria in London.', NULL, 'London'),
    ('maxime.hoerth', 'Maxime Hoerth', 'Barman who leads the cocktail program at Bar Pompette. He was named Meilleur Ouvrier de France in 2011, the first barman to earn the title, and previously headed the bar at Hotel Le Bristol in Paris.', NULL, 'Toronto'),
    ('maycoll.tobon', 'Maycoll Tobón', 'Bar director at Bar Carmen in Medellín. He writes the cocktail list around Colombian regional ingredients, using kitchen techniques and a low-waste approach.', NULL, 'Medellín'),
    ('meaghan.dorman', 'Meaghan Dorman', 'Bar director credited with curating Dear Irving''s cocktail list, which pairs New York State spirits with classic and inventive drinks.', NULL, 'New York'),
    ('mia.johansson', 'Mia Johansson', 'Co-founded Swift in Soho in November 2016 with Bobby Hiddleston, alongside the Speakeasy Entertainment partners. She helped lead the Swift bars until selling her shares and leaving in summer 2024.', NULL, 'London'),
    ('micah.melton', 'Micah Melton', 'Joined The Aviary as its ice chef before it opened in 2011, moved up to sous chef for research and development, and became beverage director in October 2014, later overseeing all Alinea Group drinks programmes.', NULL, 'Chicago'),
    ('michael.callahan', 'Michael Callahan', 'Founding barman and general manager of 28 HongKong Street, whose San Francisco cocktail background shaped its American-style approach. Later co-founded Barbary Coast in Singapore with Celia Schoonraad.', NULL, 'Singapore'),
    ('michael.chiem', 'Michael Chiem', 'Co-owner of PS40 and the PS Soda brand in Sydney, and previously of The Lobo Plantation. In 2025 he expanded the bar with PSGO, a restored 1977 RV used as a mobile bar.', NULL, 'Sydney'),
    ('michael.collina', 'Michael Collina', 'Bologna hospitality operator, known for the venues Bamboo and Donkey, and a partner in the reopened Nu Lounge.', NULL, 'Bologna'),
    ('michael.madrusan', 'Michael Madrusan', 'Melbourne bar owner who opened The Everleigh in 2011 and ran it with Zara Madrusan through the Made in the Shade Group. The group also runs Heartbreaker and Navy Strength ice, and the pair published The Madrusan Cocktail Companion in 2025.', NULL, 'Melbourne'),
    ('michael.mcilroy', 'Michael McIlroy', 'Co-owner of Attaboy with Sam Ross, in the former Milk & Honey space on Eldridge Street. Creator of the Greenpoint cocktail, and a Milk & Honey bartender before taking over the room.', NULL, 'New York'),
    ('michael.sager', 'Michael Sager', 'Co-founded the Sager + Wilde wine bars in east London and is now their sole owner. Also behind Sager and Wine, an importer and distributor that supplies the bars.', NULL, 'London'),
    ('michele.mariotti', 'Michele Mariotti', 'Led MO Bar at Mandarin Oriental, Singapore at its 2018 relaunch. Previously worked at The Berkeley and The Savoy in London.', NULL, 'Singapore'),
    ('michelle.bernstein', 'Michelle Bernstein', 'James Beard Award-winning Miami chef who runs the kitchen at Café La Trova and co-founded the bar with Julio Cabrera. She is also a partner behind Sweet Liberty.', NULL, 'Miami'),
    ('michito.kaneko', 'Michito Kaneko', 'Nara bartender who opened Lamp Bar in 2011 and won the Diageo World Class global final in 2015. He later launched the Japanese Sensorium brand and a sake-based vermouth, and hosts overseas trainees.', NULL, 'Nara'),
    ('miguel.bolanos', 'Miguel Bolaños', 'Member of Rayo''s founding team who was promoted to beverage director in October 2024, overseeing the bar''s cocktail program.', NULL, 'Mexico City'),
    ('mike.aikman', 'Mike Aikman', 'Edinburgh bar owner who co-founded Bramble with Jason Scott, then Lucky Liquor Co (2013) and The Last Word Saloon (2012). The team also makes spirits and liqueurs under the Mothership umbrella.', NULL, 'Edinburgh'),
    ('mike.capoferri', 'Mike Capoferri', 'Bartender behind Thunderbolt, which opened in 2019 after years of development, and its sister bar Night on Earth (Dec 2024). Known for technology-driven, low-waste cocktails.', NULL, 'Los Angeles'),
    ('minakshi.singh', 'Minakshi Singh', 'Co-founder of Sidecar and, with Yangdup Lama, of Cocktails & Dreams Speakeasy. She co-owns the Delhi bar.', NULL, 'New Delhi'),
    ('moe.aljaff', 'Moe Aljaff', 'Bartender and co-founder of Two Schmucks in Barcelona, which reached No. 7 on The World''s 50 Best Bars in 2022. He left in October 2022 and later launched Schmuck, a bar in New York''s East Village.', NULL, 'New York'),
    ('mohamed.yazhib', 'Mohamed Yazhib', 'Head bartender at 28 HongKong Street, known as Naz. Travelled with the general manager for the bar''s 2025 Auckland guest shift.', NULL, 'Singapore'),
    ('morris.chang', 'Morris Chang', 'Hong Kong bartender who co-leads Gokan, bringing a more modern style to the bar according to Tatler. Before Gokan he worked at Penicillin in Hong Kong.', NULL, 'Hong Kong'),
    ('mourad.mazouz', 'Mourad Mazouz', 'Paris restaurateur who opened Andy Wahloo in the Marais and owns the neighbouring 404 restaurant. Time Out describes the bar as belonging to the Mazouz brothers.', NULL, 'Paris'),
    ('nadia.rojas', 'Nadia Rojas', 'Head bartender at Otro Bar, leading a research-driven program that works Costa Rican ingredients through clarification, fermentation and infusions.', NULL, 'San José'),
    ('nakul.bhonsle', 'Nakul Bhonsle', 'Craft beer entrepreneur behind Great State Aleworks in Goa, whose beers are brewed for Boilermaker. Co-founded the Siolim bar in 2024.', NULL, 'Goa'),
    ('natasha.sideris', 'Natasha Sideris', 'Restaurateur, founder and CEO of the tashas hospitality group, who created Galaxy Bar in Dubai''s DIFC as a tribute to Athens and its night sky. She co-created the bar''s cocktail book with its beverage director.', NULL, 'Dubai'),
    ('nathalie.hudson', 'Nathalie Hudson', 'Co-owner and creative director of Dante. She and Linden Pride relaunched the cafe in 2015 and expanded to the West Village in 2020.', NULL, 'New York'),
    ('nectaly.mendoza', 'Nectaly Mendoza', 'Las Vegas bar owner who opened Herbs & Rye in 2009 and built its era-by-era classic cocktail menu. Known for insisting on historically faithful recipes rather than modernised ones.', NULL, 'Las Vegas'),
    ('nicholas.fullen', 'Nicholas Fullen', 'Executive at Grupo Locale, the hospitality group that owns Exímia, where he is named as one of the two owners alongside Gabriel Fullen.', NULL, 'São Paulo'),
    ('nick.kennedy', 'Nick Kennedy', 'Co-owner of Civil Liberties and the driving force behind its menu-free approach. Has extended the group with Civil Works and Civil Pours (bottled cocktails), and holds patents for a vacuum-distillation process.', NULL, 'Toronto'),
    ('nick.kokonas', 'Nick Kokonas', 'Business partner of Grant Achatz and co-owner of the Alinea Group, whose venues include The Aviary. He co-authored The Aviary Cocktail Book.', NULL, 'Chicago'),
    ('nick.reid', 'Nick Reid', 'Co-owner of El Gallo Altanero with a long background in the tequila industry. He describes the bar as a platform for small agave distillers to tell their story.', NULL, 'Guadalajara'),
    ('nick.wu', 'Nick Wu', 'Bartender and founder of Bar Mood in Taipei. Trained in clubs, hotels and restaurants and competed in flair before turning to classic technique with Japanese influence, then built a menu around Taiwanese ingredients. Placed third overall at the 2016 World Class global final.', NULL, 'Taipei'),
    ('nico.castro', 'Nico Castro', 'Bartender with about 25 years in the trade who manages the bar at Fifty Mils in Mexico City. He and his team wrote the relaunched menu in 2022.', NULL, 'Mexico City'),
    ('nicolas.torres', 'Nicolas Torres', 'Beverage director and partner at True Laurel, which he co-founded in 2017. Previously built the cocktail program at Lazy Bear. Known for whole-fruit, hyper-seasonal, low-waste cocktails.', NULL, 'San Francisco'),
    ('nikita.matveev', 'Nikita Matveev', 'Bartender who took over operations of The Old Man in Hong Kong after its founding team moved on, and is now described as a co-founder. Earlier competed in Diageo World Class in Russia and Hong Kong and Macau.', NULL, 'Hong Kong'),
    ('nikolay.kiselev', 'Nikolay Kiselev', 'Co-founder of El Copitas and of the Follow The Rabbits bar group in St Petersburg, which also runs Paloma Cantina and Tagliatella Caffe.', NULL, 'St Petersburg'),
    ('niks.anumanrajadhon', 'Niks Anuman-Rajadhon', 'Bangkok bar owner who opened Teens of Thailand in 2015, the country''s first gin-focused bar, and built a cluster of bars on Soi Nana. Those include Asia Today, TAX, Independence Bar and G.O.D.', NULL, 'Bangkok'),
    ('niwarin.phlainoi', 'Niwarin Phlainoi', 'Co-founder of Dry Wave Cocktail Studio, which opened in Bangkok in January 2024. Described by 50 Best as co-creator of the bar with Supawit Muttarattana; goes by Ae.', NULL, 'Bangkok'),
    ('noel.venning', 'Noel Venning', 'Co-owns Three Sheets with his brother Max, from the Dalston bar opened in 2016 to the Soho bar opened in March 2024. The pair also run Little Mercies in Crouch End and have advised restaurants on their cocktail lists.', NULL, 'London'),
    ('noppasate.hirunwathit', 'Noppasate Hirunwathit', 'Head bartender at Rabbit Hole in Bangkok, known as Depp, who has led its menus since at least 2023. Earlier worked at Hyde & Seek, Lady Brett, U.N.C.L.E. and Revolucion, and has won several national bartending competitions.', NULL, 'Bangkok'),
    ('odd.strandbakken', 'Odd Strandbakken', 'Bartender who became head bartender at Four Seasons Hotel Seoul in October 2022, overseeing Charles H. and OUL. Previously at Oslo''s Himkok. Favours house-made ingredients and local producers.', NULL, 'Seoul'),
    ('ola.carlson', 'Ola Carlson', 'Stockholm bartender with about two decades behind the bar and several bar openings behind him. Co-founded Lucy''s Flower Shop with Alex Skärlén in 2019.', NULL, 'Stockholm'),
    ('oliver.eardley', 'Oliver Eardley', 'Hired as head bartender when Little Red Door reopened under new owners in July 2024, after time at the Savoy in London.', NULL, 'Paris'),
    ('ondrej.hnilicko', 'Ondřej Hniličko', 'Head bartender at Hemingway Bar Prague, where e15 reports he has worked for around 15 years.', NULL, 'Prague'),
    ('orestes.pajon', 'Orestes Pajón', 'Cantinero and business partner at Café La Trova, working alongside Julio Cabrera on its Cuban cocktail program.', NULL, 'Miami'),
    ('oscar.jonssonbuhre', 'Oscar Jonsson Buhre', 'Stockholm bartender who was head bartender at Lucy''s Flower Shop before opening his own bar, Bar Kabinett, in August 2026. Known for work with vinegar and fermentation.', NULL, 'Stockholm'),
    ('osman.baycan', 'Osman Baycan', 'Istanbul bartender and operator who founded Bar Gabriel in 2025 after running Goose and Pigalle. Reported as a five-time Turkish national cocktail champion, including wins at Bacardi Legacy (2017) and Diageo World Class (2019), and a mentor to young bartenders.', NULL, 'Istanbul'),
    ('pankaj.balachandran', 'Pankaj Balachandran', 'Bartender, sommelier and consultant. Co-founder of Boilermaker in Goa and of the consultancy Countertop India, and earlier a co-founder of Bar Tesouro. Started at the Taj group and became India''s sommelier champion before moving into cocktails.', NULL, 'Goa'),
    ('pau.maldonado', 'Pau Maldonado', 'Head bartender at Kaito del Valle, part of the all-women team behind the bar.', NULL, 'Mexico City'),
    ('paul.gabie', 'Paul Gabie', 'Co-founder of 28 HongKong Street, which opened in 2011, and of the spirits business Proof & Company. Previously a lawyer in New York before relocating to Singapore.', NULL, 'Singapore'),
    ('paul.lougrat', 'Paul Lougrat', 'Co-founder of A Bar with Shapes for a Name in London, opened in 2021. He previously worked with Remy Savage at The Artesian and champions fast, minimal, approachable drinks at the bar.', NULL, 'London'),
    ('paul.mcgee', 'Paul McGee', 'Chicago bartender who opened Three Dots and a Dash in 2013 and then Lost Lake in 2015, and created its house cocktail. He later made drinks for Secret Sound at Time Out Market Chicago.', NULL, 'Chicago'),
    ('paul.vanderspuy', 'Paul van der Spuy', 'Cape Town menswear designer, founder of the Carducci label, and a founding partner of The House of Machines.', NULL, 'Cape Town'),
    ('paulo.gomes', 'Paulo Gomes', 'Lisbon bartender and co-owner of Red Frog, which he opened with Emanuel Minêz in 2015. Also behind Monkey Mash and 18.68 cocktail boutique, with a focus on classics reworked with kitchen techniques.', NULL, 'Lisbon'),
    ('pedro.pena', 'Pedro Peña', 'Co-founder of the Buenos Aires restaurant Niño Gordo and one of the partners behind Victor Audio Bar, where his team runs the American-influenced kitchen.', NULL, 'Buenos Aires'),
    ('peter.altenburg', 'Peter Altenburg', 'Copenhagen bar owner who ran Gilt from 2003 until it closed in 2020, and opened Bird in Frederiksberg afterwards. He championed a New Nordic approach to cocktails using local ingredients and presented it at the Manhattan Cocktail Classic in 2012.', NULL, 'Copenhagen'),
    ('peter.chua', 'Peter Chua', 'Singapore bartender and operator who opened Night Hawk in 2022. He came up through the opening team at 28 HongKong Street and has worked in spirits education and brand roles, and he also leads education at Bar Convent Singapore.', NULL, 'Singapore'),
    ('philip.stefanescu', 'Philip Stefanescu', 'Bartender and co-founder of Tropic City in Bangkok, which ran from late 2017 to April 2026. Earlier built drink menus for Bangkok venues UNCLE and Lady Brett with Sebastian De La Cruz.', NULL, 'Bangkok'),
    ('po.tsai', 'Po Tsai', 'Restaurateur and co-founder of Form + Matter (FO+MA) in Mexico City. The 50 Best entry lists him as a founder alongside David Rocha and José Olivas.', NULL, 'Mexico City'),
    ('rafael.bercot', 'Rafael Berçot', 'Co-founder of Guilhotina in São Paulo (with Márcio Silva and Marcello Nazareth in 2016) and still one of its owners.', NULL, 'São Paulo'),
    ('raffaello.polchi', 'Raffaello Polchi', 'Owner of the motorcycle workshop next to the courtyard that became Officina Milano, and co-founder of the bar with Giorgio Santambrogio in 2016.', NULL, 'Milan'),
    ('rainer.becker', 'Rainer Becker', 'Chef and restaurateur who founded Zuma, opening the first restaurant in London in 2002 and bringing it to Dubai in 2008. He later launched Roka, Oblix and Inko Nito. A chef by training rather than a bartender.', NULL, 'Dubai'),
    ('ravi.derossi', 'Ravi DeRossi', 'New York bar and restaurant owner who co-opened Amor y Amargo in 2011 and leads Overthrow Hospitality as CEO and founder. He was a founding member of Death & Co and has run venues since 2006.', NULL, 'Los Angeles'),
    ('rebecca.cate', 'Rebecca Cate', 'Co-owner of Smuggler''s Cove with her husband Martin Cate, and co-author of the James Beard Award-winning Smuggler''s Cove book.', NULL, 'San Francisco'),
    ('tato.giovannoni', 'Renato ''Tato'' Giovannoni', 'Bartender and owner of Florería Atlántico in Buenos Aires, which he opened in 2013. He came to bartending through his family''s restaurants and a design career, and builds menus and his own spirits around Argentine ingredients and immigrant history.', NULL, 'Buenos Aires'),
    ('ricardo.nava', 'Ricardo Nava', 'Co-founder of Bar Mauro with his brother Eduardo. He has a background in coffee service, bartending at Limantour and Café Paraíso, and hospitality management.', NULL, 'Mexico City'),
    ('riccardo.rossi', 'Riccardo Rossi', 'Co-founder and bar manager of Freni e Frizioni, who took over the bar programme in Trastevere and shifted it from casual aperitivo toward a technically sharp cocktail list. Has a particular interest in pisco.', NULL, 'Rome'),
    ('rich.woods', 'Rich Woods', 'Hospitality operator who took an equal stake in Scout in 2019 and ran its London operations until closure. Co-founded the drinks agency Weapons and Toys with Matt Whiley.', NULL, 'London'),
    ('richard.wynne', 'Richard Wynne', 'London bar owner who co-founded Callooh Callay in 2008 and later opened the JubJub upstairs bar and Little Bat. Callooh Callay won the Spirited Award for World''s Best Cocktail Menu under his ownership.', NULL, 'London'),
    ('richie.barrow', 'Richie Barrow', 'Group food and beverage general manager for Tribe Hotels Group, who leads Hero''s drinks menu. He is the bar''s main spokesperson on its focus on local ingredients and modern African bartending.', NULL, 'Nairobi'),
    ('rob.pevitts', 'Rob Pevitts', 'Co-owner of the Carmen restaurant group in Medellín, which includes Bar Carmen. He co-founded the business with Carmen Ángel in 2008.', NULL, 'Medellín'),
    ('rob.sloan', 'Rob Sloan', 'Sydney bar operator who co-founded Bulletin Place and ran it with Tim Philips-Johansson to the end. Earlier worked as a spirits brand ambassador.', NULL, 'Sydney'),
    ('roberto.artusio', 'Roberto Artusio', 'Co-founder of the Jerry Thomas Project in Rome, quoted in 2025 on the bar''s Tommy Jirry tequila cocktail.', NULL, 'Rome'),
    ('roberto.berdecia', 'Roberto Berdecía', 'Co-founder of La Factoría and its best-known bartender, shaping the bar''s Puerto Rico-focused cocktail style. Part of the Colectivo Ícaro group behind several San Juan venues.', NULL, 'San Juan'),
    ('rogerio.igarashi', 'Rogerio Igarashi', 'Head bartender at Bar Trench in Ebisu, with more than two decades behind Tokyo bars. Small Axe''s own site calls him chief bartender and notes he has judged international cocktail competitions.', NULL, 'Tokyo'),
    ('roisin.stimpson', 'Roisin Stimpson', 'Partner in Speakeasy Entertainment, the London group behind Swift, Nightjar and Oriole. She co-founded Swift in 2016 and remained a principal of the business after the original bar team left in 2024.', NULL, 'London'),
    ('romain.lemouellic', 'Romain Le Mouëllic', 'Founder of Le Syndicat, the Paris bar opened in 2014 that serves only French spirits. He began as a cocktail blogger before opening the bar, and now also oversees the Féfé cocktail brand.', NULL, 'Paris'),
    ('roman.ghale', 'Roman Ghale', 'Bartender and bar operator who co-founded Penicillin in Hong Kong in 2020 with Agung Prabowo. Earlier he was a co-founder of The Old Man, named Asia''s Best Bar in 2019.', NULL, 'Hong Kong'),
    ('roman.milostivy', 'Roman Milostivy', 'Moscow bartender who founded Chainaya in 2011 after working at bar 30/7, and built its vermouth-led cocktail list. Reported to have since moved to work on a project in Tbilisi.', NULL, 'Moscow'),
    ('ronald.akili', 'Ronald Akili', 'Founder of Potato Head, the hospitality brand that started as a Jakarta restaurant and bar in 2009. He opened Potato Head Beach Club in Seminyak in 2010 and grew the site into Desa Potato Head.', NULL, 'Seminyak'),
    ('ronnaporn.kanivichaporn', 'Ronnaporn Kanivichaporn', 'Bartender known as Neung who co-founded Mahaniyom in 2022 and drives its nose-to-tail Resourceful Cocktail idea. Previously worked at Find the Locker Room.', NULL, 'Bangkok'),
    ('rosa.moolenaar', 'Rosa Moolenaar', 'Co-owner and operational director of Flying Dutchmen Cocktails, where she started as a bartender. Oversees finances and operational consistency.', NULL, 'Amsterdam'),
    ('rosemanon.baux', 'Rose-Manon Baux', 'Co-founder of Wax On in Berlin-Neukölln, named Newcomer of the Year by Mixology in 2023.', NULL, 'Berlin'),
    ('ross.purnell', 'Ross Purnell', 'Bar operator who opened Tigra and Disco Pantera in Sydney with his brother Gordon in 2024, and wrote Tigra''s food menu. Previously worked at Hawksmoor and Panda & Sons.', NULL, 'Sydney'),
    ('ruben.neideck', 'Ruben Neideck', 'Head bartender at Velvet in Berlin-Neukölln, where the menu is built from foraged and seasonal ingredients. Recognised as Bartender of the Year by Mixology Magazine for the DE/AT/CH region.', NULL, 'Berlin'),
    ('russell.stradmoor', 'Russell Stradmoor', 'Hong Kong food and beverage operator who worked with Shingo Gokan to create Gokan. Known for the 888FatFatFat pop-up alongside Amanda Cheung.', NULL, 'Hong Kong'),
    ('rusty.cerven', 'Rusty Cerven', 'Bar manager and co-owner of The Gibson in London. Previously senior mixologist at the Connaught Bar.', NULL, 'London'),
    ('ryan.chetiyawardana', 'Ryan Chetiyawardana', 'London bartender behind the Lyan Bars group (Mr Lyan): Lyaness, Seed Library, Super Lyan in Amsterdam and Silver Lyan in Washington DC. Known for the Closed Loop approach to cutting bar waste and for Dandelyan, which became Lyaness.', NULL, 'London'),
    ('ryan.clift', 'Ryan Clift', 'Chef who founded Tippling Club in 2008 and ran it for 17 years, pairing its tasting menus with a serious bar programme. After it closed he moved back to Australia to lead Skillogalee restaurant in the Clare Valley.', NULL, 'Singapore'),
    ('ryan.liloia', 'Ryan Liloia', 'Clover Club head bartender with a focus on tropical drinks and rum.', NULL, 'New York'),
    ('ryota.tokumitsu', 'Ryota Tokumitsu', 'Head bartender at The SG Club, working the Sip basement bar. Listed on the group''s team page and named by a Bishoku Quest profile of the bar.', NULL, 'Tokyo'),
    ('sacha.molodskikh', 'Sacha Molodskikh', 'Bartender who trained in London bars and co-founded Le Parfum in Montpellier, where he became known for gastronomic ice work and hand-built decor.', NULL, 'Montpellier'),
    ('saharat.kaewkong', 'Saharat Kaewkong', 'Bangkok bartender known as Mac. He was head bartender at Vesper before becoming bar manager at sister bar 4th Wall, and won Diageo World Class Thailand in 2022.', NULL, 'Bangkok'),
    ('sam.orrock', 'Sam Orrock', 'Head bartender and co-founder of Wax On in Berlin-Neukölln. Previously worked at Scout in London, and builds Wax On''s drinks with lab tools such as rotary evaporators and centrifuges.', NULL, 'Berlin'),
    ('sam.ross', 'Sam Ross', 'Co-owner of Attaboy on the Lower East Side, which he and Michael McIlroy took over from Milk & Honey. Creator of the Penicillin and Paper Plane, and partner in around ten bars across New York, Brooklyn and Nashville.', NULL, 'New York'),
    ('samantha.sanford', 'Samantha Sanford', 'Co-owner of Mabel in Paris, which she opened with Joseph Akhavan.', NULL, 'Paris'),
    ('samet.ali', 'Samet Ali', 'Bar director of Oriole in Covent Garden, involved in the bar''s 2024 reopening.', NULL, 'London'),
    ('sandeep.kumar', 'Sandeep Kumar', 'Hong Kong bartender and co-owner of The Wise King. Before it he built drinks programmes at Shangri-La hotels, ON Dining, Il Milione and China Tang. In 2024 he opened a second Soho bar, The Blind Spot, on Aberdeen Street.', NULL, 'Hong Kong'),
    ('sarah.ruiz', 'Sarah Ruiz', 'Bar director and one of three partners at Juliana in Guayaquil, running the beverage programme behind its Ecuadorian-ingredient menus. She joined from San Francisco''s Pacific Cocktail Haven.', NULL, 'Guayaquil'),
    ('sarah.fischer', 'Sarah S. Fischer', 'Bar manager at Velvet in Berlin-Neukölln. Named Barwoman of the Year by Falstaff in 2023 and a member of the Mixology Bar Awards main jury since mid-2024.', NULL, 'Berlin'),
    ('scott.baird', 'Scott Baird', 'Bartender and co-founder of Bon Vivants and Trick Dog alongside Josh Harris. Their business partnership ended around 2017.', NULL, 'San Francisco'),
    ('scotty.schuder', 'Scotty Schuder', 'Bartender and owner of Dirty Dick, which he opened in Paris in 2013. Known as a key figure in the modern tiki revival for sticking closely to original Don the Beachcomber formulas with fresh fruit and house syrups.', NULL, 'Paris'),
    ('sean.muldoon', 'Sean Muldoon', 'Belfast bartender who co-founded The Dead Rabbit with Jack McGarry, then stepped back from running it in 2022 while keeping a shareholding. Earlier part of the team behind The Merchant Hotel bar in Belfast.', NULL, 'New York'),
    ('seba.garcia', 'Seba García', 'Buenos Aires bartender who created Presidente in Recoleta, where he supervises the bar and is known as its head bartender. Earlier he led the bar at the Nicky Harrison speakeasy in Palermo.', NULL, 'Buenos Aires'),
    ('sebastian.delacruz', 'Sebastian De La Cruz', 'Bartender and co-founder of Tropic City in Bangkok, which ran from late 2017 to April 2026. Earlier built drink menus for Bangkok venues UNCLE and Lady Brett with his later business partner.', NULL, 'Bangkok'),
    ('seven.yi', 'Seven Yi', 'Taipei bar and restaurant founder (Chinese name Yi Bai-xiang) who moved from molecular gastronomy into bartending. He built the Le Kief group, opening Room by Le Kief in 2018 and the dining venue MAD by Le Kief in 2022, with a focus on storytelling and food pairing.', NULL, 'Taipei'),
    ('shamim.ehsani', 'Shamim Ehsani', 'Co-founder of Tribe Hotels Group, which owns Nairobi''s Trademark Hotel, and the founder of Hero Bar. He shaped the bar''s comic-book concept and its aim to bring a new cocktail culture to Nairobi.', NULL, 'Nairobi'),
    ('shelby.allison', 'Shelby Allison', 'Co-owner of Lost Lake in Chicago''s Logan Square alongside Paul McGee, from its 2015 opening to its closure in January 2022.', NULL, 'Chicago'),
    ('shelley.tai', 'Shelley Tai', 'Hong Kong bartender who opened Mius on Gough Street in August 2025. She trained at Quinary under Antonio Lai, won Diageo World Class Hong Kong and Macau in 2019, and rose to operations director of Nutmeg Collective in Singapore before returning home.', NULL, 'Hong Kong'),
    ('simon.ahnberg', 'Simon Åhnberg', 'Restaurateur and co-owner of the 20-gruppen group that runs Tjoget, Liebling, Hornstulls Bodega and G.A.T. in Stockholm.', NULL, 'Stockholm'),
    ('simon.jimenez', 'Simon Jimenez', 'Managing bartender at Smuggler''s Cove, listed on the bar''s crew page.', NULL, 'San Francisco'),
    ('simone.rossi', 'Simone Rossi', 'Part of the opening mixology team at DarkSide in 2019 and later director of bars at Rosewood Hong Kong. He worked on the bar''s Martini VS Vesper.', NULL, 'Hong Kong'),
    ('snehal.patel', 'Snehal Patel', 'One of the three founding partners of 28 HongKong Street when it opened in 2011. Named alongside Spencer Forhart and Paul Gabie in the bar''s own retrospective.', NULL, 'Singapore'),
    ('sother.teague', 'Sother Teague', 'Bartender and former chef who co-opened Amor y Amargo in 2011 and now is a partner and beverage director at Overthrow Hospitality. He is a leading voice on amaro and bitters and co-hosted the radio show The Speakeasy.', NULL, 'New York'),
    ('spencer.amereno', 'Spencer Amereno Jr.', 'São Paulo bartender who ran the bar at Frank Bar in the Maksoud Plaza hotel from its 2015 opening until 2020, then led the drinks program at Guilhotina until 2023.', NULL, 'São Paulo'),
    ('spencer.forhart', 'Spencer Forhart', 'Co-founded 28 HongKong Street in 2011 after practising law in New York and moving to Singapore in 2007. Also co-founded Proof & Company, the craft spirits distributor and consultancy that grew out of the bar.', NULL, 'Singapore'),
    ('stefano.angelini', 'Stefano Angelini', 'Co-founder of Freni e Frizioni, the Trastevere bar opened in 2005 in a former car workshop.', NULL, 'Rome'),
    ('stelios.papadopoulos', 'Stelios Papadopoulos', 'Co-founder and owner of Barro Negro in Athens. Runs guest shifts at bars across Europe and helps lead the bar''s agave education programme.', NULL, 'Athens'),
    ('sumire.miyanohara', 'Sumire Miyanohara', 'Bartender who runs Bar Orchard Ginza together with her husband Takuo Miyanohara, and has competed in cocktail contests.', NULL, 'Tokyo'),
    ('summer.chen', 'Summer Chen', 'Bartender who worked in Singapore before returning to open Vender in Taichung in 2019 with Darren Lim. Her drinks draw on Southeast Asian ingredients.', NULL, 'Taichung'),
    ('supawit.muttarattana', 'Supawit Muttarattana', 'Bartender, known as Palm, with more than 20 years in the trade including a stint as a Diageo brand ambassador. He ran the bars at Vesper and Backstage, joined Rabbit Hole as beverage director in 2023 and opened Dry Wave in 2024.', NULL, 'Bangkok'),
    ('susan.fedroff', 'Susan Fedroff', 'Co-owner and co-founder of Clover Club with Julie Reiner, and a partner in The Saloon at Clover Club.', NULL, 'New York'),
    ('suwincha.singsuwan', 'Suwincha Singsuwan', 'Veteran Bangkok bartender from the Diageo World Class circuit, known as Chacha, who worked the bar at Rabbit Hole when it opened in 2016. Returned for its tenth-anniversary Homecoming in 2026.', NULL, 'Bangkok'),
    ('svaja.janeliunaite', 'Svajūnė Janeliūnaitė', 'Bar director at Le Syndicat, known as Svaja. Part of the team hosting its one-night residency at Bar Antoine in London in September 2026.', NULL, 'Paris'),
    ('takuma.watanabe', 'Takuma Watanabe', 'Opened Martiny''s in Gramercy in April 2022, bringing Japanese hospitality and classic cocktails to a carriage house. Eight years at Angel''s Share under Shingo Gokan before that. Later opened L''Americana (2024) and Midnight Blue (2024).', NULL, 'New York'),
    ('takuo.miyanohara', 'Takuo Miyanohara', 'Owner and bartender of Bar Orchard Ginza. A former sommelier at Hotel Okura Kobe, he moved to the bar and later opened his own place in Ginza, known for cocktails made from fresh fruit.', NULL, 'Tokyo'),
    ('tash.conte', 'Tash Conte', 'Owner of Black Pearl on Brunswick Street, Fitzroy, which opened in August 2002 and has been run by her since. It is one of Australia''s best known cocktail bars and a training ground for many Melbourne bartenders.', NULL, 'Melbourne'),
    ('terry.kim', 'Terry Kim', 'Owner and founder of Alice Cheongdam (Korean name Kim Yong-joo), which he opened in April 2015 after working in hotel bars including Grand Hyatt and JW Marriott. Named Korea''s top bartender in 2015 in local press.', NULL, 'Seoul'),
    ('tess.anne.sawyer', 'Tess Anne Sawyer', 'Named beverage director of the Spare Room for its late-2021 reopening, with a menu mixing classic riffs and Korean-inflected drinks.', NULL, 'Los Angeles'),
    ('tess.posthumus', 'Tess Posthumus', 'Amsterdam bartender who founded Flying Dutchmen Cocktails with Timo Janse and now owns it with Rosa Moolenaar and Alina Lucia, focusing on strategy, creation and education. Board member of the Tales of the Cocktail Foundation and a long-time organiser of Amsterdam Cocktail Week.', NULL, 'Amsterdam'),
    ('thanos.krimpouras', 'Thanos Krimpouras', 'Co-founder of Naked Athens (NKD), with a background in bartending, service and concept development.', NULL, 'Athens'),
    ('theo.quinn', 'Theo Quinn', 'Bartender who co-founded FOCO in Barcelona''s Gràcia with Tom Godfrey. He previously worked at Paradiso and Two Schmucks.', NULL, 'Barcelona'),
    ('thomas.girard', 'Thomas Girard', 'Bartender who led Operation Dagger from September 2019 and ran its Dagger Lab pop-up at Straits Clan after the original bar closed. Before Singapore he worked at 69 Colebrooke Row in London.', NULL, 'Singapore'),
    ('thor.bergquist', 'Thor Bergquist', 'Co-owner of PS40 and PS Soda in Sydney. Earlier worked at Der Raum in Melbourne, Tippling Club in Singapore and Experimental Cocktail Club in London and New York.', NULL, 'Sydney'),
    ('tibor.krascsenics', 'Tibor Krascsenics', 'Beverage director for La Petite Maison group (LPM), overseeing bar programmes at its venues including Dubai, London Mayfair and Limassol. He joined the group in 2015, when it had two venues, and has developed its themed Deja Vu cocktail menu.', NULL, 'Dubai'),
    ('tiger.chang', 'Tiger Chang', 'Leads the bar program at MO Bar in Mandarin Oriental, Shenzhen, and wrote its Colours of China menu. Built his career in hotel bars in Taipei and worked in bars across mainland China and elsewhere in Asia.', NULL, 'Shenzhen'),
    ('tim.philipsjohansson', 'Tim Philips-Johansson', 'Sydney bartender who co-founded Bulletin Place and its sister bar Dead Ringer. Won the Diageo World Class global title in 2012 and later worked in beverage leadership for a hospitality group.', NULL, 'Sydney'),
    ('timo.janse', 'Timo Janse', 'Amsterdam bartender who co-founded Flying Dutchmen Cocktails with Tess Posthumus. Their partnership ended on 1 June 2025, after which he took over leadership of Dutch Courage and of Amsterdam Cocktail Week and the Perfect Serve Barshow with a third partner.', NULL, 'Amsterdam'),
    ('timothee.prange', 'Timothée Prangé', 'Co-owner and founder of Little Red Door, which opened in 2012 and became a fixture of The World''s 50 Best Bars. He left in 2024 when the bar changed hands.', NULL, 'Paris'),
    ('toby.cecchini', 'Toby Cecchini', 'New York bartender and author of Cosmopolitan: A Bartender''s Life. Credited with the Cosmopolitan, created at the Odeon in 1988, and opened Passerby in Chelsea before co-restoring The Long Island Bar in 2013.', NULL, 'New York'),
    ('tom.godfrey', 'Tom Godfrey', 'Bartender who co-founded FOCO in Barcelona''s Gràcia with Theo Quinn. He previously worked at Paradiso and Two Schmucks.', NULL, 'Barcelona'),
    ('tom.hearn', 'Tom Hearn', 'Bartender who leads the bar programme at Vesper and its sister bar 4th Wall in Bangkok. He came up through the American Bar at The Savoy in London and designed Vesper''s 2025 Britain Through Seasons menu.', NULL, 'Bangkok'),
    ('tom.macy', 'Tom Macy', 'Longtime Clover Club bartender who rose from barback to head bartender and is now a partner and creative voice for the bar.', NULL, 'New York'),
    ('tommaso.cecca', 'Tommaso Cecca', 'Store manager and head bartender at Camparino in Galleria since 2018. Came up through London bars, then ran the bar at a Milan fashion-house restaurant and spent about ten years at Trussardi alla Scala before joining Camparino.', NULL, 'Milan'),
    ('tony.conigliaro', 'Tony Conigliaro', 'London bartender and drinks researcher who opened 69 Colebrooke Row and founded the Drink Factory lab. Also behind Bar Termini in Soho and Untitled Drinks in Dalston. Author of The Cocktail Lab.', NULL, 'London'),
    ('tony.yoshida', 'Tony Yoshida', 'Founded Angel''s Share in the East Village in 1993 (full name Tadao Yoshida). The bar brought Japanese bartending etiquette and precision to New York and influenced Sasha Petraske and others.', NULL, 'New York'),
    ('tyson.buhler', 'Tyson Buhler', 'Beverage director at Death & Co who led the menu at the Los Angeles opening. Trained as a chef, opened Leyenda with Ivy Mix and Julie Reiner and previously ran the bar program at Ristorante Morini.', NULL, 'Los Angeles'),
    ('victor.garibay', 'Víctor Garibay', 'Founder and director of Rayo, which opened in Mexico City in 2022 with a focus on Mexican spirits. He has said he wants to build one of the largest collections of Mexican spirits in the world.', NULL, 'Mexico City'),
    ('victor.yang', 'Victor Yang', 'Bartender and co-founder of AHA Saloon, winner of Diageo World Class Taiwan in 2013, with more than two decades behind the bar.', NULL, 'Taipei'),
    ('vijay.mudaliar', 'Vijay Mudaliar', 'Singapore bartender and owner of Native, which he opened in 2016 around locally sourced ingredients, and of the plant-based Analogue Initiative, which opened in 2021. Trained at Operation Dagger under Luke Whearty.', NULL, 'Singapore'),
    ('vlad.tcaci', 'Vlad Tcaci', 'Bar manager of the relaunched Nu Lounge in Bologna, where he directs the drinks programme. Previously bar manager at Bamboo.', NULL, 'Bologna'),
    ('walter.meyenberg', 'Walter Meyenberg', 'Mexico City hospitality owner behind Hanky Panky, Brujas and Palapa Cantina, and earlier the mezcal bar La Botica. In 2024 he formed the MWA bar group with Maura and Alex Lawrence Milia.', NULL, 'Mexico City'),
    ('will.pasternak', 'Will Pasternak', 'Former BlackTail head bartender who led the 2024 three-month BlackTail pop-up revival at Back Bar''s Hidden Bar.', NULL, 'New York'),
    ('william.elliott', 'William Elliott', 'Longtime managing partner and executive bar director at Maison Premiere, and co-author of The Maison Premiere Almanac (2023). Part of the original bar team.', NULL, 'New York'),
    ('xin.lin', 'Xin Lin', 'Co-founder of Electric Bing Sutt and Dead End Paradise in Beirut, working alongside Jad Ballout and Andre Gerges. Listed as a founding partner of the Beirut tiki bar.', NULL, 'Beirut'),
    ('yael.vengroff', 'Yael Vengroff', 'Bartender and beverage director who ran the Spare Room''s program from 2015 and later ran programs at several LA venues. Won the first Speed Rack in 2012.', NULL, 'Los Angeles'),
    ('yangdup.lama', 'Yangdup Lama', 'Delhi bartender, author and educator who co-founded Sidecar in 2018 with Minakshi Singh. He also runs Cocktails & Dreams Speakeasy and has opened bars including The Brook and Bar Stormy.', NULL, 'New Delhi'),
    ('yao.lu', 'Yao Lu', 'Shanghai bartender and co-founder of Union Trading Company, opened in 2014. Started at Anvil Bar & Refuge in Houston, later opened the tropical bar Birds of Paradise and launched the consultancy SM&Co.', NULL, 'Shanghai'),
    ('yuya.nagamine', 'Yuya Nagamine', 'Beverage director at SG Group, listed on the group''s own team page alongside the head bartender. Oversees the drinks program across the group''s venues, including The SG Club.', NULL, 'Tokyo'),
    ('zana.mohlmann', 'Zana Möhlmann', 'Head bartender at Manhattan in Singapore since 2024, unifying the bar''s rickhouse, guest-bartender program and American cocktail heritage. Won the 2023 World Young Mixologist Award.', NULL, 'Singapore'),
    ('zara.madrusan', 'Zara Madrusan', 'Co-owner of The Everleigh with Michael Madrusan, joining the bar in 2013. She ran the Made in the Shade Group with him and co-authored the 2025 book The Madrusan Cocktail Companion.', NULL, 'Melbourne')
) AS v ("handle", "name", "bio", "website", "city")
ON CONFLICT ("handle") DO NOTHING;

