) AS v("handle", "name", "description", "riff_of", "origin_year", "creator")
JOIN "public"."profiles" p ON p.handle = v.handle AND p.kind = 'bar'
LEFT JOIN "public"."items" c ON c.is_catalog AND lower(c.name) = lower(v.riff_of::text)
LEFT JOIN "public"."profiles" m ON m.handle = v.creator::text AND m.kind = 'person'
-- Once per bar and name, so re-running adds nothing.
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."items" i
    WHERE i.origin_bar_profile_id = p.id AND lower(i.name) = lower(v.name)
);

